// Modify these values to customize camera behavior, colors, lighting, materials, etc.
//
// Constants are organized by category:
// - CAMERA: Zoom, limits, FOV, positioning
// - MULTI_BODY_COLORS: Color palette for multi-body assemblies
// - MATERIALS: Alpha, metallic, roughness, RGB colors
// - LIGHTING: Intensities, positions, colors for all lights
// - ANIMATION: Speeds, durations, timing factors
// - GRID_AXIS: Sizes, colors, opacity for grid and axis gizmo
// - EDGE_RENDERING: Widths, colors, detection thresholds
// - OTHER: Scale tolerances, retry delays, thresholds
// ============================================================================

