function isViewerDebugEnabled() {
    try {
        return globalThis.localStorage?.getItem('malievViewerDebug') === 'true';
    } catch {
        return false;
    }
}

function debugLog(...args) {
    if (isViewerDebugEnabled()) {
        console.debug(...args);
    }
}

function configureBabylonLogger() {
    try {
        if (globalThis.BABYLON?.Logger) {
            BABYLON.Logger.LogLevels = BABYLON.Logger.WarningLogLevel | BABYLON.Logger.ErrorLogLevel;
        }
    } catch {
        // Logger configuration is best-effort; viewer initialization should continue.
    }
}

configureBabylonLogger();

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

/**
 * Convert CONFIG color object to BABYLON.Color3
 * @param {{r:number, g:number, b:number}} color - Color object with r,g,b properties
 * @returns {BABYLON.Color3} BabylonJS Color3 object
 */
function toColor3(color) {
    return new BABYLON.Color3(color.r, color.g, color.b);
}

/**
 * Convert CONFIG color object with alpha to BABYLON.Color4
 * @param {{r:number, g:number, b:number, a:number}} color - Color object with r,g,b,a properties
 * @returns {BABYLON.Color4} BabylonJS Color4 object
 */
function toColor4(color) {
    return new BABYLON.Color4(color.r, color.g, color.b, color.a);
}

/**
 * Convert CONFIG vector object to BABYLON.Vector3
 * @param {{x:number, y:number, z:number}} vector - Vector object with x,y,z properties
 * @returns {BABYLON.Vector3} BabylonJS Vector3 object
 */
function toVector3(vector) {
    return new BABYLON.Vector3(vector.x, vector.y, vector.z);
}

/**
 * Projects a 3D world position to 2D screen coordinates and positions an HTML element there.
 * Used for floating labels that follow 3D points (measure tool, thickness analysis).
 * @param {HTMLElement} div - The HTML element to position
 * @param {BABYLON.Vector3} worldPos - The 3D world position to track
 * @param {string} canvasId - Canvas identifier
 */
function updateLabelPosition(div, worldPos, canvasId) {
    const cam = mainCameras[canvasId];
    const engine = engines[canvasId];
    if (!cam || !engine) return;
    const canvas = engine.getRenderingCanvas();
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const rw = engine.getRenderWidth(), rh = engine.getRenderHeight();
    const viewProj = cam.getViewMatrix().multiply(cam.getProjectionMatrix());
    const p = BABYLON.Vector3.Project(
        worldPos, BABYLON.Matrix.Identity(), viewProj,
        cam.viewport.toGlobal(rw, rh)
    );
    if (p.z >= 0 && p.z <= 1) {
        div.style.left = (rect.left + (p.x / rw) * rect.width) + 'px';
        div.style.top  = (rect.top  + (p.y / rh) * rect.height) + 'px';
        div.style.display = '';
    } else {
        div.style.display = 'none';
    }
}

