// ── Per-canvas state ──────────────────────────────────────────────────────────
// ── Section-view state ───────────────────────────────────────────────────────
const sectionEdgeMeshes     = {};   // canvasId → BABYLON.LinesMesh | null
const sectionHatchMeshes    = {};   // canvasId → BABYLON.LinesMesh | null (cross-hatch fill)
const sectionFillMeshes     = {};   // canvasId → BABYLON.Mesh | null (light-pink section cap)
const sectionGhostMeshes    = {};   // canvasId → BABYLON.Mesh[] (xray clones of hidden half)
const sectionObservers      = {};   // canvasId → scene.onBeforeRenderObservable handle
const sectionClipPlanes     = {};   // canvasId → active model-material clipping plane | null
let   _sectionRebuildPending = {};  // canvasId → boolean (debounce flag)

// In-memory GLB cache: key = storage path (without signed-URL query params), value = blob URL.
// Allows instant re-render when switching back to a previously loaded part.
const _glbBlobCache = new Map(); // Map<pathKey, blobUrl>
const _GLB_CACHE_MAX = 8;
function _glbCacheKey(url) {
    try { return new URL(url).pathname; } catch (_) { return url; }
}
async function _fetchGlbCached(url) {
    const key = _glbCacheKey(url);
    if (_glbBlobCache.has(key)) return _glbBlobCache.get(key);
    const resp = await fetch(url);
    if (!resp.ok) throw new Error(`GLB fetch ${resp.status}`);
    const buf = await resp.arrayBuffer();
    const blobUrl = URL.createObjectURL(new Blob([buf], { type: 'model/gltf-binary' }));
    if (_glbBlobCache.size >= _GLB_CACHE_MAX) {
        const oldKey = _glbBlobCache.keys().next().value;
        URL.revokeObjectURL(_glbBlobCache.get(oldKey));
        _glbBlobCache.delete(oldKey);
    }
    _glbBlobCache.set(key, blobUrl);
    return blobUrl;
}

const engines               = {};   // canvasId → BABYLON.Engine
const scenes                = {};   // canvasId → BABYLON.Scene
const mainCameras           = {};   // canvasId → main ArcRotateCamera  (FIX: replaces scene.activeCamera)
const darkModes             = {};   // canvasId → boolean
const modelLoadState        = {};   // canvasId → 'loading' | 'loaded' | 'error'
const originalMaterials     = {};   // canvasId → { mesh.uniqueId → original material }
const defaultSolidMaterials = {};   // canvasId → Map<uniqueId, BABYLON.Material> — immutable baseline captured at load time
const flippedTriangleMaterials = {}; // canvasId → { mesh.uniqueId → ShaderMaterial for flipped detection }
const measureStates          = {};   // canvasId → { active, pointA, pointB, normalA, normalB, lines[], labels[], observer }
const thicknessStates        = {};   // canvasId → { active, line, label, sphere, observer }
const sceneBoundingBoxes    = {};   // canvasId → { min:{x,y,z}, max:{x,y,z} } world coords (Z-up, mm)
const meshCenters           = {};   // canvasId → { x, y, z } world center after centering
const modelScaleFactors     = {};   // canvasId → number (scale applied to main model root nodes)
const modelCenterOffsets    = {};   // canvasId → { cx, cy, zLift } (centering applied to main model root nodes)
const bboxLines             = {};   // canvasId → BABYLON.LinesMesh
const bboxLabels            = {};   // canvasId → [ { div, worldPos } ]
const bboxObservers         = {};   // canvasId → scene render observable handle
const turningAxisLayers     = {};   // canvasId → { svg, labels, pointerObserver, renderObserver, hovered }
const turningAxisRequests   = {};   // canvasId → latest requested turning-axis payload
const TURNING_AXIS_HOVER_DISTANCE_PX = 14;
const TURNING_AXIS_MAX_VERTEX_SAMPLES = 18000;
const TURNING_AXIS_RING_MIN_POINTS = 10;
const TURNING_AXIS_MIN_RING_COVERAGE = 0.42;
const TURNING_AXIS_MIN_CENTER_SCORE = 12;
const TURNING_AXIS_RELIABLE_RING_COVERAGE = 0.72;
const TURNING_AXIS_RELIABLE_RING_RESIDUAL_RATIO = 0.04;
const axisGizmoLayer        = {};   // canvasId → { dispose() }
const axisLabelDivs         = {};   // canvasId → [ { div, localPos } ]
const axisMouseHandlers     = {};   // canvasId → mousemove handler function
const resizeObservers       = {};   // canvasId → ResizeObserver
const cameraProjection      = {};   // canvasId → 'perspective' | 'orthographic'
const orthoZoomObservers    = {}; // canvasId → onViewMatrixChangedObservable handle
const perspZoomObservers    = {}; // canvasId → onViewMatrixChangedObservable handle (perspective)
const fitRadiusMap          = {};   // canvasId → initial camera radius from fitCameraToMesh
const modelFitRadiusMap     = {};   // canvasId → model-only fit radius, restored when floor helpers are hidden
const cuttingMatFrameBoundsMap = {}; // canvasId → union bounds used while the cutting mat is visible
const orthoZoomFactors      = {};   // canvasId -> zoom factor (1.0 = full view, shrinks on zoom in)
const edgeZoomObservers     = {};   // canvasId → onViewMatrixChangedObservable handle for dynamic edge width
const perCanvasBodyMap      = {};   // canvasId → Map<bodyIndex, {rootNode, meshes[], colorMaterial, name}>
const selectedBodyIndices   = {};   // canvasId → currently selected body index (null = none selected)
const loadGenerations       = {};   // canvasId → number (incremented on each initialize, checked in retry callbacks to cancel stale loads)
const shadowGenerators      = {};   // canvasId → BABYLON.ShadowGenerator
const analysisModelMeshIds  = {};   // canvasId → Set<mesh.uniqueId> for real model geometry
const analysisCameraButtons = {};   // canvasId → previous ArcRotate pointer buttons while analysis tools are active
const localAdvisoryRuns     = {};   // canvasId → latest local advisory run id
const localAdvisoryWorkers  = {};   // canvasId → active geometry worker

// ── Auto-rotation animation state ────────────────────────────────────────────
const edgesEnabled          = {};  // canvasId → boolean
const animStates            = {};  // canvasId → 'idle' | 'hovering' | 'interacting'
const autoSpeedCurrent      = {};  // canvasId → current alpha increment per frame (lerped)
const autoSpeedTarget       = {};  // canvasId → target alpha increment
const SPEED_IDLE            = CONFIG.AUTO_ROTATION_SPEED_IDLE;
const SPEED_HOVER           = CONFIG.AUTO_ROTATION_SPEED_HOVER;
const SPEED_STOP            = CONFIG.AUTO_ROTATION_SPEED_STOP;
const ORTHO_RADIUS_FACTOR   = 0.45; // fraction of cam.radius used for orthographic viewport half-height (≈ tan(FOV/2) to match perspective zoom)
const _arcAnimGuard         = {};   // canvasId → bool — suppresses the ortho observer during arc animations
const LOCAL_ADVISORY_MANIFEST_URL = '/api/v1/geometry/runtime/manifest';
const LOCAL_ADVISORY_ASSET_BASE_URL = '/api/v1/geometry/runtime/assets/';
const LOCAL_ADVISORY_FRONTEND_API_VERSION = 1;

// ── Helpers ───────────────────────────────────────────────────────────────────

function loadScript(url) {
    return new Promise((resolve, reject) => {
        if (Array.from(document.scripts).some(script => script.src === url)) { resolve(); return; }
        const script = document.createElement('script');
        script.type = 'text/javascript'; script.src = url;
        script.onload = resolve;
        script.onerror = () => reject(new Error(`Failed to load: ${url}`));
        document.head.appendChild(script);
    });
}

/**
 * World bounding box of all non-system meshes (excludes __grid__, __axis*).
 */
function computeSceneBounds(scene) {
    let minX = Infinity, minY = Infinity, minZ = Infinity;
    let maxX = -Infinity, maxY = -Infinity, maxZ = -Infinity;
    scene.meshes.forEach(m => {
        if (m.name === '__grid__' || m.name === '__shadow_catcher__' || m.name.startsWith('__axis') || m.name.startsWith('__cutting_mat')) return;
        m.computeWorldMatrix(true);
        const bi = m.getBoundingInfo();
        const lo = bi.boundingBox.minimumWorld, hi = bi.boundingBox.maximumWorld;
        minX = Math.min(minX, lo.x); minY = Math.min(minY, lo.y); minZ = Math.min(minZ, lo.z);
        maxX = Math.max(maxX, hi.x); maxY = Math.max(maxY, hi.y); maxZ = Math.max(maxZ, hi.z);
    });
    if (!isFinite(minX)) return null;
    return { min: { x: minX, y: minY, z: minZ }, max: { x: maxX, y: maxY, z: maxZ } };
}

function toWorldPoint(point) {
    return new BABYLON.Vector3(point.x, point.y, point.z);
}

function normalizeViewerSettings(viewerSettings) {
    const settings = viewerSettings && typeof viewerSettings === 'object' ? viewerSettings : {};
    const renderMode = settings.renderMode === 'solid'
        || settings.renderMode === 'wireframe'
        || settings.renderMode === 'transparent'
        || settings.renderMode === 'realistic'
        ? settings.renderMode
        : 'realistic';
    const cameraMode = settings.cameraProjection === 'perspective'
        ? 'perspective'
        : 'orthographic';
    const sectionAxis = settings.sectionAxis === 'y' || settings.sectionAxis === 'z'
        ? settings.sectionAxis
        : 'x';
    const materialType = CONFIG.MATERIAL_REALISTIC[settings.materialType]
        ? settings.materialType
        : 'aluminum';

    return {
        renderMode,
        cameraProjection: cameraMode,
        edgesEnabled: !!settings.edgesEnabled && renderMode !== 'wireframe',
        gridEnabled: !!settings.gridEnabled,
        boundingBoxEnabled: !!settings.boundingBoxEnabled,
        sectionEnabled: !!settings.sectionEnabled,
        sectionAxis,
        sectionOffsetMm: Number.isFinite(Number(settings.sectionOffsetMm)) ? Number(settings.sectionOffsetMm) : 0,
        sectionInverted: !!settings.sectionInverted,
        materialType,
        processCode: typeof settings.processCode === 'string'
            ? settings.processCode
            : (typeof settings.processId === 'string' ? settings.processId : null),
    };
}

function normalizeAxisVector(axisVector) {
    if (!Array.isArray(axisVector) || axisVector.length < 3) return null;

    const direction = new BABYLON.Vector3(
        Number(axisVector[0]),
        Number(axisVector[1]),
        Number(axisVector[2])
    );
    if (!isFinite(direction.x) || !isFinite(direction.y) || !isFinite(direction.z) || direction.length() < 1e-6) {
        return null;
    }

    return direction.normalize();
}

function transformBackendAxisPoint(canvasId, axisPoint) {
    if (!Array.isArray(axisPoint) || axisPoint.length < 3) return null;

    const sourcePoint = new BABYLON.Vector3(
        Number(axisPoint[0]),
        Number(axisPoint[1]),
        Number(axisPoint[2])
    );
    if (!isFinite(sourcePoint.x) || !isFinite(sourcePoint.y) || !isFinite(sourcePoint.z)) {
        return null;
    }

    const scaleFactor = modelScaleFactors[canvasId] ?? 1;
    const scaled = sourcePoint.scale(scaleFactor);
    const rotated = BABYLON.Vector3.TransformCoordinates(scaled, BABYLON.Matrix.RotationX(Math.PI / 2));
    const offset = modelCenterOffsets[canvasId] ?? { cx: 0, cy: 0, zLift: 0 };
    return new BABYLON.Vector3(
        rotated.x - offset.cx,
        rotated.y - offset.cy,
        rotated.z + offset.zLift
    );
}

function directionFromPrimaryAxis(primaryAxis) {
    const axis = String(primaryAxis || '').toUpperCase();
    if (axis === 'X') return new BABYLON.Vector3(1, 0, 0);
    if (axis === 'Y') return new BABYLON.Vector3(0, 1, 0);
    if (axis === 'Z') return new BABYLON.Vector3(0, 0, 1);
    return null;
}

function detectTurningAxisDirectionFromBounds(bb) {
    const x = Math.abs(bb.max.x - bb.min.x);
    const y = Math.abs(bb.max.y - bb.min.y);
    const z = Math.abs(bb.max.z - bb.min.z);

    if (x >= y && x >= z) return new BABYLON.Vector3(1, 0, 0);
    if (y >= x && y >= z) return new BABYLON.Vector3(0, 1, 0);
    return new BABYLON.Vector3(0, 0, 1);
}

function getBoundingBoxCorners(bb) {
    const min = toWorldPoint(bb.min);
    const max = toWorldPoint(bb.max);
    return [
        new BABYLON.Vector3(min.x, min.y, min.z),
        new BABYLON.Vector3(min.x, min.y, max.z),
        new BABYLON.Vector3(min.x, max.y, min.z),
        new BABYLON.Vector3(min.x, max.y, max.z),
        new BABYLON.Vector3(max.x, min.y, min.z),
        new BABYLON.Vector3(max.x, min.y, max.z),
        new BABYLON.Vector3(max.x, max.y, min.z),
        new BABYLON.Vector3(max.x, max.y, max.z),
    ];
}

function isSystemMeshForTurningAxis(mesh, canvasId) {
    if (!mesh || !mesh.name) return true;
    if (mesh.name === '__grid__' || mesh.name === '__shadow_catcher__') return true;
    if (mesh.name.startsWith('__axis') || mesh.name.startsWith('bbox_')) return true;
    if (mesh.name.startsWith('__cutting_mat')) return true;
    if (mesh.name.startsWith('__flipped_overlay__') || mesh.name.startsWith('measure_')) return true;

    const directOverlayMap = overlayMeshes?.[canvasId];
    if (directOverlayMap instanceof Map) {
        for (const [, meshArr] of directOverlayMap) {
            if (meshArr?.some(m => m.uniqueId === mesh.uniqueId)) return true;
        }
    }

    const prefix = `${canvasId}::`;
    for (const key of Object.keys(overlayMeshes ?? {})) {
        if (!key.startsWith(prefix) || !(overlayMeshes[key] instanceof Map)) continue;
        for (const [, meshArr] of overlayMeshes[key]) {
            if (meshArr?.some(m => m.uniqueId === mesh.uniqueId)) return true;
        }
    }

    return false;
}

function collectTurningAxisSamplePoints(scene, canvasId) {
    const points = [];
    const candidateMeshes = scene.meshes.filter(mesh =>
        !isSystemMeshForTurningAxis(mesh, canvasId)
        && mesh.getVerticesData
        && mesh.getVerticesData(BABYLON.VertexBuffer.PositionKind)
        && mesh.getTotalVertices?.() > 0
    );

    const totalVertices = candidateMeshes.reduce((sum, mesh) => sum + (mesh.getTotalVertices?.() ?? 0), 0);
    const globalStep = Math.max(1, Math.ceil(totalVertices / TURNING_AXIS_MAX_VERTEX_SAMPLES));

    candidateMeshes.forEach(mesh => {
        const positions = mesh.getVerticesData(BABYLON.VertexBuffer.PositionKind);
        if (!positions) return;

        mesh.computeWorldMatrix(true);
        const matrix = mesh.getWorldMatrix();
        for (let i = 0; i < positions.length; i += 3 * globalStep) {
            points.push(BABYLON.Vector3.TransformCoordinates(
                new BABYLON.Vector3(positions[i], positions[i + 1], positions[i + 2]),
                matrix
            ));
        }
    });

    return points;
}

function buildAxisBasis(direction) {
    let helper = Math.abs(BABYLON.Vector3.Dot(direction, BABYLON.Axis.Z)) < 0.9
        ? BABYLON.Axis.Z
        : BABYLON.Axis.Y;
    let u = BABYLON.Vector3.Cross(direction, helper);
    if (u.length() < 1e-6) {
        helper = BABYLON.Axis.X;
        u = BABYLON.Vector3.Cross(direction, helper);
    }

    u.normalize();
    const v = BABYLON.Vector3.Cross(direction, u).normalize();
    return { u, v };
}

function solve3x3(matrix, rhs) {
    const a = matrix.map((row, index) => [...row, rhs[index]]);

    for (let col = 0; col < 3; col += 1) {
        let pivot = col;
        for (let row = col + 1; row < 3; row += 1) {
            if (Math.abs(a[row][col]) > Math.abs(a[pivot][col])) pivot = row;
        }

        if (Math.abs(a[pivot][col]) < 1e-9) return null;
        if (pivot !== col) [a[col], a[pivot]] = [a[pivot], a[col]];

        const divisor = a[col][col];
        for (let j = col; j < 4; j += 1) a[col][j] /= divisor;

        for (let row = 0; row < 3; row += 1) {
            if (row === col) continue;
            const factor = a[row][col];
            for (let j = col; j < 4; j += 1) {
                a[row][j] -= factor * a[col][j];
            }
        }
    }

    return [a[0][3], a[1][3], a[2][3]];
}

function unique2DPoints(points, tolerance) {
    const unique = new Map();
    points.forEach(point => {
        const key = `${Math.round(point.x / tolerance)},${Math.round(point.y / tolerance)}`;
        if (!unique.has(key)) unique.set(key, point);
    });
    return [...unique.values()];
}

function fitCircle2D(points) {
    if (points.length < TURNING_AXIS_RING_MIN_POINTS) return null;

    let sA = 0, sB = 0, sC = 0, sD = 0, sE = 0, sF = 0;
    let rA = 0, rB = 0, rC = 0;
    points.forEach(point => {
        const a = 2 * point.x;
        const b = 2 * point.y;
        const c = 1;
        const rhs = point.x * point.x + point.y * point.y;
        sA += a * a;
        sB += a * b;
        sC += a * c;
        sD += b * b;
        sE += b * c;
        sF += c * c;
        rA += a * rhs;
        rB += b * rhs;
        rC += rhs;
    });

    const solved = solve3x3(
        [[sA, sB, sC], [sB, sD, sE], [sC, sE, sF]],
        [rA, rB, rC]
    );
    if (!solved) return null;

    const [cx, cy, constant] = solved;
    const radiusSquared = cx * cx + cy * cy + constant;
    if (!isFinite(radiusSquared) || radiusSquared <= 1e-9) return null;

    const radius = Math.sqrt(radiusSquared);
    let residualSum = 0;
    const angles = [];
    points.forEach(point => {
        const dist = Math.hypot(point.x - cx, point.y - cy);
        residualSum += (dist - radius) * (dist - radius);
        angles.push(Math.atan2(point.y - cy, point.x - cx));
    });
    angles.sort((a, b) => a - b);

    let maxGap = 0;
    for (let i = 1; i < angles.length; i += 1) {
        maxGap = Math.max(maxGap, angles[i] - angles[i - 1]);
    }
    if (angles.length > 1) {
        maxGap = Math.max(maxGap, (angles[0] + Math.PI * 2) - angles[angles.length - 1]);
    }

    return {
        centerU: cx,
        centerV: cy,
        radius,
        residual: Math.sqrt(residualSum / points.length),
        coverage: Math.max(0, Math.min(1, (Math.PI * 2 - maxGap) / (Math.PI * 2))),
        count: points.length,
    };
}

function splitRadialPointGroups(points, centerU, centerV, tolerance) {
    const sorted = points
        .map(point => ({
            point,
            radius: Math.hypot(point.x - centerU, point.y - centerV),
        }))
        .sort((a, b) => a.radius - b.radius);

    const groups = [];
    let current = [];
    let previousRadius = null;

    sorted.forEach(entry => {
        if (previousRadius !== null
            && entry.radius - previousRadius > tolerance
            && current.length >= TURNING_AXIS_RING_MIN_POINTS) {
            groups.push(current.map(item => item.point));
            current = [];
        }

        current.push(entry);
        previousRadius = entry.radius;
    });

    if (current.length >= TURNING_AXIS_RING_MIN_POINTS) {
        groups.push(current.map(item => item.point));
    }

    return groups;
}

function buildCirclePointGroups(points, fallbackU, fallbackV, diagonal) {
    const groups = [points];
    const tolerance = Math.max(0.2, diagonal * 0.01);
    splitRadialPointGroups(points, fallbackU, fallbackV, tolerance)
        .forEach(group => groups.push(group));

    const mean = points.reduce(
        (acc, point) => ({ x: acc.x + point.x, y: acc.y + point.y }),
        { x: 0, y: 0 });
    mean.x /= points.length;
    mean.y /= points.length;
    splitRadialPointGroups(points, mean.x, mean.y, tolerance)
        .forEach(group => groups.push(group));

    return groups;
}

function getRingResidualRatio(ring) {
    return ring.residual / Math.max(ring.radius, 1e-6);
}

function getRingQuality(ring) {
    return Math.sqrt(ring.count)
        * ring.coverage
        / (1 + getRingResidualRatio(ring) * 12);
}

function isReliableTurningRing(ring) {
    return ring.coverage >= TURNING_AXIS_RELIABLE_RING_COVERAGE
        && getRingResidualRatio(ring) <= TURNING_AXIS_RELIABLE_RING_RESIDUAL_RATIO;
}

function addRingToCenterCluster(clusters, entry, tolerance) {
    let target = null;
    let bestDistance = Infinity;

    clusters.forEach(cluster => {
        const distance = Math.hypot(
            cluster.centerU - entry.ring.centerU,
            cluster.centerV - entry.ring.centerV);
        if (distance <= tolerance && distance < bestDistance) {
            target = cluster;
            bestDistance = distance;
        }
    });

    if (!target) {
        clusters.push({
            centerU: entry.ring.centerU,
            centerV: entry.ring.centerV,
            minRadius: entry.ring.radius,
            totalQuality: entry.quality,
            ringCount: 1,
        });
        return;
    }

    const totalQuality = target.totalQuality + entry.quality;
    target.centerU = ((target.centerU * target.totalQuality) + (entry.ring.centerU * entry.quality)) / totalQuality;
    target.centerV = ((target.centerV * target.totalQuality) + (entry.ring.centerV * entry.quality)) / totalQuality;
    target.minRadius = Math.min(target.minRadius, entry.ring.radius);
    target.totalQuality = totalQuality;
    target.ringCount += 1;
}

function selectTurningAxisCenterCluster(rings, diagonal) {
    const entries = rings
        .map(ring => ({ ring, quality: getRingQuality(ring), reliable: isReliableTurningRing(ring) }))
        .filter(entry => entry.quality > 0);
    if (entries.length === 0) return null;

    const reliableEntries = entries.filter(entry => entry.reliable);
    const source = reliableEntries.length > 0 ? reliableEntries : entries;
    const tolerance = Math.max(0.12, diagonal * 0.012);
    const clusters = [];

    source
        .sort((a, b) => a.ring.radius - b.ring.radius)
        .forEach(entry => addRingToCenterCluster(clusters, entry, tolerance));

    if (clusters.length === 0) return null;

    clusters.sort((a, b) => {
        if (reliableEntries.length > 0) {
            const radiusDelta = a.minRadius - b.minRadius;
            if (Math.abs(radiusDelta) > 1e-6) return radiusDelta;
        }

        return b.totalQuality - a.totalQuality;
    });

    const selected = clusters[0];
    return {
        centerU: selected.centerU,
        centerV: selected.centerV,
        score: selected.totalQuality,
        ringCount: selected.ringCount,
    };
}

function evaluateTurningAxisCandidate(points, direction, bb, fallbackCenter) {
    const normalizedDirection = direction.clone();
    normalizedDirection.normalize();
    const { u, v } = buildAxisBasis(normalizedDirection);
    const corners = getBoundingBoxCorners(bb);
    let minT = Infinity;
    let maxT = -Infinity;
    corners.forEach(corner => {
        const t = BABYLON.Vector3.Dot(corner, normalizedDirection);
        minT = Math.min(minT, t);
        maxT = Math.max(maxT, t);
    });

    const axisLength = Math.max(maxT - minT, 1);
    const diagonal = toWorldPoint(bb.max).subtract(toWorldPoint(bb.min)).length();
    const bucketSize = Math.max(0.08, Math.min(1.25, axisLength * 0.015));
    const uniqueTolerance = Math.max(0.02, diagonal * 0.0004);
    const minRadius = Math.max(0.04, diagonal * 0.002);
    const fallbackU = BABYLON.Vector3.Dot(fallbackCenter, u);
    const fallbackV = BABYLON.Vector3.Dot(fallbackCenter, v);
    const buckets = new Map();

    points.forEach(point => {
        const t = BABYLON.Vector3.Dot(point, normalizedDirection);
        const key = Math.round(t / bucketSize);
        if (!buckets.has(key)) buckets.set(key, []);
        buckets.get(key).push({
            x: BABYLON.Vector3.Dot(point, u),
            y: BABYLON.Vector3.Dot(point, v),
        });
    });

    const rings = [];
    for (const bucketPoints of buckets.values()) {
        if (bucketPoints.length < TURNING_AXIS_RING_MIN_POINTS) continue;

        const uniquePoints = unique2DPoints(bucketPoints, uniqueTolerance);
        if (uniquePoints.length < TURNING_AXIS_RING_MIN_POINTS) continue;

        const pointGroups = buildCirclePointGroups(uniquePoints, fallbackU, fallbackV, diagonal);
        pointGroups.forEach(group => {
            const sampledPoints = group.length > 220
                ? group.filter((_, index) => index % Math.ceil(group.length / 220) === 0)
                : group;
            const fit = fitCircle2D(sampledPoints);
            if (!fit || fit.radius < minRadius) return;

            const residualLimit = Math.max(0.22, fit.radius * 0.10);
            if (fit.coverage < TURNING_AXIS_MIN_RING_COVERAGE || fit.residual > residualLimit) return;

            rings.push(fit);
        });
    }

    if (rings.length === 0) {
        return {
            direction: normalizedDirection,
            center: fallbackCenter,
            score: 0,
            ringCount: 0,
        };
    }

    const selectedCluster = selectTurningAxisCenterCluster(rings, diagonal);
    if (!selectedCluster) {
        return {
            direction: normalizedDirection,
            center: fallbackCenter,
            score: 0,
            ringCount: 0,
        };
    }

    const axisMid = (minT + maxT) / 2;
    const center = u.scale(selectedCluster.centerU)
        .add(v.scale(selectedCluster.centerV))
        .add(normalizedDirection.scale(axisMid));

    return {
        direction: normalizedDirection,
        center,
        score: selectedCluster.score,
        ringCount: selectedCluster.ringCount,
    };
}

function resolveTurningAxis(scene, canvasId, primaryAxis, axisVector, axisPoint, bb, fallbackCenter) {
    const points = collectTurningAxisSamplePoints(scene, canvasId);
    const direction = normalizeAxisVector(axisVector)
        || directionFromPrimaryAxis(primaryAxis)
        || detectTurningAxisDirectionFromBounds(bb);
    const backendCenter = transformBackendAxisPoint(canvasId, axisPoint);
    const evaluated = evaluateTurningAxisCandidate(points, direction, bb, fallbackCenter);
    if (evaluated.score >= TURNING_AXIS_MIN_CENTER_SCORE && evaluated.ringCount > 0) {
        return {
            direction,
            center: evaluated.center,
            score: evaluated.score,
            ringCount: evaluated.ringCount,
        };
    }

    return {
        direction,
        center: backendCenter ?? fallbackCenter,
        score: evaluated.score,
        ringCount: evaluated.ringCount,
    };
}

function createTurningAxisLabel(text) {
    const div = document.createElement('div');
    div.textContent = text;
    div.style.position = 'fixed';
    div.style.zIndex = '10020';
    div.style.pointerEvents = 'none';
    div.style.padding = '5px 9px';
    div.style.border = '1px solid #2563eb';
    div.style.borderRadius = '4px';
    div.style.background = 'rgba(255, 255, 255, 0.96)';
    div.style.color = '#2563eb';
    div.style.font = '600 13px/1.2 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
    div.style.boxShadow = '0 4px 12px rgba(37, 99, 235, 0.16)';
    div.style.whiteSpace = 'nowrap';
    div.style.transform = 'translate(-50%, -130%)';
    div.style.display = 'none';
    document.body.appendChild(div);
    return div;
}

function createTurningAxisSvg() {
    const ns = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(ns, 'svg');
    svg.setAttribute('aria-hidden', 'true');
    svg.style.position = 'fixed';
    svg.style.left = '0';
    svg.style.top = '0';
    svg.style.width = '100vw';
    svg.style.height = '100vh';
    svg.style.overflow = 'visible';
    svg.style.pointerEvents = 'none';
    svg.style.zIndex = '10010';

    const line = document.createElementNS(ns, 'line');
    line.setAttribute('stroke', '#2563eb');
    line.setAttribute('stroke-width', '2');
    line.setAttribute('opacity', '0.45');
    line.setAttribute('stroke-linecap', 'round');
    line.setAttribute('stroke-dasharray', '9 7');

    svg.appendChild(line);
    document.body.appendChild(svg);

    return { svg, line };
}

function projectWorldPointToScreen(worldPos, canvasId) {
    const cam = mainCameras[canvasId];
    const engine = engines[canvasId];
    if (!cam || !engine) return null;

    const canvas = engine.getRenderingCanvas();
    if (!canvas) return null;

    const rect = canvas.getBoundingClientRect();
    const rw = engine.getRenderWidth();
    const rh = engine.getRenderHeight();
    const viewProj = cam.getViewMatrix().multiply(cam.getProjectionMatrix());
    const projected = BABYLON.Vector3.Project(
        worldPos,
        BABYLON.Matrix.Identity(),
        viewProj,
        cam.viewport.toGlobal(rw, rh)
    );

    if (projected.z < 0 || projected.z > 1) return null;
    return {
        x: rect.left + (projected.x / rw) * rect.width,
        y: rect.top + (projected.y / rh) * rect.height,
    };
}

function projectTurningAxisLabel(div, worldPos, canvasId, visible) {
    if (!visible) {
        div.style.display = 'none';
        return;
    }

    const projected = projectWorldPointToScreen(worldPos, canvasId);
    if (!projected) {
        div.style.display = 'none';
        return;
    }

    div.style.left = `${projected.x}px`;
    div.style.top = `${projected.y}px`;
    div.style.display = '';
}

function distancePointToSegmentPx(px, py, a, b) {
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const len2 = dx * dx + dy * dy;
    if (len2 <= 1e-6) return Math.hypot(px - a.x, py - a.y);

    const t = Math.max(0, Math.min(1, ((px - a.x) * dx + (py - a.y) * dy) / len2));
    const x = a.x + t * dx;
    const y = a.y + t * dy;
    return Math.hypot(px - x, py - y);
}

function isPointerNearTurningAxis(canvasId, state, pointerEvent) {
    const start = projectWorldPointToScreen(state.start, canvasId);
    const end = projectWorldPointToScreen(state.end, canvasId);
    if (!start || !end) return false;

    return distancePointToSegmentPx(
        pointerEvent.clientX,
        pointerEvent.clientY,
        start,
        end
    ) <= TURNING_AXIS_HOVER_DISTANCE_PX;
}

function updateTurningAxisSvg(canvasId, state) {
    const start = projectWorldPointToScreen(state.start, canvasId);
    const end = projectWorldPointToScreen(state.end, canvasId);

    if (!start || !end) {
        state.svg.style.display = 'none';
        state.labels.forEach(label => projectTurningAxisLabel(label.div, label.worldPos, canvasId, false));
        return;
    }

    state.svg.style.display = '';
    state.line.setAttribute('x1', start.x.toString());
    state.line.setAttribute('y1', start.y.toString());
    state.line.setAttribute('x2', end.x.toString());
    state.line.setAttribute('y2', end.y.toString());
    state.labels.forEach(label => projectTurningAxisLabel(label.div, label.worldPos, canvasId, state.hovered));
}

function buildTurningAxisGeometry(canvasId, primaryAxis, axisVector, axisPoint) {
    const scene = scenes[canvasId];
    const bb = sceneBoundingBoxes[canvasId];
    const centerData = meshCenters[canvasId];
    if (!scene || !bb || !centerData) return false;

    const fallbackCenter = toWorldPoint(centerData);
    const resolvedAxis = resolveTurningAxis(scene, canvasId, primaryAxis, axisVector, axisPoint, bb, fallbackCenter);
    const direction = resolvedAxis?.direction;
    if (!direction) {
        clearTurningAxis(canvasId, false);
        return false;
    }

    clearTurningAxis(canvasId, false);

    const center = resolvedAxis.center ?? fallbackCenter;
    const min = toWorldPoint(bb.min);
    const max = toWorldPoint(bb.max);
    const corners = getBoundingBoxCorners(bb);

    let minDot = Infinity;
    let maxDot = -Infinity;
    corners.forEach(corner => {
        const dot = BABYLON.Vector3.Dot(corner.subtract(center), direction);
        minDot = Math.min(minDot, dot);
        maxDot = Math.max(maxDot, dot);
    });

    const diagonal = max.subtract(min).length();
    const padding = Math.max(diagonal * 0.08, 8);
    const start = center.add(direction.scale(minDot - padding));
    const end = center.add(direction.scale(maxDot + padding));
    const length = BABYLON.Vector3.Distance(start, end);

    const overlay = createTurningAxisSvg();
    const axisLabel = createTurningAxisLabel('Axis of Turning');
    const labelPositions = [
        { div: axisLabel, worldPos: center.add(direction.scale(length * 0.10)) },
    ];

    const state = {
        svg: overlay.svg,
        line: overlay.line,
        labels: labelPositions,
        pointerObserver: null,
        renderObserver: null,
        canvasLeaveHandler: null,
        hovered: false,
        start,
        end,
    };

    state.pointerObserver = scene.onPointerObservable.add(pointerInfo => {
        if (pointerInfo.type !== BABYLON.PointerEventTypes.POINTERMOVE) return;
        state.hovered = pointerInfo.event
            ? isPointerNearTurningAxis(canvasId, state, pointerInfo.event)
            : false;
    });
    const canvas = engines[canvasId]?.getRenderingCanvas();
    if (canvas) {
        state.canvasLeaveHandler = () => { state.hovered = false; };
        canvas.addEventListener('pointerleave', state.canvasLeaveHandler);
    }
    state.renderObserver = scene.onBeforeRenderObservable.add(() => {
        updateTurningAxisSvg(canvasId, state);
    });
    updateTurningAxisSvg(canvasId, state);

    turningAxisLayers[canvasId] = state;
    return true;
}

export function setTurningAxis(canvasId, primaryAxis, axisVector, axisPoint) {
    turningAxisRequests[canvasId] = { primaryAxis, axisVector, axisPoint };
    buildTurningAxisGeometry(canvasId, primaryAxis, axisVector, axisPoint);
}

export function clearTurningAxis(canvasId, clearRequest = true) {
    const state = turningAxisLayers[canvasId];
    if (state) {
        const scene = scenes[canvasId];
        const canvas = engines[canvasId]?.getRenderingCanvas();
        if (state.pointerObserver && scene) scene.onPointerObservable.remove(state.pointerObserver);
        if (state.renderObserver && scene) scene.onBeforeRenderObservable.remove(state.renderObserver);
        if (state.canvasLeaveHandler && canvas) canvas.removeEventListener('pointerleave', state.canvasLeaveHandler);
        if (state.svg) { try { state.svg.remove(); } catch (_) {} }
        state.labels.forEach(({ div }) => { try { div.remove(); } catch (_) {} });
        delete turningAxisLayers[canvasId];
    }

    if (clearRequest) delete turningAxisRequests[canvasId];
}

/**
 * Resolves the BabylonJS loader extension from the caller-supplied hint or the URL path.
 * Falls back to extracting the extension from the URL before any query string.
 */
function resolveExtension(fileUrl, fileExt) {
    const known = ['.glb', '.gltf', '.stl', '.obj', '.3mf'];
    const lower = (fileExt || '').toLowerCase();
    if (known.includes(lower)) return lower;
    const path = (fileUrl || '').split('?')[0].toLowerCase();
    return known.find(e => path.endsWith(e)) ?? '';
}

/**
 * Camera fitting: set radius so the mesh is comfortably framed by the FOV.
 * @param {string|null} canvasId  When provided, stores the fit radius for dynamic edge scaling.
 */
function fitCameraToMesh(cam, bb, meshCenter, canvasId) {
    const w = bb.max.x - bb.min.x;
    const d = bb.max.y - bb.min.y;
    const h = bb.max.z - bb.min.z;
    const halfDiag = Math.sqrt(w * w + d * d + h * h) / 2;
    const fov = cam.fov || CONFIG.CAMERA_FOV;
    const meshRadius = Math.max(halfDiag / Math.tan(fov / 2) * 1.2, 1);

    // Z-up target: center horizontally, vertically at half-height
    cam.target = new BABYLON.Vector3(
        (bb.min.x + bb.max.x) / 2,
        (bb.min.y + bb.max.y) / 2,
        (bb.min.z + bb.max.z) / 2
    );
    cam.radius = meshRadius;
    cam.lowerRadiusLimit = meshRadius * CONFIG.CAMERA_LOWER_RADIUS_LIMIT;
    cam.upperRadiusLimit = meshRadius * CONFIG.CAMERA_UPPER_RADIUS_LIMIT;
    // Use wheelDeltaPercentage for consistent zoom speed across all model sizes
    cam.wheelDeltaPercentage = CONFIG.ZOOM_STEP_PERCENTAGE;
    cam.pinchPrecision = CONFIG.CAMERA_PINCH_PRECISION;
    cam.minZ = 0.1;
    cam.maxZ = meshRadius * CONFIG.CAMERA_FAR_PLANE;
    // Store initial radius for dynamic perspective edge width scaling
    if (canvasId != null) {
        fitRadiusMap[canvasId] = meshRadius;
        modelFitRadiusMap[canvasId] = meshRadius;
    }
}

function _fitRadiusForBounds(cam, bb) {
    const w = bb.max.x - bb.min.x;
    const d = bb.max.y - bb.min.y;
    const h = bb.max.z - bb.min.z;
    const halfDiag = Math.sqrt(w * w + d * d + h * h) / 2;
    const fov = cam.fov || CONFIG.CAMERA_FOV;
    return Math.max(halfDiag / Math.tan(fov / 2) * 1.2, 1);
}

function _centerForBounds(bb) {
    return new BABYLON.Vector3(
        (bb.min.x + bb.max.x) / 2,
        (bb.min.y + bb.max.y) / 2,
        (bb.min.z + bb.max.z) / 2
    );
}

function _applyCameraFitBounds(canvasId, bb) {
    const cam = mainCameras[canvasId];
    const engine = engines[canvasId];
    if (!cam || !bb) return;

    const previousFit = fitRadiusMap[canvasId] || cam.radius || 1;
    const nextFit = _fitRadiusForBounds(cam, bb);
    const previousZoom = cameraProjection[canvasId] === 'orthographic'
        ? (orthoZoomFactors[canvasId] || 1)
        : ((cam.radius || previousFit) / previousFit);
    const zoom = Math.max(previousZoom, 1);

    fitRadiusMap[canvasId] = nextFit;
    cam.target = _centerForBounds(bb);
    cam.radius = nextFit * zoom;
    cam.lowerRadiusLimit = nextFit * CONFIG.CAMERA_LOWER_RADIUS_LIMIT;
    cam.upperRadiusLimit = nextFit * CONFIG.CAMERA_UPPER_RADIUS_LIMIT;
    cam.maxZ = nextFit * CONFIG.CAMERA_FAR_PLANE;

    if (cameraProjection[canvasId] === 'orthographic' && engine) {
        orthoZoomFactors[canvasId] = zoom;
        const half = nextFit * zoom * ORTHO_RADIUS_FACTOR;
        const aspect = engine.getAspectRatio(cam);
        cam.orthoLeft = -half * aspect;
        cam.orthoRight = half * aspect;
        cam.orthoTop = half;
        cam.orthoBottom = -half;
        cam.minZ = Math.max(nextFit * CONFIG.CAMERA_NEAR_PLANE, 0.01);
    }
}

function _activeCameraFitBounds(canvasId) {
    return cuttingMatFrameBoundsMap[canvasId] ?? sceneBoundingBoxes[canvasId] ?? null;
}

/**
 * Z-up preset definitions — position-based to avoid BabylonJS Y-up spherical coord confusion.
 * `dir` is the unit direction vector FROM target TO camera in world space (Z-up, mm).
 * Z-up world: X=right, Y=depth (−Y=front, +Y=back), Z=up.
 *
 *   front : camera at −Y (in front of model, looking back)
 *   back  : camera at +Y (behind model)
 *   right : camera at +X
 *   left  : camera at −X
 *   top   : camera at +Z (directly above, looking down)
 *   bottom: camera at −Z (directly below, looking up)
 *   iso   : camera at (+1,−1,+1)/√3 — front-right-above, standard 35.26° isometric
 *
 * `up` is the desired screen "up" direction for each view.
 */
// Iso elevation ≈ 25° from horizontal — lower than the 35.26° true isometric for a
// more natural "eye level" viewpoint while still showing the part's top surface.
const _ISO_ELEV = 25 * Math.PI / 180;
const _ISO_Z = Math.sin(_ISO_ELEV);                 // ≈ 0.4226
const _ISO_XY = Math.cos(_ISO_ELEV) / Math.SQRT2;   // ≈ 0.6408
const PRESETS = {
    front:  { dir: [  0,      -1,       0      ], up: [0, 0, 1], zoom: 1.0 },
    back:   { dir: [  0,      +1,       0      ], up: [0, 0, 1], zoom: 1.0 },
    right:  { dir: [ -1,       0,       0      ], up: [0, 0, 1], zoom: 1.0 },
    left:   { dir: [ +1,       0,       0      ], up: [0, 0, 1], zoom: 1.0 },
    top:    { dir: [  0,       0,      +1      ], up: [0, 1, 0], zoom: 1.0 },
    bottom: { dir: [  0,       0,      -1      ], up: [0, 1, 0], zoom: 1.0 },
    iso:    { dir: [ -_ISO_XY, -_ISO_XY, _ISO_Z], up: [0, 0, 1], zoom: 1.0 },
};

// ── Smooth Transition Helpers ─────────────────────────────────────────────────────

/**
 * Creates a smooth easing function for camera transitions (ease-in-out cubic).
 */
function easeInOutCubic(t) {
    return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

/**
 * Animates camera position to a target position over the configured duration.
 * Returns a Promise that resolves when animation completes.
 */
function animateCameraToPosition(cam, targetPos, scene) {
    return new Promise((resolve) => {
        const duration = CONFIG.CAMERA_TRANSITION_DURATION * 1000;
        const startPos = cam.position.clone();
        const startTime = performance.now();

        const anim = () => {
            if (cam._presetAnimationCancelled) {
                resolve();
                return;
            }
            const elapsed = performance.now() - startTime;
            const progress = Math.min(elapsed / duration, 1);
            const eased = easeInOutCubic(progress);

            cam.position = BABYLON.Vector3.Lerp(startPos, targetPos, eased);

            if (progress < 1) {
                requestAnimationFrame(anim);
            } else {
                resolve();
            }
        };
        anim();
    });
}

/**
 * Animates the camera along a great-circle arc to a target direction, using
 * quaternion SLERP for numerically stable rotation at any angle (including 180°).
 * Also interpolates zoom (radius for perspective, ortho bounds for orthographic).
 * Returns a Promise that resolves when animation completes.
 *
 * @param {BABYLON.ArcRotateCamera} cam
 * @param {number[]} targetDir  - [x,y,z] unit direction from target to camera
 * @param {number}   startRadius - current camera radius
 * @param {number}   endRadius   - target camera radius (fitRadius × preset zoom)
 * @param {string}   canvasId    - viewer canvas ID (for ortho/perspective handling)
 */
function animateCameraArc(cam, targetDir, startRadius, endRadius, canvasId) {
    return new Promise((resolve) => {
        const duration = CONFIG.CAMERA_TRANSITION_DURATION * 1000;
        const tgt = cam.target;

        const startDirVec = cam.position.subtract(tgt).normalize();
        const endDirVec = new BABYLON.Vector3(targetDir[0], targetDir[1], targetDir[2]);

        // Build the quaternion that rotates startDir → endDir
        let dot = BABYLON.Vector3.Dot(startDirVec, endDirVec);
        dot = Math.max(-1, Math.min(1, dot));

        let rotQuat;
        if (dot > 0.999999) {
            // Nearly identical — no rotation
            rotQuat = BABYLON.Quaternion.Identity();
        } else if (dot < -0.999999) {
            // Antipodal (180°): pick a perpendicular axis to define the great circle.
            // Prefer the Z-up axis for horizontal 180° turns (front↔back, left↔right).
            let axis = BABYLON.Vector3.Cross(new BABYLON.Vector3(0, 0, 1), startDirVec);
            if (axis.length() < 0.001) {
                axis = BABYLON.Vector3.Cross(new BABYLON.Vector3(0, 1, 0), startDirVec);
            }
            axis.normalize();
            rotQuat = BABYLON.Quaternion.RotationAxis(axis, Math.PI);
        } else {
            const axis = BABYLON.Vector3.Cross(startDirVec, endDirVec).normalize();
            const angle = Math.acos(dot);
            rotQuat = BABYLON.Quaternion.RotationAxis(axis, angle);
        }

        const identity = BABYLON.Quaternion.Identity();

        // Ortho-mode zoom handling: animate orthoZoomFactors and bounds directly
        const isOrtho = canvasId && cameraProjection[canvasId] === 'orthographic';
        const initialRadius = canvasId ? (fitRadiusMap[canvasId] || cam.radius) : cam.radius;
        const startOrthoZoom = isOrtho ? (orthoZoomFactors[canvasId] || 1.0) : 0;
        const endOrthoZoom = isOrtho ? (endRadius / initialRadius) : 0;
        const engine = isOrtho ? engines[canvasId] : null;

        // Guard the ortho observer so it doesn't fight our bounds updates
        if (isOrtho) _arcAnimGuard[canvasId] = true;

        const startTime = performance.now();

        const anim = () => {
            if (cam._presetAnimationCancelled) {
                if (isOrtho) _arcAnimGuard[canvasId] = false;
                resolve();
                return;
            }

            const elapsed = performance.now() - startTime;
            const progress = Math.min(elapsed / duration, 1);
            const eased = easeInOutCubic(progress);

            // Quaternion SLERP gives a stable arc for any angle, including 180°
            const quat = BABYLON.Quaternion.Slerp(identity, rotQuat, eased);
            const dir = BABYLON.Vector3.Zero();
            startDirVec.rotateByQuaternionToRef(quat, dir);

            // Interpolate radius (perspective zoom) or use constant initial (ortho)
            const currentRadius = isOrtho
                ? initialRadius
                : startRadius + (endRadius - startRadius) * eased;

            cam.setPosition(new BABYLON.Vector3(
                tgt.x + dir.x * currentRadius,
                tgt.y + dir.y * currentRadius,
                tgt.z + dir.z * currentRadius
            ));

            if (isOrtho && engine) {
                // Smoothly animate ortho bounds instead of letting the observer handle it
                const currentZoom = startOrthoZoom + (endOrthoZoom - startOrthoZoom) * eased;
                orthoZoomFactors[canvasId] = currentZoom;
                const h = initialRadius * currentZoom * ORTHO_RADIUS_FACTOR;
                const asp = engine.getAspectRatio(cam);
                cam.orthoLeft   = -h * asp;
                cam.orthoRight  =  h * asp;
                cam.orthoTop    =  h;
                cam.orthoBottom = -h;
                cam.radius = initialRadius;
            } else {
                cam.radius = currentRadius;
            }

            if (progress < 1) {
                requestAnimationFrame(anim);
            } else {
                if (isOrtho) _arcAnimGuard[canvasId] = false;
                resolve();
            }
        };
        anim();
    });
}

/**
 * Animates camera upVector to target upVector over the configured duration.
 * Returns a Promise that resolves when animation completes.
 */
function animateCameraUpVector(cam, targetUp, scene) {
    return new Promise((resolve) => {
        const duration = CONFIG.CAMERA_TRANSITION_DURATION * 1000;
        const startUp = cam.upVector.clone();
        const targetUpVec = new BABYLON.Vector3(targetUp[0], targetUp[1], targetUp[2]);
        const startTime = performance.now();

        const anim = () => {
            if (cam._presetAnimationCancelled) {
                resolve();
                return;
            }
            const elapsed = performance.now() - startTime;
            const progress = Math.min(elapsed / duration, 1);
            const eased = easeInOutCubic(progress);

            cam.upVector = BABYLON.Vector3.Lerp(startUp, targetUpVec, eased).normalize();

            if (progress < 1) {
                requestAnimationFrame(anim);
            } else {
                resolve();
            }
        };
        anim();
    });
}

/**
 * Animates camera alpha (horizontal rotation) by a delta over the configured duration.
 * Returns a Promise that resolves when animation completes.
 */
function animateCameraAlpha(cam, deltaAlpha) {
    return new Promise((resolve) => {
        const duration = CONFIG.CAMERA_TRANSITION_DURATION * 1000;
        const startAlpha = cam.alpha;
        const targetAlpha = startAlpha + deltaAlpha;
        const startTime = performance.now();

        const anim = () => {
            if (cam._presetAnimationCancelled) {
                resolve();
                return;
            }
            const elapsed = performance.now() - startTime;
            const progress = Math.min(elapsed / duration, 1);
            const eased = easeInOutCubic(progress);

            cam.alpha = startAlpha + (targetAlpha - startAlpha) * eased;

            if (progress < 1) {
                requestAnimationFrame(anim);
            } else {
                resolve();
            }
        };
        anim();
    });
}

/**
 * Animates camera beta (vertical rotation) to a target value over the configured duration.
 * Returns a Promise that resolves when animation completes.
 */
function animateCameraBeta(cam, targetBeta) {
    return new Promise((resolve) => {
        const duration = CONFIG.CAMERA_TRANSITION_DURATION * 1000;
        const startBeta = cam.beta;
        const startTime = performance.now();

        const anim = () => {
            if (cam._presetAnimationCancelled) {
                resolve();
                return;
            }
            const elapsed = performance.now() - startTime;
            const progress = Math.min(elapsed / duration, 1);
            const eased = easeInOutCubic(progress);

            cam.beta = startBeta + (targetBeta - startBeta) * eased;

            if (progress < 1) {
                requestAnimationFrame(anim);
            } else {
                resolve();
            }
        };
        anim();
    });
}

/**
 * Animates camera radius (zoom) to a target value over the configured duration.
 * Returns a Promise that resolves when animation completes.
 */
function animateCameraRadius(cam, targetRadius) {
    return new Promise((resolve) => {
        const duration = CONFIG.CAMERA_TRANSITION_DURATION * 1000;
        const startRadius = cam.radius;
        const startTime = performance.now();

        const anim = () => {
            if (cam._presetAnimationCancelled) {
                resolve();
                return;
            }
            const elapsed = performance.now() - startTime;
            const progress = Math.min(elapsed / duration, 1);
            const eased = easeInOutCubic(progress);

            cam.radius = startRadius + (targetRadius - startRadius) * eased;

            if (progress < 1) {
                requestAnimationFrame(anim);
            } else {
                resolve();
            }
        };
        anim();
    });
}

/**
 * Positions the camera using a world-space direction vector rather than alpha/beta
 * so that the Z-up coordinate system is respected without spherical-coord confusion.
 * @param {boolean} smooth - If true, animates the transition smoothly
 */
function applyPreset(cam, presetName, smooth = false, canvasId = null) {
    const p = PRESETS[presetName];
    if (!p) return;

    const targetUp = new BABYLON.Vector3(p.up[0], p.up[1], p.up[2]);
    const t = cam.target;

    // Each preset defines a zoom factor (1.0 = fit-to-view). Resolve to a radius.
    const initialRadius = canvasId ? (fitRadiusMap[canvasId] || cam.radius) : cam.radius;
    const targetRadius = initialRadius * (p.zoom || 1.0);
    const currentRadius = cam.radius;

    const targetPos = new BABYLON.Vector3(
        t.x + p.dir[0] * targetRadius,
        t.y + p.dir[1] * targetRadius,
        t.z + p.dir[2] * targetRadius
    );

    if (smooth && canvasId) {
        const scene = scenes[canvasId];
        if (scene) {
            // Quaternion arc (direction + zoom) and up-vector transition in parallel
            Promise.all([
                animateCameraUpVector(cam, p.up, scene),
                animateCameraArc(cam, p.dir, currentRadius, targetRadius, canvasId)
            ]).then(() => {
                // Snap to exact final state
                cam.upVector = targetUp;
                cam.setPosition(targetPos);
                if (cameraProjection[canvasId] === 'orthographic') {
                    orthoZoomFactors[canvasId] = p.zoom || 1.0;
                    const engine = engines[canvasId];
                    if (engine) {
                        const h = initialRadius * (p.zoom || 1.0) * ORTHO_RADIUS_FACTOR;
                        const asp = engine.getAspectRatio(cam);
                        cam.orthoLeft   = -h * asp;
                        cam.orthoRight  =  h * asp;
                        cam.orthoTop    =  h;
                        cam.orthoBottom = -h;
                    }
                    cam.radius = initialRadius;
                } else {
                    cam.radius = targetRadius;
                }
            });
            return;
        }
    }

    // Immediate mode
    cam.upVector = targetUp;
    cam.setPosition(targetPos);
    if (canvasId && cameraProjection[canvasId] === 'orthographic') {
        orthoZoomFactors[canvasId] = p.zoom || 1.0;
        const engine = engines[canvasId];
        if (engine) {
            const h = initialRadius * (p.zoom || 1.0) * ORTHO_RADIUS_FACTOR;
            const asp = engine.getAspectRatio(cam);
            cam.orthoLeft   = -h * asp;
            cam.orthoRight  =  h * asp;
            cam.orthoTop    =  h;
            cam.orthoBottom = -h;
        }
        cam.radius = initialRadius;
    } else {
        cam.radius = targetRadius;
    }
}

// ── initialize ────────────────────────────────────────────────────────────────

/**
 * @param {string}  canvasId
 * @param {string}  fileUrl        Signed URL to the 3D file
 * @param {string}  fileExt        e.g. ".glb"
 * @param {boolean} isDark
 * @param {object|null} knownDimsMm  Optional { x, y, z } bounding box in mm from server
 * @param {object|null} dotNetRef   Optional DotNetObjectReference for error callbacks
 * @param {object|null} viewerSettings  Per-part render/projection/section settings
 */
export async function initialize(canvasId, fileUrl, fileExt, isDark, knownDimsMm, dotNetRef, viewerSettings = {}) {
    viewerSettings = normalizeViewerSettings(viewerSettings);
    // Debug logging: track when initialize is called
    const sanitizedUrl = fileUrl ? (fileUrl.includes('?') ? fileUrl.substring(0, fileUrl.indexOf('?')) + '?[SIGNED_URL]' : fileUrl) : '(none)';
    debugLog('[BabylonViewer] initialize START:', { canvasId, url: sanitizedUrl, fileExt, prevGen: loadGenerations[canvasId] || 0, timestamp: Date.now() });

    try {
        await loadScript('./lib/babylonjs/babylon.js');
        configureBabylonLogger();
        await loadScript('./lib/babylonjs/babylonjs.loaders.min.js');
        await loadScript('./lib/babylonjs/babylonjs.materials.min.js');

        const canvas = document.getElementById(canvasId);
        if (!canvas) { console.error(`[BabylonViewer] Canvas #${canvasId} not found.`); return; }

        canvas.style.background = 'transparent';
        canvas.style.opacity = '0';
        canvas.style.transition = `opacity ${CONFIG.ANIMATION_CANVAS_FADE_IN} ease-in`;

        if (engines[canvasId]) await dispose(canvasId);

        // Generation counter: any stale retry or async callback from a previous initialize()
        // call will see a mismatched generation and bail out, preventing duplicate mesh appends.
        loadGenerations[canvasId] = (loadGenerations[canvasId] || 0) + 1;
        const currentGen = loadGenerations[canvasId];

        darkModes[canvasId]        = !!isDark;
        modelLoadState[canvasId]   = 'loading';
        originalMaterials[canvasId]= {};
        sceneBoundingBoxes[canvasId] = null;
        meshCenters[canvasId]      = null;
        edgesEnabled[canvasId]     = !!viewerSettings.edgesEnabled;

        const engine = new BABYLON.Engine(canvas, true, {
            premultipliedAlpha: false,
            alpha: true,
            stencil: true,
            disableUniformBuffers: true,
        });
        const scene  = new BABYLON.Scene(engine);
        engines[canvasId] = engine;
        scenes[canvasId]  = scene;
        engine.resize();

        scene.clearColor = new BABYLON.Color4(0, 0, 0, 0);

        // Camera (upVector updated after model loads)
        const camera = new BABYLON.ArcRotateCamera('cam',
            Math.PI / 4, Math.acos(1 / Math.sqrt(3)) + (15 * Math.PI / 180), 10,
            BABYLON.Vector3.Zero(), scene);
        camera.attachControl(canvas, true);
        camera.wheelPrecision = 5; // Will be tuned by fitCameraToMesh after load
        camera.upVector = new BABYLON.Vector3(0, 0, 1); // Z-up
        // Disable built-in panning — replaced by pick-point pan below
        camera.panningSensibility = 0;
        // Restrict rotation to left-click only — right-click is reserved for pick-point pan
        camera.inputs.attached.pointers.buttons = [0];
        // Remove default pole clamp — allow full vertical rotation over top and bottom
        camera.lowerBetaLimit = null;
        camera.upperBetaLimit = null;
        mainCameras[canvasId] = camera;

        // Set initial projection mode based on parameter
        debugLog('[BabylonViewer] initialize: cameraProjection =', viewerSettings.cameraProjection);
        if (viewerSettings.cameraProjection === 'orthographic') {
            setCameraProjection(canvasId, 'orthographic');
        }

        // ── Right-click pixel-perfect pan (attached now, updated each model load) ────
        attachPickPointPan(canvasId, canvas, camera);

        // Placeholder light (replaced after model loads)
        new BABYLON.HemisphericLight('__init_light__', new BABYLON.Vector3(0, 0, 1), scene);

        const forcedExt = resolveExtension(fileUrl, fileExt);
        BABYLON.SceneLoader.ShowLoadingScreen = false;

        // Attempt to pre-fetch the GLB into a local blob URL. This allows instant
        // re-render on subsequent tab switches to the same part (blob URL never expires).
        let _resolvedUrl = fileUrl;
        if (fileUrl && (fileUrl.endsWith('.glb') || fileUrl.includes('.glb?'))) {
            try {
                _resolvedUrl = await _fetchGlbCached(fileUrl);
            } catch (_fetchErr) {
                console.warn('[BabylonViewer] GLB pre-fetch failed, falling back to direct URL:', _fetchErr.message);
                _resolvedUrl = fileUrl;
            }
        }
        if (loadGenerations[canvasId] !== currentGen || engines[canvasId] !== engine || scenes[canvasId] !== scene) {
            try { engine.stopRenderLoop(); } catch { }
            try { scene.dispose(); } catch { }
            try { engine.dispose(); } catch { }
            return;
        }
        const _effectiveFileUrl = _resolvedUrl;

        // Retry-with-backoff: the GLB may not yet be in GCS when the signed URL arrives
        // (race between the geometry worker writing the file and the SignalR event).
        // Retry up to 4 times on 404 with exponential backoff before surfacing the error to the UI.
        const _retryDelays = CONFIG.GLB_RETRY_DELAYS;
        function _loadAttempt(attempt) {
            // Bail out if a newer initialize() call has superseded this one
            if (loadGenerations[canvasId] !== currentGen) {
                console.warn(`[BabylonViewer] Stale load attempt ${attempt} cancelled (gen mismatch)`);
                return;
            }
            BABYLON.SceneLoader.Append('', _effectiveFileUrl, scene,
                (_scene) => {
                // Check again inside the async success callback — dispose() may have run while loading
                if (loadGenerations[canvasId] !== currentGen) {
                    console.warn('[BabylonViewer] Stale load success ignored (gen mismatch)');
                    return;
                }
                modelLoadState[canvasId] = 'loaded';
                requestAnimationFrame(() => { canvas.style.opacity = '1'; });


                // ── Re-affirm transparent background (append:true keeps existing scene) ──
                _scene.clearColor = new BABYLON.Color4(0, 0, 0, 0);

                // ── Remove placeholder lights, add studio lighting ──
                _scene.lights.forEach(l => l.dispose());
                const _lc = isDark ? CONFIG.STUDIO_DARK : CONFIG.STUDIO_LIGHT;

                // Ambient hemisphere
                const _amb = _lc.ambient;
                const hemi = new BABYLON.HemisphericLight('hemi', toVector3(_amb.direction), _scene);
                hemi.intensity   = _amb.intensity;
                hemi.diffuse     = toColor3(_amb.diffuse);
                hemi.groundColor = toColor3(_amb.groundColor);
                hemi.specular    = toColor3(_amb.specular);

                // Key light — casts shadows; kept as named local so key.position below stays valid
                const key = new BABYLON.DirectionalLight('key', toVector3(_lc.key.direction), _scene);
                key.intensity = _lc.key.intensity;
                key.diffuse   = toColor3(_lc.key.diffuse);
                key.specular  = toColor3(_lc.key.diffuse);

                const shadowGenerator = new BABYLON.ShadowGenerator(_lc.key.shadowMapSize, key);
                shadowGenerator.usePercentageCloserFiltering = true;
                shadowGenerator.filteringQuality = BABYLON.ShadowGenerator.QUALITY_HIGH;
                shadowGenerator.setDarkness(_lc.key.shadowDarkness);
                shadowGenerator.transparencyShadow = true;
                shadowGenerators[canvasId] = shadowGenerator;

                // Fill / rim lights (no shadows)
                if (_lc.fill) {
                    const fill = new BABYLON.DirectionalLight('fill', toVector3(_lc.fill.direction), _scene);
                    fill.intensity = _lc.fill.intensity;
                    fill.diffuse   = toColor3(_lc.fill.diffuse);
                    fill.specular  = new BABYLON.Color3(0.05, 0.05, 0.06);
                }
                if (_lc.rim) {
                    const rim = new BABYLON.DirectionalLight('rim', toVector3(_lc.rim.direction), _scene);
                    rim.intensity = _lc.rim.intensity;
                    rim.diffuse   = toColor3(_lc.rim.diffuse);
                    rim.specular  = toColor3(_lc.rim.diffuse);
                }
                if (_lc.back) {
                    const back2 = new BABYLON.DirectionalLight('back', toVector3(_lc.back.direction), _scene);
                    back2.intensity = _lc.back.intensity;
                    back2.diffuse   = toColor3(_lc.back.diffuse);
                    back2.specular  = new BABYLON.Color3(0.02, 0.02, 0.04);
                }

                // ── Find real model root nodes (TransformNodes or Meshes at scene root) ──
                // Operating on scene.rootNodes guarantees local-space == world-space
                // (no parent transform to account for), making centering exact.
                const _sysNames = new Set(['key', 'fill', 'back', 'hemi', 'cam', '__init_light__']);
                const modelRootNodes = _scene.rootNodes.filter(n =>
                    n.name !== '__grid__' &&
                    !n.name.startsWith('__axis') &&
                    !_sysNames.has(n.name) &&
                    !(n instanceof BABYLON.Camera) &&
                    !(n instanceof BABYLON.Light)
                );

                // rootMeshes still needed for scaling and shadow setup
                const rootMeshes = _scene.meshes.filter(m =>
                    m.name !== '__grid__' && m.name !== '__shadow_catcher__' && !m.name.startsWith('__axis') &&
                    (m.parent == null || !(m.parent instanceof BABYLON.AbstractMesh))
                );

                if (modelRootNodes.length === 0 && rootMeshes.length === 0) {
    console.warn('[BabylonViewer] No model meshes found - GLB may be empty or conversion failed');
    return;
}

                // ── Compute raw bounding box (GLB as-loaded, Y-up, mm) ──
                let rawBb = computeSceneBounds(_scene);
                if (!rawBb) {
    console.warn('[BabylonViewer] Could not compute bounding box - GLB may be corrupt');
    return;
}

                // ── Scale correction (if GLB dimensions deviate >5% from known) ──
                let scaleFactor = 1;
                const rawMaxDim = Math.max(
                    rawBb.max.x - rawBb.min.x,
                    rawBb.max.y - rawBb.min.y,
                    rawBb.max.z - rawBb.min.z
                );
                if (rawMaxDim > 1e-9
                    && knownDimsMm && knownDimsMm.x > 0 && knownDimsMm.y > 0 && knownDimsMm.z > 0) {
                    const knownMax = Math.max(knownDimsMm.x, knownDimsMm.y, knownDimsMm.z);
                    const ratio = rawMaxDim / knownMax;
                    const tol = CONFIG.SCALE_TOLERANCE;
                    if (ratio < (1 - tol) || ratio > (1 + tol)) scaleFactor = knownMax / rawMaxDim;
                }
                if (scaleFactor !== 1) {
                    rootMeshes.forEach(m => m.scaling.setAll(scaleFactor));
                }
                modelScaleFactors[canvasId] = scaleFactor;

                // ── Apply +90°X rotation to model root nodes ──
                // GLBs are Y-up (glTF spec). +90°X converts to Z-up (CAD/print standard).
                // Root nodes have no parent, so local-space == world-space for this rotation.
                const zUpQuat = BABYLON.Quaternion.RotationAxis(BABYLON.Axis.X, Math.PI / 2);
                const targetNodes = modelRootNodes.length > 0 ? modelRootNodes : rootMeshes;
                targetNodes.forEach(n => {
                    if (n.rotationQuaternion == null) {
                        n.rotationQuaternion = (n.rotation && n.rotation.length)
                            ? BABYLON.Quaternion.FromEulerVector(n.rotation)
                            : BABYLON.Quaternion.Identity();
                    }
                    n.rotationQuaternion = zUpQuat.multiply(n.rotationQuaternion);
                });

                // Force world matrix recalculation for all meshes after rotation
                _scene.meshes.forEach(m => m.computeWorldMatrix(true));

                // ── Bounding box (now Z-up, mm) ──
                let bb = computeSceneBounds(_scene);
                if (!bb) return;

                // ── Center on X/Y, lift Z_min → 0 ──
                // Applied to root nodes (local == world), so offset is exact.
                const cx = (bb.min.x + bb.max.x) / 2;
                const cy = (bb.min.y + bb.max.y) / 2;
                const zLift = -bb.min.z;
                modelCenterOffsets[canvasId] = { cx, cy, zLift };
                targetNodes.forEach(n => {
                    n.position.x -= cx;
                    n.position.y -= cy;
                    n.position.z += zLift;
                });

                // ── Final bounding box ──
                _scene.meshes.forEach(m => m.computeWorldMatrix(true));
                const finalBb = computeSceneBounds(_scene);
                if (!finalBb) return;
                sceneBoundingBoxes[canvasId] = finalBb;
                meshCenters[canvasId] = {
                    x: (finalBb.min.x + finalBb.max.x) / 2,
                    y: (finalBb.min.y + finalBb.max.y) / 2,
                    z: (finalBb.min.z + finalBb.max.z) / 2,
                };
                if (turningAxisRequests[canvasId]) {
                    const request = turningAxisRequests[canvasId];
                    buildTurningAxisGeometry(canvasId, request.primaryAxis, request.axisVector, request.axisPoint);
                }

                // ── Permanent shadow-catcher ground plane ──
                // Creates an always-on ground mesh to catch shadows from the model.
                // The grid toggle is independent and creates/disposes its own ground.
                const bbSizeXY = Math.max(finalBb.max.x - finalBb.min.x, finalBb.max.y - finalBb.min.y) * 3;
                const catcher = BABYLON.MeshBuilder.CreateGround('__shadow_catcher__', { width: bbSizeXY, height: bbSizeXY }, _scene);
                catcher.rotation.x = Math.PI / 2;   // world XY plane (Z-up)
                catcher.position.z = finalBb.min.z;  // sit at model base
                catcher.receiveShadows = true;
                catcher.isPickable = false;
                // Prefer ShadowOnlyMaterial (visually invisible but catches shadows)
                if (BABYLON.ShadowOnlyMaterial) {
                    const mat = new BABYLON.ShadowOnlyMaterial('shadowOnly', _scene);
                    mat.shadowColor = new BABYLON.Color3(0, 0, 0);
                    mat.alpha = 0.35;
                    catcher.material = mat;
                } else {
                    // Fallback: transparent StandardMaterial
                    const mat = new BABYLON.StandardMaterial('shadowCatcherFallback', _scene);
                    mat.alpha = 0.0001;
                    mat.diffuseColor = new BABYLON.Color3(1, 1, 1);
                    mat.specularColor = new BABYLON.Color3(0, 0, 0);
                    catcher.material = mat;
                }

                // ── Build body map for multi-body support ──
                // A multi-body GLB has a single glTF __root__ node with N body children.
                // A single-body GLB either IS the root mesh or has one child.
                // We resolve body nodes by descending into children when the root has multiple.
                const bodyMap = new Map();
                let bodyIndex = 0;

                function _collectBodyNodes(root) {
                    // If root is itself a mesh, it IS the body
                    if (root instanceof BABYLON.AbstractMesh && root.getTotalVertices() > 0) {
                        return [root];
                    }
                    // Get non-system child nodes
                    const children = root.getChildren().filter(c =>
                        !(c instanceof BABYLON.Camera) && !(c instanceof BABYLON.Light)
                    );
                    if (children.length === 0) return [];
                    if (children.length === 1) {
                        // One child — could be an extra wrapper level; recurse
                        return _collectBodyNodes(children[0]);
                    }
                    // Multiple children → each is a distinct body
                    return children;
                }

                modelRootNodes.forEach(root => {
                    const bodyNodes = _collectBodyNodes(root);
                    bodyNodes.forEach(bodyNode => {
                        const meshes = bodyNode instanceof BABYLON.AbstractMesh && bodyNode.getTotalVertices() > 0
                            ? [bodyNode, ...bodyNode.getChildMeshes(false).filter(m => m.getTotalVertices() > 0)]
                            : bodyNode.getChildMeshes(false).filter(m => m.getTotalVertices() > 0);
                        if (meshes.length > 0) {
                            bodyMap.set(bodyIndex, {
                                rootNode: bodyNode,
                                meshes,
                                colorMaterial: null,
                                name: bodyNode.name || `Body_${bodyIndex}`
                            });
                            bodyIndex++;
                        }
                    });
                });
                perCanvasBodyMap[canvasId] = bodyMap;
                debugLog(`[BabylonViewer] Detected ${bodyMap.size} bodies in model`);

                // ── Apply multi-body colored materials immediately ──
                // Don't wait for SignalR — color the bodies right away on load
                if (bodyMap.size > 1) {
                    const palette = CONFIG.MULTI_BODY_PALETTE.map(c => toColor3(c));
                    const bodies = Array.from(bodyMap.keys()).map(idx => ({
                        index: idx,
                        name: bodyMap.get(idx)?.name || `Body_${idx}`,
                        volumeCm3: 0,  // Not known yet, but setBodies doesn't use it
                        colorHex: null
                    }));

                    // Apply the colored materials
                    bodies.forEach((body, idx) => {
                        const bodyData = bodyMap.get(body.index);
                        if (!bodyData) return;

                        const color = palette[idx % palette.length];
                        const colorMaterial = new BABYLON.PBRMaterial(`body_${idx}_mat`, scene);
                        colorMaterial.albedoColor = color;
                        colorMaterial.metallic = CONFIG.MATERIAL_MULTI_BODY.metallic;
                        colorMaterial.roughness = CONFIG.MATERIAL_MULTI_BODY.roughness;
                        colorMaterial.alpha = CONFIG.MATERIAL_MULTI_BODY.alpha;
                        colorMaterial.backFaceCulling = false;

                        bodyData.meshes.forEach(mesh => {
                            mesh.material = colorMaterial;
                        });

                        bodyData.colorMaterial = colorMaterial;
                        bodyData.index = idx;
                        bodyData.name = body.name;

                        debugLog(`[BylonViewer] Auto-colored body ${idx} (${body.name}) to RGB(${color.r},${color.g},${color.b})`);
                    });
                }

                // ── Save original materials and setup shadows ──
                const origMats = originalMaterials[canvasId];
                const shadowGen = shadowGenerators[canvasId];
                if (!shadowGen) {
                    console.warn('[BabylonViewer] Shadow generator not found for canvas:', canvasId);
                }
                _scene.meshes.forEach(m => {
                    if (m.name !== '__grid__' && m.name !== '__shadow_catcher__' && !m.name.startsWith('__axis') && !m.name.startsWith('__cutting_mat')) {
                        if (m.material) origMats[m.uniqueId] = m.material;
                        if (shadowGen) {
                            shadowGen.addShadowCaster(m);
                        }
                        m.receiveShadows = false;
                    }
                });

                // Capture immutable baseline for "default solid look" — never overwritten.
                // Used by setRenderMode('solid') and flipped-triangles disable to restore a clean state.
                // For single-body models, always use the uniform CAD gray so all files look consistent.
                // For multi-body models, preserve per-body palette colors.
                if (!defaultSolidMaterials[canvasId]) defaultSolidMaterials[canvasId] = new Map();
                const defMap = defaultSolidMaterials[canvasId];
                const existingBodyMap = perCanvasBodyMap[canvasId];
                const isMultiBody = existingBodyMap && existingBodyMap.size > 1;
                const cadGray = getCadMaterial(_scene);
                _scene.meshes.forEach(m => {
                    if (m.material && !defMap.has(m.uniqueId) && !isSystemMesh(m) && m.name !== '__root__' && !m.name.startsWith('__axis')) {
                        defMap.set(m.uniqueId, isMultiBody ? m.material : cadGray);
                        // Apply CAD gray immediately for single-body so the initial view is uniform
                        if (!isMultiBody) m.material = cadGray;
                    }
                });
                tagModelMeshesForAnalysis(canvasId, _scene);

                // ── Store material type for setRenderMode below ──
                materialTypes[canvasId] = viewerSettings.materialType || 'aluminum';

                // Position directional light to correctly cast shadows from the top, front-left
                const dist = Math.max(
                    finalBb.max.x - finalBb.min.x,
                    finalBb.max.y - finalBb.min.y,
                    finalBb.max.z - finalBb.min.z
                );
                key.position = new BABYLON.Vector3(meshCenters[canvasId].x - dist, meshCenters[canvasId].y - dist, finalBb.max.z + dist);

                // ── Configure camera ──
                const cam = mainCameras[canvasId];
                if (cam) {
                    cam.upVector = new BABYLON.Vector3(0, 0, 1);
                    fitCameraToMesh(cam, finalBb, meshCenters[canvasId], canvasId);
                    applyPreset(cam, 'iso');
                    // Apply projection after fit: engines[canvasId] is registered before async
                    // model loading starts, so setCameraProjection can recalculate ortho bounds
                    // using the correct model-scale radius.
                    setCameraProjection(canvasId, viewerSettings.cameraProjection);
                }

                // ── Post Processing ──
                // Image processing is configured via scene.imageProcessingConfiguration
                // (tonemapping, contrast, exposure) inside getOrCreateEnvironmentTexture()
                // when realistic mode is entered. Hardware MSAA is enabled on engine creation.
                // Full DefaultRenderingPipeline is intentionally avoided: it adds shader
                // complexity that conflicts with analysis-tool overlays and the axis gizmo.

                // ── Auto-rotation: idle spin with hover slow-down and click stop ──
                animStates[canvasId]       = 'idle';
                autoSpeedCurrent[canvasId] = 0;
                autoSpeedTarget[canvasId]  = SPEED_IDLE;

                canvas.addEventListener('mouseenter', () => {
                    if (animStates[canvasId] !== 'interacting') {
                        animStates[canvasId]      = 'hovering';
                        autoSpeedTarget[canvasId] = SPEED_HOVER;
                    }
                });
                canvas.addEventListener('mouseleave', () => {
                    if (animStates[canvasId] !== 'interacting') {
                        animStates[canvasId]      = 'idle';
                        autoSpeedTarget[canvasId] = SPEED_IDLE;
                    }
                });
                canvas.addEventListener('pointerdown', () => {
                    animStates[canvasId]      = 'interacting';
                    autoSpeedTarget[canvasId] = SPEED_STOP;
                });

                // ── Axis gizmo ──
                createAxisGizmo(canvasId, _scene, mainCameras[canvasId], canvas);
                axisGizmoLayer[canvasId]?.onResize(canvas.offsetWidth, canvas.offsetHeight);

                // ── Resize observer ──
                if (resizeObservers[canvasId]) resizeObservers[canvasId].disconnect();
                const ro = new ResizeObserver(() => {
                    requestAnimationFrame(() => {
                        if (engines[canvasId]) {
                            engines[canvasId].resize();
                            axisGizmoLayer[canvasId]?.onResize(canvas.offsetWidth, canvas.offsetHeight);
                        }
                    });
                });
                ro.observe(canvas);
                resizeObservers[canvasId] = ro;

                setRenderMode(canvasId, viewerSettings.renderMode);
                toggleEdges(canvasId, !!viewerSettings.edgesEnabled);
                toggleBoundingBox(canvasId, !!viewerSettings.boundingBoxEnabled);
                viewerSettings.gridEnabled ? showGrid(canvasId) : hideGrid(canvasId);
                setSectionPlane(
                    canvasId,
                    !!viewerSettings.sectionEnabled,
                    viewerSettings.sectionAxis,
                    viewerSettings.sectionOffsetMm,
                    !!viewerSettings.sectionInverted
                );
                runLocalAdvisoryGeometry(canvasId, {
                    processCode: viewerSettings.processCode,
                });
            },
            null,
            (_scene, message, exception) => {
                const is404 = message && (message.includes('404') || message.includes('Not Found') || message.includes('status: 404'));
                if (is404 && attempt < _retryDelays.length) {
                    const delay = _retryDelays[attempt];
                    console.warn(`[BabylonViewer] GLB not ready (404), retry ${attempt + 1}/${_retryDelays.length} in ${delay}ms`);
                    setTimeout(() => {
                        if (loadGenerations[canvasId] !== currentGen) return;
                        _loadAttempt(attempt + 1);
                    }, delay);
                    return;
                }
                modelLoadState[canvasId] = 'error';
                // Detailed error logging for debugging viewer flash issue
                const sanitizedUrl = fileUrl ? (fileUrl.includes('?') ? fileUrl.substring(0, fileUrl.indexOf('?')) + '?[SIGNED_URL]' : fileUrl) : '(none)';
                console.error('[BabylonViewer] Load error details:', {
                    url: sanitizedUrl,
                    message: message,
                    exception: exception?.message || exception?.toString() || '(no exception)',
                    stack: exception?.stack || '(no stack)',
                    attempt: attempt,
                    totalRetries: _retryDelays.length
                });
                if (dotNetRef) {
                    dotNetRef.invokeMethodAsync('OnLoadError', message || 'Failed to load 3D model');
                }
                requestAnimationFrame(() => { canvas.style.opacity = '1'; });
            },
            forcedExt,
            );
        }
        _loadAttempt(0);

        engine.runRenderLoop(() => {
            if (loadGenerations[canvasId] !== currentGen || engines[canvasId] !== engine || scenes[canvasId] !== scene) {
                return;
            }

            // Smooth speed interpolation (lerp toward target)
            const curr   = autoSpeedCurrent[canvasId] ?? 0;
            const target = autoSpeedTarget[canvasId]  ?? 0;
            autoSpeedCurrent[canvasId] = curr + (target - curr) * CONFIG.AUTO_ROTATION_LERP_FACTOR;

            // Apply auto-rotation
            const cam = mainCameras[canvasId];
            if (cam && Math.abs(autoSpeedCurrent[canvasId]) > CONFIG.AUTO_ROTATION_MIN_THRESHOLD) {
                cam.alpha += autoSpeedCurrent[canvasId];
            }

            scene.render();
        });

        const resizeHandler = () => {
            requestAnimationFrame(() => {
                if (engines[canvasId]) {
                    engines[canvasId].resize();
                    axisGizmoLayer[canvasId]?.onResize(canvas.offsetWidth, canvas.offsetHeight);
                }
            });
        };
        window.addEventListener('resize', resizeHandler);
        engine._resizeHandler = resizeHandler;

    } catch (err) {
        modelLoadState[canvasId] = 'error';
        // Detailed error logging for debugging viewer flash issue
        const sanitizedUrl = fileUrl ? (fileUrl.includes('?') ? fileUrl.substring(0, fileUrl.indexOf('?')) + '?[SIGNED_URL]' : fileUrl) : '(none)';
        console.error('[BabylonViewer] Init failed details:', {
            url: sanitizedUrl,
            error: err?.message || err?.toString() || '(no error)',
            stack: err?.stack || '(no stack)'
        });
        if (dotNetRef) {
            dotNetRef.invokeMethodAsync('OnLoadError', err.message || 'Failed to initialize 3D viewer');
        }
    }
}

// ── Pick-point pan (right-click drag) ─────────────────────────────────────────────

/**
 * Attaches a right-click drag handler that pans the camera so that the
 * 3D world point initially under the cursor stays exactly under the cursor.
 *
 * Algorithm (ray-plane intersection):
 *   1. On right-mousedown: cast a ray and intersect with a plane that is
 *      perpendicular to the view direction and passes through camera.target.
 *      This gives the "anchor" world point A.
 *   2. On mousemove: cast a ray and find where it hits the same plane.
 *      This gives the "current" world point C.
 *   3. Move camera.target by (A − C) so that C maps to the anchor pixel.
 *      A stays fixed relative to that pixel.
 *
 * Works for both perspective and orthographic modes.
 */
const panStates = {}; // canvasId → { active, plane, anchor, planeNormal }
// per-canvas right-drag event listeners so we can remove them on dispose
const panHandlers = {}; // canvasId → { down, move, up }
const middleZoomHandlers = {}; // DISABLED - feature removed

function attachPickPointPan(canvasId, canvas, camera) {
    // Remove any previous handlers for this canvas
    const prev = panHandlers[canvasId];
    if (prev) {
        canvas.removeEventListener('pointerdown',  prev.down);
        canvas.removeEventListener('pointermove',  prev.move);
        canvas.removeEventListener('pointerup',    prev.up);
        canvas.removeEventListener('contextmenu',  prev.ctx);
    }

    panStates[canvasId] = { active: false, plane: null, anchor: null };

    function castRay(clientX, clientY) {
        const engine = engines[canvasId];
        const scene  = scenes[canvasId];
        if (!engine || !scene) return null;
        const rect = canvas.getBoundingClientRect();
        const x = ((clientX - rect.left) / rect.width)  * engine.getRenderWidth();
        const y = ((clientY - rect.top)  / rect.height) * engine.getRenderHeight();
        return scene.createPickingRay(x, y, BABYLON.Matrix.Identity(), camera, false);
    }

    function rayPlaneIntersect(ray, planeNormal, planePoint) {
        const denom = BABYLON.Vector3.Dot(planeNormal, ray.direction);
        if (Math.abs(denom) < 1e-6) return null;
        const t = BABYLON.Vector3.Dot(planeNormal, planePoint.subtract(ray.origin)) / denom;
        if (t < 0) return null;
        return ray.origin.add(ray.direction.scale(t));
    }

    const onPointerDown = (e) => {
        if (e.button !== 2) return;
        e.preventDefault();
        const state = panStates[canvasId];
        const ray = castRay(e.clientX, e.clientY);
        if (!ray) return;
        // Plane: perpendicular to view direction, passing through camera.target
        const planeNormal = camera.position.subtract(camera.target).normalize();
        const anchor = rayPlaneIntersect(ray, planeNormal, camera.target.clone());
        if (!anchor) return;
        state.active  = true;
        state.plane   = { normal: planeNormal, point: camera.target.clone() };
        state.anchor  = anchor;
        canvas.setPointerCapture(e.pointerId);
    };

    const onPointerMove = (e) => {
        const state = panStates[canvasId];
        if (!state || !state.active) return;
        const ray = castRay(e.clientX, e.clientY);
        if (!ray) return;
        const hit = rayPlaneIntersect(ray, state.plane.normal, state.plane.point);
        if (!hit) return;
        // Move camera.target so the anchor stays fixed under the cursor
        const delta = state.anchor.subtract(hit);
        camera.target.addInPlace(delta);
        // Keep the plane co-moving with the camera target for numerical stability
        state.plane.point.addInPlace(delta);
    };

    const onPointerUp = (e) => {
        if (e.button !== 2) return;
        const state = panStates[canvasId];
        if (state) state.active = false;
        try { canvas.releasePointerCapture(e.pointerId); } catch (_) {}
        // Re-apply edges after pan to catch up on skipped observer updates
        if (edgesEnabled[canvasId] && cameraProjection[canvasId] === 'perspective') {
            toggleEdges(canvasId, true);
        }
    };

    // Suppress the browser context-menu on right-click inside the 3D canvas
    const onContextMenu = (e) => e.preventDefault();

    canvas.addEventListener('pointerdown',  onPointerDown);
    canvas.addEventListener('pointermove',  onPointerMove);
    canvas.addEventListener('pointerup',    onPointerUp);
    canvas.addEventListener('contextmenu',  onContextMenu);

    panHandlers[canvasId] = {
        down: onPointerDown,
        move: onPointerMove,
        up:   onPointerUp,
        ctx:  onContextMenu,
    };
}

// ── Middle-mouse drag zoom ───────────────────────────────────────────────────────

/**
 * Attaches middle-mouse button drag-to-zoom functionality.
 * Dragging up zooms in, dragging down zooms out. Zooms toward the cursor position.
 * @param {string} canvasId
 * @param {HTMLElement} canvas
 */
function attachMiddleMouseZoom(canvasId, canvas) { return; // DISABLED - feature removed
    // Remove any previous handlers for this canvas
    const prev = middleZoomHandlers[canvasId];
    if (prev) {
        canvas.removeEventListener('pointerdown', prev.down);
        canvas.removeEventListener('pointermove', prev.move);
        canvas.removeEventListener('pointerup',   prev.up);
        canvas.removeEventListener('pointerleave', prev.leave);
    }

    const state = {
        active: false,
        startY: 0,
        startRadius: 0,
        startZoom: 0,
        targetPoint: null
    };

    function onPointerDown(e) {
        if (e.button !== 1) return; // middle mouse only
        e.preventDefault();
        state.active = true;
        state.startY = e.clientY;
        state.startRadius = mainCameras[canvasId].radius;
        state.startZoom = orthoZoomFactors[canvasId] || 1;

        // Pick point under cursor for zoom-target
        const scene = scenes[canvasId];
        const coords = getPointerRenderCoordinates(canvasId, e);
        const pickResult = coords
            ? scene.pick(coords.x, coords.y, mesh => isModelMeshForAnalysis(mesh, canvasId))
            : { hit: false };
        if (pickResult.hit && !isSystemMesh(pickResult.pickedMesh)) {
            state.targetPoint = pickResult.pickedPoint.clone();
        } else {
            state.targetPoint = null;
        }

        // Stop auto-rotation
        animStates[canvasId] = 'interacting';
        autoSpeedTarget[canvasId] = SPEED_STOP;
    }

    function onPointerMove(e) {
        if (!state.active) return;
        const dy = state.startY - e.clientY; // positive = drag up = zoom in
        const zoomSpeed = 0.005;
        const cam = mainCameras[canvasId];

        if (cameraProjection[canvasId] === 'orthographic') {
            orthoZoomFactors[canvasId] = Math.max(0.05, state.startZoom * Math.exp(-dy * zoomSpeed));
        } else {
            const newRadius = Math.max(cam.lowerRadiusLimit, Math.min(cam.upperRadiusLimit,
                state.startRadius * Math.exp(dy * zoomSpeed)));
            cam.radius = newRadius;
        }

        // Move target toward picked point (CAD-style zoom-to-cursor)
        if (state.targetPoint) {
            const factor = dy * zoomSpeed * 0.3;
            cam.target = BABYLON.Vector3.Lerp(cam.target, state.targetPoint, Math.min(0.15, Math.abs(factor)));
        }
    }

    function onPointerUp(e) {
        if (e.button !== 1 || !state.active) return;
        state.active = false;
        // Re-apply edges if enabled (zoom changed)
        if (edgesEnabled[canvasId]) toggleEdges(canvasId, true);
    }

    function onPointerLeave() {
        if (state.active) {
            state.active = false;
            // Re-apply edges if enabled
            if (edgesEnabled[canvasId]) toggleEdges(canvasId, true);
        }
    }

    canvas.addEventListener('pointerdown',  onPointerDown);
    canvas.addEventListener('pointermove',  onPointerMove);
    canvas.addEventListener('pointerup',    onPointerUp);
    canvas.addEventListener('pointerleave', onPointerLeave);

    // Prevent middle-click auto-scroll behavior in some browsers
    canvas.onauxclick = (e) => e.preventDefault();

    middleZoomHandlers[canvasId] = {
        down:  onPointerDown,
        move: onPointerMove,
        up:    onPointerUp,
        leave: onPointerLeave,
    };
}

// ── Axis gizmo ────────────────────────────────────────────────────────────────

/**
 * Creates a fixed XYZ axis indicator in the top-right corner.
 * After 90° clockwise rotation around Z (Z is up on screen):
 * - X (red) → points up (Y+)
 * - Y (green) → points right (X+)
 * - Z (blue) → points up (Z+, unchanged)
 */
function createAxisGizmo(canvasId, scene, mainCam, canvas) {
    // Dispose previous
    if (axisGizmoLayer[canvasId]) { axisGizmoLayer[canvasId].dispose(); axisGizmoLayer[canvasId] = null; }
    if (axisLabelDivs[canvasId]) {
        axisLabelDivs[canvasId].forEach(({ div }) => div.remove());
        delete axisLabelDivs[canvasId];
    }
    if (axisMouseHandlers[canvasId]) {
        canvas.removeEventListener('mousemove', axisMouseHandlers[canvasId]);
        canvas.removeEventListener('mouseleave', axisMouseHandlers[canvasId + '_leave']);
        delete axisMouseHandlers[canvasId];
    }
    ['__axisX__','__axisY__','__axisZ__','__axisXArr__','__axisYArr__','__axisZArr__']
        .forEach(n => { const m = scene.getMeshByName(n); if (m) m.dispose(); });
    const oldCam = scene.getCameraByName('__axesCam__');
    if (oldCam) oldCam.dispose();

    if (!(mainCam instanceof BABYLON.ArcRotateCamera)) return;

    const LAYER = CONFIG.AXIS_GIZMO.layerMask;
    const LEN   = CONFIG.AXIS_GIZMO.length;

    // Z-up CAD standard: X=red, Y=green, Z=blue
    const COL_X = toColor3(CONFIG.AXIS_GIZMO.colorX); // Red
    const COL_Y = toColor3(CONFIG.AXIS_GIZMO.colorY); // Green
    const COL_Z = toColor3(CONFIG.AXIS_GIZMO.colorZ); // Blue

    function makeAxisLine(name, pts, color) {
        const l = BABYLON.MeshBuilder.CreateLines(name, { points: pts }, scene);
        l.color = color; l.isPickable = false; l.layerMask = LAYER;
        return l;
    }

    makeAxisLine('__axisX__', [BABYLON.Vector3.Zero(), new BABYLON.Vector3(-LEN, 0, 0)], COL_X);  // X+ direction, red
    makeAxisLine('__axisY__', [BABYLON.Vector3.Zero(), new BABYLON.Vector3(0, LEN, 0)], COL_Y);  // Y+ direction, green
    makeAxisLine('__axisZ__', [BABYLON.Vector3.Zero(), new BABYLON.Vector3(0, 0, LEN)], COL_Z);  // Z+ direction, blue

    function makeCone(name, dir, color) {
        const d = dir.normalize();
        const cone = BABYLON.MeshBuilder.CreateCylinder(name,
            { diameterTop: 0, diameterBottom: CONFIG.AXIS_GIZMO.coneDiameter, height: CONFIG.AXIS_GIZMO.coneHeight, tessellation: CONFIG.AXIS_GIZMO.coneTessellation }, scene);
        const mat = new BABYLON.StandardMaterial(name + 'Mat', scene);
        mat.diffuseColor = color; mat.emissiveColor = color.scale(0.4);
        mat.backFaceCulling = false;
        cone.material = mat; cone.isPickable = false; cone.layerMask = LAYER;
        const up = new BABYLON.Vector3(0, 1, 0);
        const cross = BABYLON.Vector3.Cross(up, d);
        if (cross.length() > 0.001) {
            cone.rotationQuaternion = BABYLON.Quaternion.RotationAxis(
                cross.normalize(), Math.acos(Math.max(-1, Math.min(1, BABYLON.Vector3.Dot(up, d)))));
        } else if (BABYLON.Vector3.Dot(up, d) < 0) {
            cone.rotationQuaternion = BABYLON.Quaternion.RotationAxis(new BABYLON.Vector3(1, 0, 0), Math.PI);
        }
        cone.position = d.scale(LEN + 0.09);
        return cone;
    }

    makeCone('__axisXArr__', new BABYLON.Vector3(-1, 0, 0), COL_X);  // X+ direction, red
    makeCone('__axisYArr__', new BABYLON.Vector3(0, 1, 0), COL_Y);  // Y+ direction, green
    makeCone('__axisZArr__', new BABYLON.Vector3(0, 0, 1), COL_Z);  // Z+ direction, blue

    // Gizmo camera — top-right corner, orthographic, renders only LAYER meshes
    const hw = 1.1;
    const axesCam = new BABYLON.ArcRotateCamera('__axesCam__',
        mainCam.alpha, mainCam.beta, 3.5, BABYLON.Vector3.Zero(), scene);
    axesCam.mode        = BABYLON.Camera.ORTHOGRAPHIC_CAMERA;
    axesCam.orthoLeft   = -hw; axesCam.orthoRight = hw;
    axesCam.orthoTop    = hw;  axesCam.orthoBottom = -hw;
    axesCam.viewport    = new BABYLON.Viewport(
        CONFIG.AXIS_GIZMO.viewportPosition.x,
        CONFIG.AXIS_GIZMO.viewportPosition.y,
        CONFIG.AXIS_GIZMO.viewportPosition.width,
        CONFIG.AXIS_GIZMO.viewportPosition.height
    ); // top-right
    axesCam.layerMask   = LAYER;
    axesCam.minZ = 0.01; axesCam.maxZ = 100;
    axesCam.upVector = new BABYLON.Vector3(0, 0, 1);

    const syncObs = scene.onBeforeRenderObservable.add(() => {
        // Sync the gizmo camera to match the main camera's view direction.
        // We derive a position from the normalised direction vector so the
        // gizmo always shows the correct axis orientation regardless of upVector.
        const dir = mainCam.position.subtract(mainCam.target).normalize();
        axesCam.setPosition(dir.scale(3.5)); // orbit at fixed radius
        axesCam.upVector.copyFrom(mainCam.upVector);
        // Update axis hover label positions each frame
        updateAxisLabels(canvasId, scene, axesCam);
    });

    scene.activeCameras = [mainCam, axesCam];

    // ── Hover labels (X, Y, Z text that appear on mouseover) ──
    const labelDefs = [
        { name: 'X', color: '#f04444', pos: new BABYLON.Vector3(-(LEN + 0.28), 0, 0) },  // X+, red
        { name: 'Y', color: '#22c750', pos: new BABYLON.Vector3(0, LEN + 0.28, 0) },  // Y+, green
        { name: 'Z', color: '#3882f5', pos: new BABYLON.Vector3(0, 0, LEN + 0.28) },  // Z+, blue
    ];

    const labelDivs = labelDefs.map(({ name, color, pos }) => {
        const div = document.createElement('div');
        div.className = 'axis-gizmo-label';
        div.textContent = name;
        div.setAttribute('translate', 'no');
        div.setAttribute('aria-label', `${name} axis`);
        div.lang = 'zxx';
        div.style.cssText = `
            position: fixed;
            transform: translate(-50%, -50%);
            color: ${color};
            font-size: ${CONFIG.AXIS_GIZMO.labelFontSize};
            font-weight: 700;
            font-family: 'JetBrains Mono', ui-monospace, SFMono-Regular, Consolas, 'Courier New', monospace !important;
            font-variant-ligatures: none;
            font-feature-settings: "liga" 0, "clig" 0;
            text-transform: none;
            pointer-events: none;
            opacity: 0;
            transition: opacity 0.18s ease;
            z-index: 25;
            text-shadow: 0 0 4px rgba(0,0,0,0.8);
        `;
        document.body.appendChild(div);
        return { div, localPos: pos };
    });
    axisLabelDivs[canvasId] = labelDivs;

    // Mousemove: show labels when cursor is over axes viewport region
    // BabylonJS viewport (0.78, 0.76, 0.22, 0.24):
    //   canvas DOM coords: relX ≥ 0.78, relY ≤ 1 − 0.76 = 0.24  (BabylonJS Y is bottom-up)
    function onMouseMove(e) {
        const rect = canvas.getBoundingClientRect();
        const relX = (e.clientX - rect.left) / rect.width;
        const relY = (e.clientY - rect.top) / rect.height;
        const inGizmo = relX >= CONFIG.GIZMO_HOVER_REGION.xMin && relY <= CONFIG.GIZMO_HOVER_REGION.yMax;
        labelDivs.forEach(({ div }) => {
            div.style.opacity = inGizmo ? '1' : '0';
        });
    }
    function onMouseLeave() {
        labelDivs.forEach(({ div }) => { div.style.opacity = '0'; });
    }
    canvas.addEventListener('mousemove', onMouseMove);
    canvas.addEventListener('mouseleave', onMouseLeave);
    axisMouseHandlers[canvasId]              = onMouseMove;
    axisMouseHandlers[canvasId + '_leave']   = onMouseLeave;

    axisGizmoLayer[canvasId] = {
        dispose() {
            scene.onBeforeRenderObservable.remove(syncObs);
            scene.activeCameras = [mainCam];
            axesCam.dispose();
            ['__axisX__','__axisY__','__axisZ__','__axisXArr__','__axisYArr__','__axisZArr__']
                .forEach(n => { const m = scene.getMeshByName(n); if (m) m.dispose(); });
            labelDivs.forEach(({ div }) => div.remove());
            canvas.removeEventListener('mousemove', onMouseMove);
            canvas.removeEventListener('mouseleave', onMouseLeave);
        },
        onResize(canvasWidth, canvasHeight) {
            // Keep gizmo axes undistorted: scale ortho bounds to match viewport aspect ratio.
            // Match the camera frustum to the configured gizmo viewport's actual pixel aspect.
            const viewport = CONFIG.AXIS_GIZMO.viewportPosition;
            const viewportWidth = Math.max(1, canvasWidth * viewport.width);
            const viewportHeight = Math.max(1, canvasHeight * viewport.height);
            const aspect = viewportWidth / viewportHeight;
            axesCam.orthoLeft   = -hw * aspect;
            axesCam.orthoRight  =  hw * aspect;
            axesCam.orthoTop    =  hw;
            axesCam.orthoBottom = -hw;
        }
    };
}

/**
 * Reprojects axis label positions to screen space each frame.
 */
function updateAxisLabels(canvasId, scene, axesCam) {
    const labelDivs = axisLabelDivs[canvasId];
    if (!labelDivs) return;
    const engine = engines[canvasId];
    if (!engine) return;
    const canvas = engine.getRenderingCanvas();
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const rw = engine.getRenderWidth(), rh = engine.getRenderHeight();
    // Use axesCam's own view×projection so labels map to the gizmo viewport.
    const viewProj = axesCam.getViewMatrix().multiply(axesCam.getProjectionMatrix());
    labelDivs.forEach(({ div, localPos }) => {
        const p = BABYLON.Vector3.Project(
            localPos, BABYLON.Matrix.Identity(), viewProj,
            axesCam.viewport.toGlobal(rw, rh)
        );
        if (p.z >= 0 && p.z <= 1) {
            div.style.left = (rect.left + (p.x / rw) * rect.width)  + 'px';
            // BabylonJS viewport.y is in bottom-origin (OpenGL) convention.
            // Subtract it so the gizmo's pixel range [vp.y·rh, rh] maps to CSS [0%, vh%] from top.
            div.style.top  = (rect.top  + (p.y / rh - axesCam.viewport.y) * rect.height) + 'px';
        }
    });
}

// ── Studio environment map for realistic PBR reflections ─────────────────────

/**
 * Creates a simple studio-lighting cube texture for PBR environment reflections.
 * Without an environment map metallic PBR materials render flat/dark, so this
 * generates a lightweight procedural cubemap: bright top (softbox), mid-gray
 * sides, dark bottom.  The texture is cached per scene.
 * @param {BABYLON.Scene} scene
 * @param {string} canvasId
 */
function getOrCreateEnvironmentTexture(scene, canvasId) {
    if (environmentTextures[canvasId]) return environmentTextures[canvasId];

    const size = CONFIG.REALISTIC.environmentTextureSize || 512;

    /**
     * Generates a graduated studio-lighting cube face as a raw RGBA Uint8Array.
     * Identical visual output to the old canvas-gradient approach but fully
     * synchronous — no Image.onload latency — so PBR materials are lit correctly
     * on the very first rendered frame after file upload.
     *
     * @param {number} r - red 0-255
     * @param {number} g - green 0-255
     * @param {number} b - blue 0-255
     * @param {'top'|'bottom'|'side'} kind - gradient direction
     * @returns {Uint8Array} RGBA pixels, size×size×4 bytes
     */
    function rawFace(r, g, b, kind) {
        const pixels = new Uint8Array(size * size * 4);
        const cx = size / 2, cy = size / 2;
        for (let y = 0; y < size; y++) {
            for (let x = 0; x < size; x++) {
                let fr, fg, fb;

                if (kind === 'top') {
                    // Radial gradient: inner r=size*0.1, outer r=size*0.72
                    // stop 0 → bright, stop 0.45 → base, stop 1 → dark
                    const innerR = size * 0.1, outerR = size * 0.72;
                    const dist = Math.sqrt((x - cx) * (x - cx) + (y - cy) * (y - cy));
                    const t = Math.min(1, Math.max(0, (dist - innerR) / (outerR - innerR)));
                    if (t <= 0.45) {
                        const u = t / 0.45;
                        fr = Math.min(255, r + 30) * (1 - u) + r * u;
                        fg = Math.min(255, g + 30) * (1 - u) + g * u;
                        fb = Math.min(255, b + 22) * (1 - u) + b * u;
                    } else {
                        const u = (t - 0.45) / 0.55;
                        fr = r * (1 - u) + Math.max(0, r - 55) * u;
                        fg = g * (1 - u) + Math.max(0, g - 55) * u;
                        fb = b * (1 - u) + Math.max(0, b - 48) * u;
                    }
                } else if (kind === 'bottom') {
                    // Flat base with radial shadow overlay (centre 5% alpha → edge 55% alpha)
                    const innerR = size * 0.05, outerR = size * 0.8;
                    const dist = Math.sqrt((x - cx) * (x - cx) + (y - cy) * (y - cy));
                    const t = Math.min(1, Math.max(0, (dist - innerR) / (outerR - innerR)));
                    const shadow = 0.05 + t * 0.50;
                    fr = r * (1 - shadow);
                    fg = g * (1 - shadow);
                    fb = b * (1 - shadow);
                } else {
                    // Side — linear vertical gradient (top bright, bottom dark)
                    const t = y / (size - 1);
                    if (t <= 0.55) {
                        const u = t / 0.55;
                        fr = r - 18 * u;
                        fg = g - 18 * u;
                        fb = b - 18 * u;
                    } else {
                        const u = (t - 0.55) / 0.45;
                        fr = (r - 18) - 17 * u;
                        fg = (g - 18) - 17 * u;
                        fb = (b - 18) - 17 * u;
                    }
                }

                const idx = (y * size + x) * 4;
                pixels[idx]     = Math.round(Math.max(0, Math.min(255, fr)));
                pixels[idx + 1] = Math.round(Math.max(0, Math.min(255, fg)));
                pixels[idx + 2] = Math.round(Math.max(0, Math.min(255, fb)));
                pixels[idx + 3] = 255;
            }
        }
        return pixels;
    }

    // Studio lighting: bright softbox above, dark floor, neutral grey walls.
    // Face order for BabylonJS CubeTexture: [+X, -X, +Y, -Y, +Z, -Z]
    const sidePosX = rawFace(165, 165, 170, 'side');   // +X
    const sideNegX = rawFace(165, 165, 170, 'side');   // -X
    const top      = rawFace(238, 238, 232, 'top');     // +Y — overhead softbox
    const bottom   = rawFace(42,  42,  45,  'bottom'); // -Y — dark floor
    const sidePosZ = rawFace(165, 165, 170, 'side');   // +Z
    const sideNegZ = rawFace(155, 155, 160, 'side');   // -Z — slightly darker back wall

    // RawCubeTexture receives typed arrays directly — zero async I/O, zero Image.onload
    // latency. The old CubeTexture.CreateFromImages approach loaded PNG data-URLs through
    // the browser Image pipeline asynchronously, so PBR metallic materials (metallic≥0.9)
    // rendered black on first load because the environment map wasn't ready yet.
    const cube = new BABYLON.RawCubeTexture(
        scene,
        [sidePosX, sideNegX, top, bottom, sidePosZ, sideNegZ],
        size,
        BABYLON.Constants.TEXTUREFORMAT_RGBA,
        BABYLON.Constants.TEXTURETYPE_UNSIGNED_BYTE,
        true,   // generateMipMaps — needed for smooth specular highlights
        false,  // invertY
        BABYLON.Constants.TEXTURE_TRILINEAR_SAMPLINGMODE
    );

    scene.environmentTexture = cube;
    scene.environmentIntensity = CONFIG.REALISTIC.environmentIntensity;

    // Image processing for realistic rendering.
    // Standard tone mapping (linear + gamma) is used instead of ACES because
    // ACES was designed for HDR cinematic content and compresses mid-range
    // palette colours (e.g. white POM at 0.95 reads as grey under ACES).
    scene.imageProcessingConfiguration.contrast = CONFIG.REALISTIC.contrast;
    scene.imageProcessingConfiguration.exposure = CONFIG.REALISTIC.exposure;
    scene.imageProcessingConfiguration.toneMappingEnabled = true;
    scene.imageProcessingConfiguration.toneMappingType =
        BABYLON.ImageProcessingConfiguration.TONEMAPPING_STANDARD;

    environmentTextures[canvasId] = cube;
    return cube;
}

// ── FDM layer-line MaterialPlugin ─────────────────────────────────────────────
// Simulates FDM printing layer lines as a world-space Y-periodic surface darkening.
// UV-independent: works on any GLB regardless of UV quality.
// Applied only to FDM plastic presets in realistic mode.

const FDM_LAYER_PRESET_KEYS = new Set(['pla', 'abs', 'petg', 'nylon', 'peek', 'carbon-fiber']);
const ADDITIVE_LAYER_PRESET_KEYS = new Set([
    ...FDM_LAYER_PRESET_KEYS,
    'petg-clear',
    'resin',
    'nylon-powder',
]);
const INTRINSIC_COLOR_PRESET_KEYS = new Set(['black-pom', 'white-pom', 'blue-pom']);
const FDM_LAYER_EFFECT_KEY = 'fdm-layer-lines';

let FdmLayerPluginClass = null;

function getFdmLayerPluginClass() {
    if (FdmLayerPluginClass) return FdmLayerPluginClass;

    FdmLayerPluginClass = class FdmLayerPlugin extends BABYLON.MaterialPluginBase {
        constructor(material, layerHeightMm) {
            super(material, 'FdmLayer', 200, { FDMLAYER: false });
            this._layerHeightMm = layerHeightMm || 0.2;
            // Activate through Babylon's plugin API so shader defines are compiled.
            this._isEnabled = true;
            this._enable(this._isEnabled);
        }

        getClassName() { return 'FdmLayerPlugin'; }

        prepareDefines(defines) {
            defines.FDMLAYER = this._isEnabled;
        }

        getUniforms() {
            // Declare the uniform via the UBO path; BabylonJS injects it into the shader automatically
            return { ubo: [{ name: 'fdmLayerH', size: 1, type: 'float' }] };
        }

        bindForSubMesh(uniformBuffer) {
            if (this._isEnabled) uniformBuffer.updateFloat('fdmLayerH', this._layerHeightMm);
        }

        getCustomCode(shaderType) {
            if (shaderType !== 'fragment') return null;
            return {
                // Inject after all PBR lighting is resolved, before the final gl_FragColor write.
                // 'finalColor' is the vec4 final fragment colour available at this injection point.
                // 'vPositionW' is the world-space position (in mm after model scaling).
                CUSTOM_FRAGMENT_BEFORE_FRAGCOLOR: `
                #ifdef FDMLAYER
                {
                    // Periodic groove at each layer boundary (Z = viewer vertical / stacking axis)
                    float _lPhase = vPositionW.z / max(fdmLayerH, 0.001);
                    float _ridge  = sin(_lPhase * 6.28318) * 0.5 + 0.5; // 1 = layer centre, 0 = boundary
                    // Narrow dark groove at boundaries; transparent preset skips (alpha already < 1)
                    float _groove = smoothstep(0.70, 1.0, 1.0 - _ridge) * 0.18;
                    finalColor.rgb *= (1.0 - _groove);
                }
                #endif
            `,
            };
        }
    };

    return FdmLayerPluginClass;
}

// ── Procedural manufacturing-surface MaterialPlugin ──────────────────────────
// Adds subtle, UV-independent finish/process texture in realistic mode.
// Effects are intentionally visual-only: they perturb the shaded colour and lighting normal, not geometry.

// scale / stripeScale are world-space frequencies (approx cycles per mm): grain/mark spacing is approx
// 1/scale mm (noise) or 2*pi/stripeScale mm (stripes). `bump` drives visible height-relief contrast; strength +
// stripeStrength drive the roughness wobble. The noise is band-limited so the surface stays stable
// under the idle camera orbit.
const SURFACE_EFFECTS = {
    none: {
        key: 'none',
        kind: 0,
        scale: 1.0,
        strength: 0.0,
        stripeScale: 0.0,
        stripeStrength: 0.0,
        bump: 0.0,
    },
    'bead-blast': {
        key: 'bead-blast',
        kind: 1,
        scale: 6.5,        // ~0.15 mm isotropic micrograin for satin bead-blasted aluminum
        strength: 0.075,
        stripeScale: 0.0,
        stripeStrength: 0.0,
        bump: 0.065,       // fine crater normal bump; bead blasting should not look ridged
    },
    brushed: {
        key: 'brushed',
        kind: 2,
        scale: 1.5,
        strength: 0.03,
        stripeScale: 6.0,  // ~1.0 mm unidirectional brush lines
        stripeStrength: 0.09,
        bump: 0.09,
    },
    machining: {
        key: 'machining',
        kind: 4,           // orientation-aware CNC tool marks (face vs side milling); distinct from brushed (2)
        scale: 1.0,
        strength: 0.012,
        stripeScale: 4.2,  // fine raw-machined feed marks for bright steel/stainless reflections
        stripeStrength: 0.020,
        bump: 0.014,       // subtle tool-mark normal bump; raw steel should be polished, not gouged
    },
    'powder-grain': {
        key: 'powder-grain',
        kind: 3,
        scale: 1.2,        // ~0.83 mm sintered grain
        strength: 0.13,
        stripeScale: 0.0,
        stripeStrength: 0.0,
        bump: 0.15,
    },
};

let SurfaceEffectPluginClass = null;

function getSurfaceEffect(effectKey) {
    if (!effectKey) return { ...SURFACE_EFFECTS.none };
    return { ...(SURFACE_EFFECTS[effectKey] || SURFACE_EFFECTS.none) };
}

function isPowderBedProcess(processCode) {
    const process = String(processCode || '').trim().toUpperCase();
    return process === 'MJF' || process === 'SLS' || process === 'SLS_PA' || process === 'SJS';
}

function isCncProcess(processCode) {
    const process = String(processCode || '').trim().toUpperCase();
    return process === 'CNC' || process === 'CNC_MILL' || process === 'CNC_TURN' || process.startsWith('CNC_');
}

function shouldApplyMachiningEffect(finishCode) {
    const lower = String(finishCode || '').toLowerCase();
    if (!lower) return true;
    if (lower.includes('bead') || lower.includes('blast') || lower.includes('polish')
        || lower.includes('brush') || lower.includes('paint') || lower.includes('plate')) {
        return false;
    }

    return lower.includes('machine')
        || lower.includes('machined')
        || lower.includes('mill')
        || lower.includes('turn')
        || lower.includes('ra')
        || lower.includes('standard')
        || lower.includes('as_')
        || lower.includes('raw')
        || lower.includes('unfinished');
}

function resolveSurfaceEffect(processCode, materialKey, finishCode, finishModifiers) {
    if (finishModifiers?.surfaceEffectKey) {
        return getSurfaceEffect(finishModifiers.surfaceEffectKey);
    }

    if (isPowderBedProcess(processCode) || materialKey === 'nylon-powder') {
        return getSurfaceEffect('powder-grain');
    }

    if (isCncProcess(processCode) && shouldApplyMachiningEffect(finishCode)) {
        return getSurfaceEffect('machining');
    }

    return getSurfaceEffect(null);
}

function getSurfaceEffectPluginClass() {
    if (SurfaceEffectPluginClass) return SurfaceEffectPluginClass;

    SurfaceEffectPluginClass = class SurfaceEffectPlugin extends BABYLON.MaterialPluginBase {
        constructor(material, effect) {
            super(material, 'MalievSurfaceEffect', 210, { MALIEV_SURFACE_EFFECT: false });
            this._effect = getSurfaceEffect(effect?.key);
            material._malievSurfaceEffect = this._effect;
            this._isEnabled = this._effect.kind > 0;
            this._enable(this._isEnabled);
        }

        getClassName() { return 'SurfaceEffectPlugin'; }

        prepareDefines(defines) {
            defines.MALIEV_SURFACE_EFFECT = this._isEnabled;
        }

        getUniforms() {
            return {
                ubo: [
                    { name: 'surfaceEffectKind', size: 1, type: 'float' },
                    { name: 'surfaceEffectScale', size: 1, type: 'float' },
                    { name: 'surfaceEffectStrength', size: 1, type: 'float' },
                    { name: 'surfaceEffectStripeScale', size: 1, type: 'float' },
                    { name: 'surfaceEffectStripeStrength', size: 1, type: 'float' },
                    { name: 'surfaceEffectBump', size: 1, type: 'float' },
                ],
            };
        }

        bindForSubMesh(uniformBuffer) {
            if (!this._isEnabled) return;
            uniformBuffer.updateFloat('surfaceEffectKind', this._effect.kind);
            uniformBuffer.updateFloat('surfaceEffectScale', this._effect.scale);
            uniformBuffer.updateFloat('surfaceEffectStrength', this._effect.strength);
            uniformBuffer.updateFloat('surfaceEffectStripeScale', this._effect.stripeScale);
            uniformBuffer.updateFloat('surfaceEffectStripeStrength', this._effect.stripeStrength);
            uniformBuffer.updateFloat('surfaceEffectBump', this._effect.bump || 0.0);
        }

        getCustomCode(shaderType) {
            if (shaderType !== 'fragment') return null;
            return {
                CUSTOM_FRAGMENT_DEFINITIONS: `
                #ifdef MALIEV_SURFACE_EFFECT
                float malievHash3(vec3 p) {
                    return fract(sin(dot(p, vec3(12.9898, 78.233, 37.719))) * 43758.5453123);
                }
                vec2 malievHash2(vec2 p) {
                    return fract(sin(vec2(
                        dot(p, vec2(127.1, 311.7)),
                        dot(p, vec2(269.5, 183.3)))) * 43758.5453123);
                }
                // Smooth, band-limited value noise in world space, stable under camera motion
                // (no high-frequency aliasing, no screen-space derivatives) so it stays flicker-free.
                float malievVNoise(vec3 x) {
                    vec3 i = floor(x);
                    vec3 f = fract(x);
                    f = f * f * (3.0 - 2.0 * f);
                    float n000 = malievHash3(i + vec3(0.0, 0.0, 0.0));
                    float n100 = malievHash3(i + vec3(1.0, 0.0, 0.0));
                    float n010 = malievHash3(i + vec3(0.0, 1.0, 0.0));
                    float n110 = malievHash3(i + vec3(1.0, 1.0, 0.0));
                    float n001 = malievHash3(i + vec3(0.0, 0.0, 1.0));
                    float n101 = malievHash3(i + vec3(1.0, 0.0, 1.0));
                    float n011 = malievHash3(i + vec3(0.0, 1.0, 1.0));
                    float n111 = malievHash3(i + vec3(1.0, 1.0, 1.0));
                    float nx00 = mix(n000, n100, f.x);
                    float nx10 = mix(n010, n110, f.x);
                    float nx01 = mix(n001, n101, f.x);
                    float nx11 = mix(n011, n111, f.x);
                    return mix(mix(nx00, nx10, f.y), mix(nx01, nx11, f.y), f.z);
                }
                float malievSurfaceSpeckle(vec3 p, float kind, float scl) {
                    float cellScale = kind < 1.5 ? max(scl, 2.0) : max(scl * 1.35, 1.0);
                    return malievVNoise(p * cellScale) * 0.68
                        + malievVNoise(p * cellScale * 2.35 + vec3(17.0, 31.0, 11.0)) * 0.32;
                }
                vec2 malievBeadSurfaceUv(vec3 p, vec3 n, float scl) {
                    vec3 an = abs(n);
                    if (an.z >= an.x && an.z >= an.y) {
                        return p.xy * scl;
                    }
                    if (an.x >= an.y) {
                        return p.yz * scl;
                    }
                    return p.xz * scl;
                }
                float malievBeadCraterLayer(vec2 uv) {
                    vec2 cell = floor(uv);
                    vec2 f = fract(uv);
                    float pit = 0.0;
                    for (int ix = -1; ix <= 1; ix++) {
                        for (int iy = -1; iy <= 1; iy++) {
                            vec2 g = vec2(float(ix), float(iy));
                            vec2 rnd = malievHash2(cell + g);
                            vec2 center = g + rnd;
                            float d = length(f - center);
                            float radius = 0.26 + rnd.y * 0.12;
                            float bowl = pow(1.0 - smoothstep(0.0, radius, d), 2.0);
                            float rim = smoothstep(radius * 0.56, radius, d)
                                * (1.0 - smoothstep(radius, radius * 1.36, d));
                            pit = max(pit, bowl * (0.62 + rnd.x * 0.30) - rim * 0.14);
                        }
                    }
                    return clamp(1.0 - pit * 0.78, 0.0, 1.0);
                }
                float malievBeadCraterHeight(vec3 p, vec3 n, float scl) {
                    vec2 uv = malievBeadSurfaceUv(p, n, max(scl, 0.0001));
                    float primary = malievBeadCraterLayer(uv);
                    float secondary = malievBeadCraterLayer(uv * 1.83 + vec2(13.7, 29.1));
                    float dust = malievVNoise(p * scl * 3.1 + vec3(5.0, 19.0, 37.0));
                    return clamp(primary * 0.70 + secondary * 0.24 + dust * 0.06, 0.0, 1.0);
                }
                float malievBeadCraterFootprint(vec3 p, vec3 n, float scl) {
                    vec2 uv = malievBeadSurfaceUv(p, n, max(scl, 0.0001));
                    return max(length(dFdx(uv)), length(dFdy(uv)));
                }
                vec3 malievBeadCraterGradient(vec3 p, vec3 n, float scl) {
                    float e = max(0.012, 0.15 / max(scl, 0.0001));
                    float hx = malievBeadCraterHeight(p + vec3(e, 0.0, 0.0), n, scl)
                        - malievBeadCraterHeight(p - vec3(e, 0.0, 0.0), n, scl);
                    float hy = malievBeadCraterHeight(p + vec3(0.0, e, 0.0), n, scl)
                        - malievBeadCraterHeight(p - vec3(0.0, e, 0.0), n, scl);
                    float hz = malievBeadCraterHeight(p + vec3(0.0, 0.0, e), n, scl)
                        - malievBeadCraterHeight(p - vec3(0.0, 0.0, e), n, scl);
                    vec3 gradient = vec3(hx, hy, hz) / (2.0 * e);
                    return gradient - n * dot(gradient, n);
                }
                // Procedural micro-surface HEIGHT in [0,1] for the selected finish (world-space, UV-free).
                // Its value drives albedo grain and roughness wobble.
                // 'up' = |geometric normal . Z| so CNC marks switch between face- and side-milling.
                float malievHeight(vec3 p, float kind, float scl, float sScl, float up) {
                    scl = max(scl, 0.0001);
                    if (kind < 1.5) {
                        // Bead blasted: 2-octave isotropic grain.
                        float smoothGrain = malievVNoise(p * scl) * 0.65 + malievVNoise(p * scl * 2.7) * 0.35;
                        return smoothGrain * 0.58 + malievSurfaceSpeckle(p, kind, scl) * 0.42;
                    } else if (kind < 2.5) {
                        // Brushed: unidirectional fine lines (along world X) + faint noise.
                        float lines = sin(p.y * sScl) * 0.5 + 0.5;
                        return lines * 0.78 + malievVNoise(vec3(p.x * scl * 3.0, p.y * scl, p.z * scl)) * 0.22;
                    } else if (kind < 3.5) {
                        // Powder (MJF/SLS): coarse 2-octave sintered grain.
                        return malievVNoise(p * scl) * 0.6 + malievVNoise(p * scl * 2.3) * 0.4;
                    }
                    // CNC as-machined: face milling (top/bottom) vs side milling (walls).
                    float fa = sin(p.x * sScl) * 0.5 + 0.5;        // feed cross-hatch in XY
                    float fb = sin(p.y * sScl * 0.92 + 1.7) * 0.5 + 0.5;
                    float faceMark = fa * 0.6 + fb * 0.4;
                    float sideMark = sin(p.z * sScl * 1.7) * 0.5 + 0.5; // scallop lines stacked along wall height
                    return mix(sideMark, faceMark, up);
                }
                vec3 malievHeightGradient(vec3 p, float kind, float scl, float sScl, float up) {
                    float e = max(0.12, 0.35 / max(scl, 0.0001));
                    float hx = malievHeight(p + vec3(e, 0.0, 0.0), kind, scl, sScl, up)
                        - malievHeight(p - vec3(e, 0.0, 0.0), kind, scl, sScl, up);
                    float hy = malievHeight(p + vec3(0.0, e, 0.0), kind, scl, sScl, up)
                        - malievHeight(p - vec3(0.0, e, 0.0), kind, scl, sScl, up);
                    float hz = malievHeight(p + vec3(0.0, 0.0, e), kind, scl, sScl, up)
                        - malievHeight(p - vec3(0.0, 0.0, e), kind, scl, sScl, up);
                    return vec3(hx, hy, hz) / (2.0 * e);
                }
                float malievSurfaceRelief(vec3 p, float kind, float scl, float sScl, float bump, float up) {
                    vec3 baseNormal = normalize(cross(dFdx(p), dFdy(p)));
                    baseNormal *= gl_FrontFacing ? 1.0 : -1.0;
                    vec3 gradient = malievHeightGradient(p, kind, scl, sScl, up);
                    vec3 reliefNormal = normalize(baseNormal - gradient * bump * 3.2);
                    vec3 keyLight = normalize(vec3(-0.38, -0.58, 0.72));
                    return clamp(dot(reliefNormal, keyLight) - dot(baseNormal, keyLight), -0.35, 0.35);
                }
                #endif
            `,
                CUSTOM_FRAGMENT_BEFORE_LIGHTS: `
                #ifdef MALIEV_SURFACE_EFFECT
                {
                    float _isBead = 1.0 - step(1.5, surfaceEffectKind);
                    float _isMachined = step(3.5, surfaceEffectKind);
                    if (_isBead > 0.5) {
                        vec3 _beadBaseNormal = normalize(normalW);
                        vec3 _beadCraterGradient = malievBeadCraterGradient(
                            vPositionW,
                            _beadBaseNormal,
                            surfaceEffectScale);
                        float _beadCraterFootprint = malievBeadCraterFootprint(
                            vPositionW,
                            _beadBaseNormal,
                            surfaceEffectScale);
                        float _beadCraterAa = 1.0 - smoothstep(0.38, 1.05, _beadCraterFootprint);
                        normalW = normalize(_beadBaseNormal - _beadCraterGradient * surfaceEffectBump * 2.0 * _beadCraterAa);
                    } else if (_isMachined > 0.5) {
                        vec3 _machinedBaseNormal = normalize(normalW);
                        float _machinedUp = abs(_machinedBaseNormal.z);
                        vec3 _machinedGradient = malievHeightGradient(
                            vPositionW,
                            surfaceEffectKind,
                            surfaceEffectScale,
                            surfaceEffectStripeScale,
                            _machinedUp);
                        float _machinedFootprint = max(
                            length(dFdx(vPositionW * surfaceEffectStripeScale)),
                            length(dFdy(vPositionW * surfaceEffectStripeScale)));
                        float _machinedAa = 1.0 - smoothstep(0.75, 1.65, _machinedFootprint);
                        normalW = normalize(_machinedBaseNormal - _machinedGradient * surfaceEffectBump * 0.16 * _machinedAa);
                    }
                }
                #endif
            `,
                CUSTOM_FRAGMENT_UPDATE_ALBEDO: `
                #ifdef MALIEV_SURFACE_EFFECT
                {
                    // Subtle albedo variation supports the bump map without making bead blast look painted on.
                    float _up = abs(normalize(cross(dFdx(vPositionW), dFdy(vPositionW))).z);
                    float _h = malievHeight(vPositionW, surfaceEffectKind, surfaceEffectScale, surfaceEffectStripeScale, _up);
                    float _speckle = malievSurfaceSpeckle(vPositionW, surfaceEffectKind, surfaceEffectScale);
                    float _isBead = 1.0 - step(1.5, surfaceEffectKind);
                    float _relief = malievSurfaceRelief(
                        vPositionW,
                        surfaceEffectKind,
                        surfaceEffectScale,
                        surfaceEffectStripeScale,
                        surfaceEffectBump,
                        _up);
                    float _grainAmplitude = mix(surfaceEffectBump, surfaceEffectStrength, _isBead);
                    float _grain = (_h - 0.5) * _grainAmplitude * mix(0.72, 0.04, _isBead)
                        + (_speckle - 0.5) * _grainAmplitude * mix(0.24, 0.03, _isBead);
                    surfaceAlbedo *= clamp(
                        1.0 + _grain + _relief * mix(0.22, 0.0, _isBead),
                        mix(0.75, 0.97, _isBead),
                        mix(1.20, 1.03, _isBead));
                }
                #endif
            `,
                CUSTOM_FRAGMENT_UPDATE_METALLICROUGHNESS: `
                #ifdef MALIEV_SURFACE_EFFECT
                {
                    // Roughness grain: view-dependent light/dark micro-scatter that reads like relief and
                    // (because it feeds reflection blur) shows on metals too.
                    float _up = abs(normalize(cross(dFdx(vPositionW), dFdy(vPositionW))).z);
                    float _h = malievHeight(vPositionW, surfaceEffectKind, surfaceEffectScale, surfaceEffectStripeScale, _up);
                    float _speckle = malievSurfaceSpeckle(vPositionW, surfaceEffectKind, surfaceEffectScale);
                    float _ra = surfaceEffectStrength + surfaceEffectStripeStrength + surfaceEffectBump * 0.35;
                    float _isBead = 1.0 - step(1.5, surfaceEffectKind);
                    metallicRoughness.g = clamp(
                        metallicRoughness.g
                            + ((_h - 0.5) * mix(0.72, 0.10, _isBead)
                                + (_speckle - 0.5) * mix(0.45, 0.08, _isBead))
                                * _ra * mix(1.6, 0.45, _isBead),
                        0.06,
                        1.0);
                }
                #endif
            `,
                CUSTOM_FRAGMENT_BEFORE_FRAGCOLOR: `
                #ifdef MALIEV_SURFACE_EFFECT
                {
                    // Final lit-color relief makes bead blasting read as surface texture instead of only
                    // as a flatter roughness preset.
                    float _finalUp = abs(normalize(cross(dFdx(vPositionW), dFdy(vPositionW))).z);
                    float _finalH = malievHeight(
                        vPositionW,
                        surfaceEffectKind,
                        surfaceEffectScale,
                        surfaceEffectStripeScale,
                        _finalUp);
                    float _finalSpeckle = malievSurfaceSpeckle(
                        vPositionW,
                        surfaceEffectKind,
                        surfaceEffectScale);
                    float _isBead = 1.0 - step(1.5, surfaceEffectKind);
                    float _finalBeadH = malievBeadCraterHeight(vPositionW, normalize(normalW), surfaceEffectScale);
                    float _finalSurfaceH = mix(_finalH, _finalBeadH, _isBead);
                    float _finalRelief = malievSurfaceRelief(
                        vPositionW,
                        surfaceEffectKind,
                        surfaceEffectScale,
                        surfaceEffectStripeScale,
                        surfaceEffectBump,
                        _finalUp);
                    finalColor.rgb *= clamp(
                        1.0
                            + (_finalSurfaceH - 0.5) * mix(surfaceEffectBump, surfaceEffectStrength, _isBead) * mix(0.55, 0.02, _isBead)
                            + (_finalSpeckle - 0.5) * mix(surfaceEffectBump, surfaceEffectStrength, _isBead) * mix(0.24, 0.015, _isBead)
                            + _finalRelief * mix(0.18, 0.0, _isBead),
                        mix(0.78, 0.97, _isBead),
                        mix(1.18, 1.03, _isBead));
                }
                #endif
            `,
            };
        }
    };

    return SurfaceEffectPluginClass;
}

// ── Realistic material ─────────────────────────────────────────────────────────

function configureRealisticPbrQuality(pbr) {
    if (!pbr) return;

    // Geometric specular anti-aliasing tames metallic shimmer cheaply.
    // NOTE: realTimeFiltering was intentionally removed; it ran per-pixel IBL
    // prefiltering (64 samples) on a *static* studio cube that is already mip +
    // SH prefiltered. It was expensive (mobile-hostile) and a driver-dependent
    // instability source; the prefiltered environment gives stable specular IBL.
    pbr.enableSpecularAntiAliasing = true;
}

function isFdmProcess(processCode) {
    const process = String(processCode || '').trim().toUpperCase();
    return process === 'FDM' || process === 'FDM_3D_PRINTING' || process === 'FFF';
}

function isLayeredAdditiveProcess(processCode) {
    const process = String(processCode || '').trim().toUpperCase();
    return isFdmProcess(process)
        || process === 'SLA'
        || process === 'SLA_DLP'
        || process === 'DLP'
        || process === 'MJF'
        || process === 'SLS'
        || process === 'SLS_PA'
        || process === 'SJS';
}

function getAdditiveLayerLineStrength(canvasId, materialType) {
    const processCode = perCanvasProcessCodes[canvasId];
    if (!ADDITIVE_LAYER_PRESET_KEYS.has(materialType) || !isLayeredAdditiveProcess(processCode)) {
        return 0;
    }

    if (isPowderBedProcess(processCode)) return 0.010;
    if (isFdmProcess(processCode)) return 0.022;
    return 0.016;
}

function shouldApplyFdmLayerLines(canvasId, materialType) {
    return getAdditiveLayerLineStrength(canvasId, materialType) > 0;
}

function resolveRealisticNodeMaterialProfile(canvasId, materialType) {
    const surfaceEffect = perCanvasSurfaceEffects[canvasId] || getSurfaceEffect(null);
    const layerLineStrength = getAdditiveLayerLineStrength(canvasId, materialType);
    const processCode = perCanvasProcessCodes[canvasId];
    const profile = {
        surfaceEffectKey: surfaceEffect.kind > 0 ? surfaceEffect.key : null,
        normalStrength: 0,
        noiseScale: 0,
        stripeAxis: 'x',
        stripeScale: 0,
        stripeStrength: 0,
        stripeWaveform: 'sine',
        layerAxis: 'z',
        layerHeightMm: layerLineStrength > 0
            ? isFdmProcess(processCode)
                ? 0.9
                : isPowderBedProcess(processCode)
                    ? 1.35
                    : 1.1
            : 0,
        layerLineStrength,
        layerWaveform: 'sine',
    };

    if (surfaceEffect.key === 'bead-blast') {
        profile.normalStrength = 0.006;
        profile.noiseScale = 6.5;
    } else if (surfaceEffect.key === 'brushed') {
        profile.normalStrength = 0.010;
        profile.noiseScale = 0.035;
        profile.stripeAxis = 'x';
        profile.stripeScale = 0.90;
        profile.stripeStrength = 0.020;
    } else if (surfaceEffect.key === 'machining') {
        profile.normalStrength = 0.004;
        profile.noiseScale = 0.025;
        profile.stripeAxis = 'x';
        profile.stripeScale = 0.34;
        profile.stripeStrength = 0.012;
    } else if (surfaceEffect.key === 'powder-grain') {
        profile.normalStrength = 0.018;
        profile.noiseScale = 0.48;
    }

    if (layerLineStrength > 0 && !profile.surfaceEffectKey) {
        profile.surfaceEffectKey = FDM_LAYER_EFFECT_KEY;
    }

    return profile;
}

function syncRealisticMaterialProperties(material, preset, custom, finishMod, profile) {
    if (!material || !preset) return;

    const albedo = custom ? toColor3(custom) : toColor3(preset.albedoColor);
    const metallic = clamp(preset.metallic + (finishMod?.metallicOffset || 0), 0, 1);
    const roughness = finishMod?.absoluteRoughness != null
        ? finishMod.absoluteRoughness
        : clamp(preset.roughness + (finishMod?.roughnessOffset || 0), 0, 1);

    if (material.albedoColor?.set) {
        material.albedoColor.set(albedo.r, albedo.g, albedo.b);
    } else {
        material.albedoColor = albedo;
    }

    material.metallic = metallic;
    material.roughness = roughness;
    material._malievNodeMaterialProfile = profile;

    if (material._malievNodeInputs) {
        material._malievNodeInputs.baseColor.value = albedo;
        material._malievNodeInputs.metallic.value = metallic;
        material._malievNodeInputs.roughness.value = roughness;
        material._malievNodeInputs.alpha.value = preset.alpha ?? 1;
    }

    if (preset.alpha != null && preset.alpha < 1.0) {
        material.alpha = preset.alpha;
        material.transparencyMode = 2; // BABYLON.Material.MATERIAL_ALPHABLEND
        material.needDepthPrePass = true;
    } else {
        material.alpha = 1;
        material.transparencyMode = BABYLON.Material?.MATERIAL_OPAQUE ?? 0;
        material.needDepthPrePass = false;
    }
}

function createRealisticPbrMaterial(scene, canvasId, materialType, preset) {
    const custom = customAlbedoColors[canvasId];
    const finishMod = perCanvasFinishModifiers[canvasId] || { roughnessOffset: 0, metallicOffset: 0 };
    const profile = resolveRealisticNodeMaterialProfile(canvasId, materialType);

    const pbr = new BABYLON.PBRMaterial(`__realistic_${materialType}__`, scene);
    configureRealisticPbrQuality(pbr);
    syncRealisticMaterialProperties(pbr, preset, custom, finishMod, profile);

    // Translucent materials (e.g. clear PETG): alpha < 1 gives a frosted/milky look
    if (preset.alpha != null && preset.alpha < 1.0) {
        pbr.alpha            = preset.alpha;
        pbr.transparencyMode = 2; // BABYLON.Material.MATERIAL_ALPHABLEND
        pbr.needDepthPrePass = true;
    }

    // FDM layer-line simulation: attach plugin to FDM plastic presets (UV-independent world-space effect)
    if (shouldApplyFdmLayerLines(canvasId, materialType)) {
        const FdmLayerPlugin = getFdmLayerPluginClass();
        new FdmLayerPlugin(pbr, 0.2); // 0.2 mm default layer height
    }

    const surfaceEffect = perCanvasSurfaceEffects[canvasId] || getSurfaceEffect(null);
    if (surfaceEffect.kind > 0) {
        const SurfaceEffectPlugin = getSurfaceEffectPluginClass();
        new SurfaceEffectPlugin(pbr, surfaceEffect);
    }

    pbr._malievMaterialPipeline = 'pbr-plugin-fallback';
    pbr._malievNodeMaterialProfile = profile;
    return pbr;
}

/**
 * Returns (or lazily creates) a realistic material for the given material type.
 * Each material type is cached per canvas so it is shared across all meshes.
 * @param {BABYLON.Scene} scene
 * @param {string} canvasId
 * @param {string} materialType - key in CONFIG.MATERIAL_REALISTIC
 * @returns {BABYLON.Material}
 */
function getRealisticMaterial(scene, canvasId, materialType) {
    if (!realisticMaterialCache[canvasId]) realisticMaterialCache[canvasId] = {};
    const cache = realisticMaterialCache[canvasId];

    if (cache[materialType]) return cache[materialType];

    const preset = CONFIG.MATERIAL_REALISTIC[materialType]
                || CONFIG.MATERIAL_REALISTIC['aluminum'];

    // Realistic materials are PBRMaterial + MaterialPlugins. The previous
    // hand-wired NodeMaterial graph rendered metals black (its ReflectionBlock
    // was never given a texture) and was the realistic-only flicker source.
    const pbr = createRealisticPbrMaterial(scene, canvasId, materialType, preset);

    cache[materialType] = pbr;
    return pbr;
}

function detachCachedRealisticMaterial(canvasId, materialType) {
    const cache = realisticMaterialCache[canvasId];
    if (!cache) return null;

    const material = cache[materialType] || null;
    delete cache[materialType];
    return material;
}

function detachAllCachedRealisticMaterials(canvasId) {
    const cache = realisticMaterialCache[canvasId];
    if (!cache) return [];

    const materials = Object.values(cache).filter(Boolean);
    realisticMaterialCache[canvasId] = {};
    return materials;
}

function disposeDetachedMaterial(material) {
    try { material?.dispose?.(); } catch (_) {}
}

function normalizeConfiguratorToken(value) {
    return String(value ?? '').trim().toUpperCase();
}

function resolveConfiguratorCustomAlbedo(materialKey, colorHex) {
    if (!colorHex || !/^#[0-9a-fA-F]{6}$/.test(colorHex) || INTRINSIC_COLOR_PRESET_KEYS.has(materialKey)) {
        return { color: null, key: '' };
    }

    const r = parseInt(colorHex.slice(1, 3), 16) / 255;
    const g = parseInt(colorHex.slice(3, 5), 16) / 255;
    const b = parseInt(colorHex.slice(5, 7), 16) / 255;
    if (isNaN(r) || isNaN(g) || isNaN(b)) {
        return { color: null, key: '' };
    }

    return {
        color: { r, g, b },
        key: colorHex.toLowerCase(),
    };
}

function getConfiguratorStateKey(materialKey, colorKey, finishCode, roughnessCode, processCode) {
    return [
        materialKey,
        colorKey,
        normalizeConfiguratorToken(finishCode),
        normalizeConfiguratorToken(roughnessCode),
        normalizeConfiguratorToken(processCode),
    ].join('|');
}

function isCachedRealisticMaterialAssigned(canvasId, materialType) {
    const scene = scenes[canvasId];
    const material = realisticMaterialCache[canvasId]?.[materialType];
    if (!scene || !material) return false;

    return scene.meshes.some(mesh => !isSystemMesh(mesh) && mesh.material === material);
}

/**
 * Applies the selected realistic material to all model meshes in the scene.
 * Multi-body assemblies receive the same shared configurator-colour material
 * so all bodies look uniform in realistic mode.  Original per-body materials
 * are never mutated — they are restored intact on switch back to solid.
 */
function applyRealisticMaterial(canvasId, materialType) {
    const scene = scenes[canvasId];
    if (!scene) return;

    // Ensure an environment texture exists for metallic reflections.
    getOrCreateEnvironmentTexture(scene, canvasId);

    const finishMod = perCanvasFinishModifiers[canvasId] || { roughnessOffset: 0, metallicOffset: 0 };

    scene.meshes.forEach(mesh => {
        if (isSystemMesh(mesh)) return;

        mesh.material = getRealisticMaterial(scene, canvasId, materialType);
        const preset = CONFIG.MATERIAL_REALISTIC[materialType]
                    || CONFIG.MATERIAL_REALISTIC['aluminum'];
        syncRealisticMaterialProperties(
            mesh.material,
            preset,
            customAlbedoColors[canvasId],
            finishMod,
            resolveRealisticNodeMaterialProfile(canvasId, materialType));
    });
}

/**
 * Sets the material type for realistic rendering mode and applies it immediately.
 * Callable from Blazor via JS interop.
 * @param {string} canvasId
 * @param {string} materialType - key in CONFIG.MATERIAL_REALISTIC
 */
export function setMaterialType(canvasId, materialType) {
    if (!CONFIG.MATERIAL_REALISTIC[materialType]) {
        console.warn(`[BabylonViewer] Unknown material type: ${materialType}, falling back to aluminum`);
        materialType = 'aluminum';
    }
    console.log(`[BabylonViewer] setMaterialType canvas=${canvasId} type=${materialType}`);

    // Clear custom color override so the preset albedo is restored
    delete customAlbedoColors[canvasId];
    perCanvasSurfaceEffects[canvasId] = getSurfaceEffect(null);
    perCanvasFinishModifiers[canvasId] = { roughnessOffset: 0, metallicOffset: 0 };
    delete perCanvasProcessCodes[canvasId];
    delete realisticConfiguratorStateKeys[canvasId];

    const detachedMaterials = detachAllCachedRealisticMaterials(canvasId);
    materialTypes[canvasId] = materialType;
    applyRealisticMaterial(canvasId, materialType);
    detachedMaterials.forEach(disposeDetachedMaterial);
}

/**
 * Overrides the albedo colour of all realistic materials on the fly.
 * Callable from Blazor on every colour-picker change for real-time feedback.
 * @param {string} canvasId
 * @param {string} hexColor - e.g. "#ff8800"
 */
export function setMaterialColor(canvasId, hexColor) {
    const scene = scenes[canvasId];
    if (!scene) return;

    const r = parseInt(hexColor.slice(1, 3), 16) / 255;
    const g = parseInt(hexColor.slice(3, 5), 16) / 255;
    const b = parseInt(hexColor.slice(5, 7), 16) / 255;

    if (isNaN(r) || isNaN(g) || isNaN(b)) return;

    customAlbedoColors[canvasId] = { r, g, b };
    delete realisticConfiguratorStateKeys[canvasId];

    // Update albedo in-place on all cached realistic materials
    const cache = realisticMaterialCache[canvasId];
    if (cache) {
        Object.entries(cache).forEach(([key, mat]) => {
            const preset = CONFIG.MATERIAL_REALISTIC[key];
            if (!preset) return;
            syncRealisticMaterialProperties(
                mat,
                preset,
                customAlbedoColors[canvasId],
                perCanvasFinishModifiers[canvasId] || { roughnessOffset: 0, metallicOffset: 0 },
                resolveRealisticNodeMaterialProfile(canvasId, key));
        });
    }
}

/**
 * Maps a configurator material key to a realistic PBR preset and applies it along
 * with an optional custom colour, surface finish, and Ra roughness. Called from Blazor
 * when the user selects a material, colour, finish, or roughness in the PartConfigSidebar.
 * @param {string} canvasId
 * @param {string} materialKey - sanitised key matching a CONFIG.MATERIAL_REALISTIC entry
 * @param {string|null} colorHex - optional hex colour override (e.g. "#2f6fd6")
 * @param {string} finishCode - optional surface finish code (e.g. "anodized", "")
 * @param {string|null} roughnessCode - optional Ra roughness code (e.g. "RA_3_2", "RA_1_6", "RA_0_8")
 * @param {string|null} processCode - optional manufacturing process code (e.g. "CNC_MILL", "MJF", "SLS")
 */
export function configureMaterialFromConfigurator(canvasId, materialKey, colorHex, finishCode = '', roughnessCode = null, processCode = null) {
    if (!CONFIG.MATERIAL_REALISTIC[materialKey]) {
        console.warn(`[BabylonViewer] Unknown configurator material: ${materialKey}, falling back to aluminum`);
        materialKey = 'aluminum';
    }

    // Colour-keyed POM presets keep their tuned albedo because the sidebar
    // swatch is only used to choose the preset and can be lighter than the
    // thumbnail material.
    const customAlbedo = resolveConfiguratorCustomAlbedo(materialKey, colorHex);

    // Determine roughness/metallic modifiers from finish type
    const finishModifiers = getFinishModifiers(finishCode, materialKey);
    // Ra roughness code overrides the finish-derived roughness with an absolute value
    const raRoughness = roughnessCode ? (CONFIG.CNC_ROUGHNESS_MAP[roughnessCode] ?? null) : null;
    const surfaceEffect = resolveSurfaceEffect(processCode, materialKey, finishCode, finishModifiers);
    const nextFinishModifiers = {
        ...finishModifiers,
        // Specific finishes own the visual roughness; Ra applies only when
        // there is no finish-specific target.
        absoluteRoughness: finishModifiers.absoluteRoughness ?? raRoughness,
    };
    const nextStateKey = getConfiguratorStateKey(
        materialKey,
        customAlbedo.key,
        finishCode,
        roughnessCode,
        processCode);

    if (realisticConfiguratorStateKeys[canvasId] === nextStateKey) {
        materialTypes[canvasId] = materialKey;
        if (currentRenderModes[canvasId] === 'realistic'
            && !isCachedRealisticMaterialAssigned(canvasId, materialKey)) {
            applyRealisticMaterial(canvasId, materialKey);
        }
        return;
    }

    if (customAlbedo.color) {
        customAlbedoColors[canvasId] = customAlbedo.color;
    } else {
        delete customAlbedoColors[canvasId];
    }

    materialTypes[canvasId] = materialKey;
    perCanvasProcessCodes[canvasId] = processCode;
    // Store finish modifiers + resolved roughness so setRenderMode can re-apply them
    perCanvasFinishModifiers[canvasId] = nextFinishModifiers;
    perCanvasSurfaceEffects[canvasId] = surfaceEffect;
    realisticConfiguratorStateKeys[canvasId] = nextStateKey;

    // Invalidate the cached material so getRealisticMaterial creates a fresh
    // instance directly from the final colour/finish state. Do not mutate the
    // currently visible material through a preset colour first; that produces a
    // frame-visible flash in realistic mode.
    const detachedMaterial = detachCachedRealisticMaterial(canvasId, materialKey);

    // Only apply immediately if we are already in realistic mode.
    if (currentRenderModes[canvasId] === 'realistic') {
        applyRealisticMaterial(canvasId, materialKey);
    }

    disposeDetachedMaterial(detachedMaterial);
}

/**
 * Returns roughness and metallic offsets for a given surface finish code.
 * These are added to the material preset's base values.
 */
function isSteelLikeMaterial(materialKey) {
    return materialKey === 'steel' || materialKey === 'stainless-steel';
}

function isRawMachinedFinish(lowerFinishCode) {
    return !lowerFinishCode
        || lowerFinishCode.includes('raw')
        || lowerFinishCode.includes('unfinished')
        || lowerFinishCode.includes('as_machined')
        || lowerFinishCode.includes('as-machined')
        || lowerFinishCode.includes('machined')
        || lowerFinishCode.includes('machine')
        || lowerFinishCode.includes('standard')
        || lowerFinishCode.includes('ra_');
}

function getFinishModifiers(finishCode, materialKey = '') {
    const lower = (finishCode || '').toLowerCase();
    if (lower.includes('mirror') || lower.includes('electropolish') || lower.includes('polish')) {
        return { roughnessOffset: -0.22, metallicOffset: 0.03, surfaceEffectKey: null, absoluteRoughness: 0.045 };
    }
    if (lower.includes('brush')) {
        return { roughnessOffset: 0.14, metallicOffset: -0.03, surfaceEffectKey: 'brushed', absoluteRoughness: 0.44 };
    }
    if (lower.includes('anod'))   return { roughnessOffset: -0.10, metallicOffset: 0.05, surfaceEffectKey: null };  // shinier, more metallic
    if (lower.includes('bead'))   return { roughnessOffset: 0.24, metallicOffset: -0.03, surfaceEffectKey: 'bead-blast', absoluteRoughness: 0.58 };  // satin micro-etched aluminum
    if (lower.includes('blast'))  return { roughnessOffset: 0.21, metallicOffset: -0.02, surfaceEffectKey: 'bead-blast', absoluteRoughness: 0.56 };  // satin micro-etched aluminum
    if (lower.includes('paint'))  return { roughnessOffset: 0.0, metallicOffset: -0.10, surfaceEffectKey: null };    // less metallic
    if (lower.includes('plate'))  return { roughnessOffset: -0.05, metallicOffset: 0.0, surfaceEffectKey: null };   // slightly smoother
    if (isSteelLikeMaterial(materialKey) && isRawMachinedFinish(lower)) {
        return { roughnessOffset: 0.0, metallicOffset: 0.0, surfaceEffectKey: null, absoluteRoughness: 0.26 };
    }
    return { roughnessOffset: 0.0, metallicOffset: 0.0, surfaceEffectKey: null };
}

function resolveFinishRoughness(preset, finishModifiers, raRoughness) {
    if (finishModifiers.absoluteRoughness != null) {
        return clamp(finishModifiers.absoluteRoughness, 0, 1);
    }

    return raRoughness !== null
        ? raRoughness
        : clamp(preset.roughness + finishModifiers.roughnessOffset, 0, 1);
}

/** Clamps a value between min and max. */
function clamp(value, min, max) {
    return Math.min(max, Math.max(min, value));
}

function getSmoothNormalPositionTolerance(positions) {
    const minTolerance = CONFIG.REALISTIC.normalPositionToleranceMin
        || CONFIG.REALISTIC.normalPositionTolerance
        || 0.001;
    const ratio = CONFIG.REALISTIC.normalPositionToleranceRatio || 0;
    if (!positions || positions.length < 6 || ratio <= 0) return minTolerance;

    let minX = Infinity, minY = Infinity, minZ = Infinity;
    let maxX = -Infinity, maxY = -Infinity, maxZ = -Infinity;
    for (let i = 0; i < positions.length; i += 3) {
        const x = positions[i], y = positions[i + 1], z = positions[i + 2];
        minX = Math.min(minX, x); minY = Math.min(minY, y); minZ = Math.min(minZ, z);
        maxX = Math.max(maxX, x); maxY = Math.max(maxY, y); maxZ = Math.max(maxZ, z);
    }

    const dx = maxX - minX, dy = maxY - minY, dz = maxZ - minZ;
    const diagonal = Math.sqrt(dx * dx + dy * dy + dz * dz);
    return Math.max(minTolerance, diagonal * ratio);
}

function getSmoothNormalPositionKey(positions, offset, tolerance = CONFIG.REALISTIC.normalPositionTolerance || 0.001) {
    const qx = Math.round(positions[offset] / tolerance);
    const qy = Math.round(positions[offset + 1] / tolerance);
    const qz = Math.round(positions[offset + 2] / tolerance);
    return `${qx}|${qy}|${qz}`;
}

function normalizeNormalVector(normals, offset, fallback) {
    let nx = normals?.[offset] ?? fallback?.x ?? 0;
    let ny = normals?.[offset + 1] ?? fallback?.y ?? 0;
    let nz = normals?.[offset + 2] ?? fallback?.z ?? 1;
    const len = Math.sqrt(nx * nx + ny * ny + nz * nz);
    if (len > 1e-10) {
        nx /= len;
        ny /= len;
        nz /= len;
    } else {
        nx = fallback?.x ?? 0;
        ny = fallback?.y ?? 0;
        nz = fallback?.z ?? 1;
    }
    return { x: nx, y: ny, z: nz };
}

// ── Smooth normals for realistic edge softening ───────────────────────────────

/**
 * Recomputes per-vertex normals with angle-based smoothing to visually soften
 * faceted CAD edges — approximating a 0.2 mm fillet without tessellating geometry.
 * Original hard normals are saved so they can be restored on mode switch.
 * @param {string} canvasId
 */
function applySmoothNormals(canvasId) {
    const scene = scenes[canvasId];
    if (!scene) return;

    const thresholdRad = (CONFIG.REALISTIC.smoothAngleDeg * Math.PI) / 180;
    const cosThreshold = Math.cos(thresholdRad);

    if (!originalNormalData[canvasId]) originalNormalData[canvasId] = new Map();
    const saved = originalNormalData[canvasId];

    scene.meshes.forEach(mesh => {
        if (isSystemMesh(mesh)) return;
        if (saved.has(mesh.uniqueId)) return;  // already smoothed

        const positions = mesh.getVerticesData(BABYLON.VertexBuffer.PositionKind);
        const indices   = mesh.getIndices();
        const origNorms = mesh.getVerticesData(BABYLON.VertexBuffer.NormalKind);
        if (!positions || !indices || !origNorms) return;

        // Save original (hard) normals for restoration
        saved.set(mesh.uniqueId, new Float32Array(origNorms));

        const vertCount = positions.length / 3;
        const faceNormals = [];
        const positionFaceMap = new Map();
        const smoothNormals = new Float32Array(vertCount * 3);
        const positionTolerance = getSmoothNormalPositionTolerance(positions);

        // Pass 1 — compute face normals
        for (let i = 0; i < indices.length; i += 3) {
            const v0 = indices[i], v1 = indices[i + 1], v2 = indices[i + 2];
            const i0 = v0 * 3, i1 = v1 * 3, i2 = v2 * 3;
            const ax = positions[i1] - positions[i0], ay = positions[i1 + 1] - positions[i0 + 1], az = positions[i1 + 2] - positions[i0 + 2];
            const bx = positions[i2] - positions[i0], by = positions[i2 + 1] - positions[i0 + 1], bz = positions[i2 + 2] - positions[i0 + 2];
            const nx = ay * bz - az * by, ny = az * bx - ax * bz, nz = ax * by - ay * bx;
            const len = Math.sqrt(nx * nx + ny * ny + nz * nz);
            const area = len * 0.5;
            const fn = len > 1e-10 ? { x: nx / len, y: ny / len, z: nz / len, weight: area } : { x: 0, y: 0, z: 1, weight: 1 };
            faceNormals.push(fn);

            [v0, v1, v2].forEach(v => {
                if (v >= vertCount) return;
                const key = getSmoothNormalPositionKey(positions, v * 3, positionTolerance);
                const faces = positionFaceMap.get(key) || [];
                faces.push(fn);
                positionFaceMap.set(key, faces);
            });
        }

        // Pass 2 — average normals by position, discarding faces beyond angle threshold.
        // CAD/STL imports commonly duplicate vertices per triangle, so index-only
        // adjacency leaves round surfaces faceted and causes jagged PBR reflections.
        for (let v = 0; v < vertCount; v++) {
            const key = getSmoothNormalPositionKey(positions, v * 3, positionTolerance);
            const faces = positionFaceMap.get(key) || [];
            if (faces.length === 0) { smoothNormals[v * 3 + 2] = 1; continue; }

            let sx = 0, sy = 0, sz = 0;
            const refNormal = normalizeNormalVector(origNorms, v * 3, faces[0]);
            for (let j = 0; j < faces.length; j++) {
                const f = faces[j];
                const dot = refNormal.x * f.x + refNormal.y * f.y + refNormal.z * f.z;
                if (dot >= cosThreshold) {
                    const weight = f.weight || 1;
                    sx += f.x * weight;
                    sy += f.y * weight;
                    sz += f.z * weight;
                }
            }
            const slen = Math.sqrt(sx * sx + sy * sy + sz * sz);
            if (slen > 1e-10) { sx /= slen; sy /= slen; sz /= slen; }
            smoothNormals[v * 3]     = slen > 1e-10 ? sx : refNormal.x;
            smoothNormals[v * 3 + 1] = slen > 1e-10 ? sy : refNormal.y;
            smoothNormals[v * 3 + 2] = slen > 1e-10 ? sz : refNormal.z;
        }

        mesh.setVerticesData(BABYLON.VertexBuffer.NormalKind, smoothNormals);
    });
}

/**
 * Restores the original per-vertex normals saved before smoothing.
 * @param {string} canvasId
 */
function restoreOriginalNormals(canvasId) {
    const scene = scenes[canvasId];
    const saved = originalNormalData[canvasId];
    if (!scene || !saved) return;

    scene.meshes.forEach(mesh => {
        const orig = saved.get(mesh.uniqueId);
        if (!orig) return;
        mesh.setVerticesData(BABYLON.VertexBuffer.NormalKind, orig);
    });

    delete originalNormalData[canvasId];
}

// ── CAD material ──────────────────────────────────────────────────────────────

/**
 * Returns (or lazily creates) the shared CAD-gray PBR material for a scene.
 * All solid-mode meshes use this so parts always render with a uniform aluminum-gray
 * regardless of the original material embedded in the GLB.
 */
function getCadMaterial(scene) {
    const name = '__cad_gray__';
    const existing = scene.getMaterialByName(name);
    if (existing) return existing;
    const pbr = new BABYLON.PBRMaterial(name, scene);
    // Satin-aluminum — neutral gray with subtle metallic sheen, matching typical CAD software defaults
    pbr.albedoColor = toColor3(CONFIG.MATERIAL_CAD_SOLID.albedoColor);
    pbr.metallic    = CONFIG.MATERIAL_CAD_SOLID.metallic;
    pbr.roughness   = CONFIG.MATERIAL_CAD_SOLID.roughness;
    return pbr;
}

/**
 * Returns a shared x-ray/transparent material for the scene.
 * Creates it once and reuses for all transparent rendering (toolbar + body selection).
 * @param {BABYLON.Scene} scene
 * @returns {BABYLON.StandardMaterial}
 */
function getOrCreateXrayMaterial(scene) {
    const name = '__xray_shared__';
    const existing = scene.getMaterialByName(name);
    if (existing) return existing;

    const tm = new BABYLON.StandardMaterial(name, scene);
    // CAD-gray semi-transparent (X-Ray view) - same appearance for toolbar and body selection
    tm.diffuseColor     = toColor3(CONFIG.MATERIAL_XRAY.diffuseColor);
    tm.emissiveColor    = toColor3(CONFIG.MATERIAL_XRAY.emissiveColor);
    tm.alpha            = CONFIG.MATERIAL_XRAY.alpha;
    tm.backFaceCulling  = false;
    tm.twoSidedLighting = true;
    return tm;
}

/**
 * Returns a shared x-ray material for body selection (MORE transparent than toolbar).
 * Used only when highlighting one body in a multi-body assembly.
 * @param {BABYLON.Scene} scene
 * @returns {BABYLON.StandardMaterial}
 */
function getOrCreateBodySelectionXrayMaterial(scene) {
    const name = '__body_xray_shared__';
    const existing = scene.getMaterialByName(name);
    if (existing) return existing;

    const tm = new BABYLON.StandardMaterial(name, scene);
    // Much more transparent than toolbar x-ray (alpha=0.15 vs 0.38)
    // This makes the selected body stand out clearly
    tm.diffuseColor     = toColor3(CONFIG.MATERIAL_BODY_SELECTION_XRAY.diffuseColor);
    tm.emissiveColor    = toColor3(CONFIG.MATERIAL_BODY_SELECTION_XRAY.emissiveColor);
    tm.alpha            = CONFIG.MATERIAL_BODY_SELECTION_XRAY.alpha;
    tm.backFaceCulling  = false;
    tm.twoSidedLighting = true;
    return tm;
}

/**
 * Returns a dedicated xray material for the section-view ghost (hidden half).
 * Separate from the toolbar xray so alpha and clip plane can differ independently.
 * @param {BABYLON.Scene} scene
 * @returns {BABYLON.StandardMaterial}
 */
function _getOrCreateSectionGhostMaterial(scene) {
    const name = '__section_ghost__';
    const existing = scene.getMaterialByName(name);
    if (existing) return existing;

    const mat = new BABYLON.StandardMaterial(name, scene);
    mat.diffuseColor     = new BABYLON.Color3(0.55, 0.62, 0.72);
    mat.emissiveColor    = new BABYLON.Color3(0.05, 0.07, 0.12);
    mat.alpha            = 0.08;
    mat.backFaceCulling  = false;
    mat.twoSidedLighting = true;
    return mat;
}

/**
 * Creates ghost (xray) clones of every visible body mesh with the clip plane inverted,
 * so the hidden half appears as a faint see-through silhouette.
 * @param {string}  canvasId
 * @param {BABYLON.Scene} scene
 * @param {number}  nx  plane normal x
 * @param {number}  ny  plane normal y
 * @param {number}  nz  plane normal z
 * @param {number}  d   plane constant
 */
function _createSectionGhosts(canvasId, scene, nx, ny, nz, d) {
    _disposeSectionGhosts(canvasId);

    const ghostMat = _getOrCreateSectionGhostMaterial(scene);
    // Each ghost material instance needs its own clipPlane, so clone per call
    // (but we reuse the same ghost mat with a per-mesh override via material.clipPlane)
    const invertedPlane = new BABYLON.Plane(-nx, -ny, -nz, -d);

    const ghosts = [];
    for (const mesh of scene.meshes) {
        if (!mesh.isVisible || !isModelMeshForAnalysis(mesh, canvasId)) continue;
        if (typeof mesh.clone !== 'function') continue;

        const clone = mesh.clone(`__section_ghost_${mesh.uniqueId}`, null, false);
        if (!clone) continue;

        // Create a per-clone material so clipPlane is independent of the shared mat
        const cloneMat = ghostMat.clone(`__section_ghost_mat_${mesh.uniqueId}`);
        cloneMat.clipPlane = invertedPlane;
        clone.material = cloneMat;
        clone.receiveShadows = false;
        markAnalysisHelperMesh(clone);
        ghosts.push(clone);
    }
    sectionGhostMeshes[canvasId] = ghosts;
}

/**
 * Disposes all section ghost meshes (and their per-clone materials) for a canvas.
 * @param {string} canvasId
 */
function _disposeSectionGhosts(canvasId) {
    const ghosts = sectionGhostMeshes[canvasId];
    if (!ghosts) return;
    for (const g of ghosts) {
        if (g.material) g.material.dispose();
        g.dispose();
    }
    sectionGhostMeshes[canvasId] = null;
}

function isAnalysisHelperMesh(mesh) {
    const name = mesh?.name ?? '';
    return !!mesh?.metadata?.malievAnalysisHelper
        || name === '__grid__'
        || name === '__shadow_catcher__'
        || name === '__root__'
        || name.startsWith('__axis')
        || name.startsWith('bbox_')
        || name.startsWith('__cutting_mat')
        || name.startsWith('__section_ghost')
        || name.startsWith('__section_edges_')
        || name.startsWith('__section_hatch_')
        || name.startsWith('__flipped_overlay__')
        || name.startsWith('measure_')
        || name.startsWith('thickness_');
}

function markAnalysisHelperMesh(mesh) {
    if (!mesh) return mesh;
    mesh.metadata = { ...(mesh.metadata ?? {}), malievAnalysisHelper: true, malievModelMesh: false };
    mesh.isPickable = false;
    return mesh;
}

function isOverlayMeshForCanvas(canvasId, mesh) {
    if (!mesh) return false;
    const direct = overlayMeshes[canvasId];
    if (direct instanceof Map) {
        for (const [, meshes] of direct) {
            if (meshes?.some(m => m === mesh || m?.uniqueId === mesh.uniqueId)) return true;
        }
    }

    const prefix = `${canvasId}::`;
    for (const [key, value] of Object.entries(overlayMeshes)) {
        if (!key.startsWith(prefix) || !(value instanceof Map)) continue;
        for (const [, meshes] of value) {
            if (meshes?.some(m => m === mesh || m?.uniqueId === mesh.uniqueId)) return true;
        }
    }

    return false;
}

function isModelMeshCandidate(mesh, canvasId) {
    return !!mesh
        && !isAnalysisHelperMesh(mesh)
        && !isOverlayMeshForCanvas(canvasId, mesh)
        && typeof mesh.getTotalVertices === 'function'
        && mesh.getTotalVertices() > 0
        && (typeof mesh.isEnabled !== 'function' || mesh.isEnabled());
}

function tagModelMeshesForAnalysis(canvasId, scene = scenes[canvasId]) {
    if (!scene) return;

    const ids = new Set();
    scene.meshes.forEach(mesh => {
        if (isModelMeshCandidate(mesh, canvasId)) {
            mesh.metadata = { ...(mesh.metadata ?? {}), malievModelMesh: true, malievAnalysisHelper: false };
            mesh.isPickable = true;
            ids.add(mesh.uniqueId);
        } else if (isAnalysisHelperMesh(mesh) || isOverlayMeshForCanvas(canvasId, mesh)) {
            if (mesh.metadata?.malievModelMesh) {
                mesh.metadata = { ...mesh.metadata, malievModelMesh: false };
            }
            if (isAnalysisHelperMesh(mesh)) mesh.isPickable = false;
        }
    });
    analysisModelMeshIds[canvasId] = ids;
}

function ensureModelMeshesTagged(canvasId, scene = scenes[canvasId]) {
    if (!analysisModelMeshIds[canvasId] || analysisModelMeshIds[canvasId].size === 0) {
        tagModelMeshesForAnalysis(canvasId, scene);
    }
}

function isModelMeshForAnalysis(mesh, canvasId = null) {
    if (!mesh || isAnalysisHelperMesh(mesh)) return false;
    if (canvasId && analysisModelMeshIds[canvasId]?.has(mesh.uniqueId)) return true;
    return mesh.metadata?.malievModelMesh === true;
}

/**
 * Checks if a mesh is a system mesh (grid, axis gizmo, bounding box, analysis helpers) that should be skipped.
 * @param {BABYLON.AbstractMesh} mesh
 * @returns {boolean}
 */
function isSystemMesh(mesh) {
    return isAnalysisHelperMesh(mesh);
}

function toPlainNumberArray(values) {
    return Array.from(values ?? [], value => Number(value)).filter(Number.isFinite);
}

function getMeshWorldPositions(mesh, positions) {
    if (!mesh || !positions || positions.length === 0) return [];

    try {
        mesh.computeWorldMatrix?.(true);
        const matrix = mesh.getWorldMatrix?.();
        if (!matrix || !BABYLON?.Vector3?.TransformCoordinates) {
            return toPlainNumberArray(positions);
        }

        const transformed = [];
        for (let index = 0; index < positions.length; index += 3) {
            const point = BABYLON.Vector3.TransformCoordinates(
                new BABYLON.Vector3(
                    Number(positions[index]),
                    Number(positions[index + 1]),
                    Number(positions[index + 2])
                ),
                matrix
            );
            transformed.push(point.x, point.y, point.z);
        }
        return transformed;
    } catch (_) {
        return toPlainNumberArray(positions);
    }
}

/**
 * Collects mesh buffers for the browser advisory geometry runtime.
 * @param {string} canvasId
 * @returns {Array<{positions:number[], indices:number[]}>}
 */
export function collectAdvisoryMeshBuffers(canvasId) {
    const scene = scenes[canvasId];
    if (!scene) return [];

    ensureModelMeshesTagged(canvasId, scene);
    const buffers = [];
    for (const mesh of scene.meshes ?? []) {
        if (!mesh?.isVisible || !isModelMeshForAnalysis(mesh, canvasId)) continue;
        const positions = mesh.getVerticesData?.(BABYLON.VertexBuffer.PositionKind);
        if (!positions || positions.length < 9) continue;

        const indices = mesh.getIndices?.() ?? [];
        const safeIndices = indices.length > 0
            ? toPlainNumberArray(indices)
            : Array.from({ length: positions.length / 3 }, (_, index) => index);
        if (safeIndices.length < 3) continue;

        buffers.push({
            positions: getMeshWorldPositions(mesh, positions),
            indices: safeIndices,
        });
    }

    return buffers;
}

function resolveRuntimeAssetUrl(assetPath, assetBaseUrl = LOCAL_ADVISORY_ASSET_BASE_URL) {
    const value = String(assetPath ?? '');
    if (value.includes('..') || value.includes('\\')) return null;
    const name = value.split('?')[0].split('/').pop();
    if (!name || name.includes('..') || name.includes('/') || name.includes('\\')) return null;
    return `${assetBaseUrl}${encodeURIComponent(name)}`;
}

function getLocalAdvisoryPanel(canvasId) {
    const canvas = document.getElementById(canvasId);
    const host = canvas?.parentElement;
    if (!host) return null;

    const selector = `[data-local-geometry-advisory="${canvasId}"]`;
    let panel = host.querySelector?.(selector);
    if (!panel) {
        panel = document.createElement('div');
        panel.setAttribute('data-local-geometry-advisory', canvasId);
        panel.setAttribute('role', 'status');
        Object.assign(panel.style, {
            position: 'absolute',
            right: '12px',
            bottom: '78px',
            maxWidth: '260px',
            padding: '9px 11px',
            borderRadius: '6px',
            background: 'rgba(17, 24, 39, 0.86)',
            color: '#ffffff',
            boxShadow: '0 8px 24px rgba(0,0,0,0.22)',
            font: '500 12px/1.35 system-ui, -apple-system, Segoe UI, sans-serif',
            pointerEvents: 'none',
            zIndex: '8',
        });
        host.appendChild(panel);
    }

    return panel;
}

function clearLocalAdvisoryPanel(canvasId) {
    const canvas = document.getElementById(canvasId);
    const host = canvas?.parentElement;
    const panel = host?.querySelector?.(`[data-local-geometry-advisory="${canvasId}"]`);
    panel?.remove?.();
}

function renderLocalAdvisoryStatus(canvasId, state, result = null) {
    const panel = getLocalAdvisoryPanel(canvasId);
    if (!panel) return;

    if (state === 'pending') {
        panel.textContent = 'Local preliminary DFM running...';
        return;
    }

    const issues = Array.isArray(result?.issues) ? result.issues : [];
    const warnings = issues.filter(issue => issue?.severity !== 'info').length;
    const faceCount = Number(result?.metrics?.faceCount ?? 0);
    const issueLabel = warnings === 0
        ? 'no warnings'
        : `${warnings} warning${warnings === 1 ? '' : 's'}`;
    panel.textContent = `Local preliminary DFM: ${issueLabel} · advisory only · ${faceCount.toLocaleString()} tris`;
}

function terminateLocalAdvisoryWorker(canvasId) {
    try { localAdvisoryWorkers[canvasId]?.terminate?.(); } catch (_) {}
    delete localAdvisoryWorkers[canvasId];
}

function analyzeWithLocalAdvisoryWorker(canvasId, workerUrl, input, processCode, timeoutMs) {
    terminateLocalAdvisoryWorker(canvasId);

    return new Promise((resolve, reject) => {
        const worker = new Worker(workerUrl, { name: 'maliev-geometry-advisory' });
        localAdvisoryWorkers[canvasId] = worker;
        const messageId = `${canvasId}:${Date.now()}:${Math.random().toString(36).slice(2)}`;
        const timeout = setTimeout(() => {
            terminateLocalAdvisoryWorker(canvasId);
            reject(new Error('Local advisory geometry runtime timed out.'));
        }, timeoutMs);

        worker.onmessage = event => {
            const message = event.data ?? {};
            if (message.id !== messageId) return;
            clearTimeout(timeout);
            terminateLocalAdvisoryWorker(canvasId);
            message.ok ? resolve(message.result) : reject(new Error(message.error || 'Local advisory geometry runtime failed.'));
        };
        worker.onerror = event => {
            clearTimeout(timeout);
            terminateLocalAdvisoryWorker(canvasId);
            reject(new Error(event?.message || 'Local advisory geometry worker failed.'));
        };
        worker.postMessage({ id: messageId, input, processCode });
    });
}

/**
 * Runs the GeometryService-owned advisory browser runtime through the same-origin BFF proxy.
 * Falls back silently to the server-only path when the manifest or worker cannot be used.
 * @param {string} canvasId
 * @param {{processCode?: string, manifestUrl?: string, assetBaseUrl?: string, timeoutMs?: number}} options
 * @returns {Promise<object|null>}
 */
export async function runLocalAdvisoryGeometry(canvasId, options = {}) {
    if (typeof fetch !== 'function' || typeof Worker === 'undefined') return null;

    const runId = (localAdvisoryRuns[canvasId] ?? 0) + 1;
    localAdvisoryRuns[canvasId] = runId;

    const meshBuffers = collectAdvisoryMeshBuffers(canvasId);
    if (meshBuffers.length === 0) return null;

    renderLocalAdvisoryStatus(canvasId, 'pending');
    try {
        const manifestResponse = await fetch(options.manifestUrl ?? LOCAL_ADVISORY_MANIFEST_URL, {
            cache: 'no-cache',
            credentials: 'same-origin',
        });
        if (!manifestResponse.ok || localAdvisoryRuns[canvasId] !== runId) {
            clearLocalAdvisoryPanel(canvasId);
            return null;
        }

        const manifest = await manifestResponse.json();
        if (Number(manifest.minFrontendApiVersion ?? 1) > LOCAL_ADVISORY_FRONTEND_API_VERSION ||
            manifest.isAuthoritative !== false ||
            manifest.authority !== 'advisory') {
            clearLocalAdvisoryPanel(canvasId);
            return null;
        }

        const workerUrl = resolveRuntimeAssetUrl(
            manifest.assets?.worker,
            options.assetBaseUrl ?? LOCAL_ADVISORY_ASSET_BASE_URL);
        if (!workerUrl) {
            clearLocalAdvisoryPanel(canvasId);
            return null;
        }

        const result = await analyzeWithLocalAdvisoryWorker(
            canvasId,
            workerUrl,
            { meshBuffers },
            options.processCode ?? 'FDM',
            Number(options.timeoutMs) > 0 ? Number(options.timeoutMs) : 15000);
        if (localAdvisoryRuns[canvasId] !== runId ||
            result?.isAuthoritative !== false ||
            result?.authority !== 'advisory') {
            clearLocalAdvisoryPanel(canvasId);
            return null;
        }

        renderLocalAdvisoryStatus(canvasId, 'complete', result);
        return result;
    } catch (_) {
        if (localAdvisoryRuns[canvasId] === runId) {
            clearLocalAdvisoryPanel(canvasId);
        }
        return null;
    }
}

function getPointerRenderCoordinates(canvasId, pointerEvent) {
    const engine = engines[canvasId];
    const canvas = engine?.getRenderingCanvas?.() ?? document.getElementById(canvasId);
    const event = pointerEvent?.touches?.[0]
        ?? pointerEvent?.changedTouches?.[0]
        ?? pointerEvent;

    if (!canvas || !event || !Number.isFinite(event.clientX) || !Number.isFinite(event.clientY)) return null;
    const rect = canvas.getBoundingClientRect();
    if (!rect || rect.width <= 0 || rect.height <= 0) return null;

    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    if (x < 0 || y < 0 || x > rect.width || y > rect.height) return null;

    const renderWidth = Number(engine?.getRenderWidth?.());
    const renderHeight = Number(engine?.getRenderHeight?.());
    const scaleX = Number.isFinite(renderWidth) && renderWidth > 0
        ? renderWidth / rect.width
        : 1;
    const scaleY = Number.isFinite(renderHeight) && renderHeight > 0
        ? renderHeight / rect.height
        : 1;

    return {
        x: x * scaleX,
        y: y * scaleY,
    };
}

function getPointerInfoRenderCoordinates(canvasId, scene, pointerInfo) {
    if (pointerInfo?.event) return getPointerRenderCoordinates(canvasId, pointerInfo.event);

    return Number.isFinite(scene?.pointerX) && Number.isFinite(scene?.pointerY)
        ? { x: scene.pointerX, y: scene.pointerY }
        : null;
}

function projectWorldToRenderCoordinates(canvasId, scene, worldPos) {
    const engine = engines[canvasId];
    const cam = mainCameras[canvasId] ?? scene?.activeCamera;
    if (!engine || !cam || !worldPos) return null;
    if (typeof BABYLON.Vector3?.Project !== 'function' || typeof BABYLON.Matrix?.Identity !== 'function') return null;
    if (typeof cam.getViewMatrix !== 'function' || typeof cam.getProjectionMatrix !== 'function' || !cam.viewport) return null;

    const renderWidth = Number(engine.getRenderWidth?.());
    const renderHeight = Number(engine.getRenderHeight?.());
    if (!Number.isFinite(renderWidth) || !Number.isFinite(renderHeight) || renderWidth <= 0 || renderHeight <= 0) return null;

    try {
        const viewProjection = cam.getViewMatrix().multiply(cam.getProjectionMatrix());
        return BABYLON.Vector3.Project(
            worldPos,
            BABYLON.Matrix.Identity(),
            viewProjection,
            cam.viewport.toGlobal(renderWidth, renderHeight));
    } catch (_) {
        return null;
    }
}

function isPickProjectedNearPointer(canvasId, scene, pickResult, x, y) {
    if (!canvasId || !pickResult?.hit || !pickResult.pickedPoint) return true;

    const projected = projectWorldToRenderCoordinates(canvasId, scene, pickResult.pickedPoint);
    if (!projected || projected.z < 0 || projected.z > 1) return true;

    const engine = engines[canvasId];
    const canvas = engine?.getRenderingCanvas?.();
    const rect = canvas?.getBoundingClientRect?.();
    const renderWidth = Number(engine?.getRenderWidth?.());
    const renderHeight = Number(engine?.getRenderHeight?.());
    const scaleX = rect?.width > 0 && Number.isFinite(renderWidth) ? renderWidth / rect.width : 1;
    const scaleY = rect?.height > 0 && Number.isFinite(renderHeight) ? renderHeight / rect.height : 1;
    const tolerance = CONFIG.MEASURE.maxPickScreenDistancePx * Math.max(scaleX, scaleY, 1);

    return Math.hypot(projected.x - x, projected.y - y) <= tolerance;
}

function setAnalysisNavigationLock(canvasId, locked) {
    const pointers = mainCameras[canvasId]?.inputs?.attached?.pointers;
    if (!pointers) return;

    if (locked) {
        if (!analysisCameraButtons[canvasId]) {
            analysisCameraButtons[canvasId] = Array.isArray(pointers.buttons)
                ? [...pointers.buttons]
                : [0];
        }
        return;
    }

    if (measureStates[canvasId]?.active || thicknessStates[canvasId]?.active) return;
    const previous = analysisCameraButtons[canvasId] ?? [0];
    pointers.buttons = [...previous];
    delete analysisCameraButtons[canvasId];
}

/**
 * Safely disables edge rendering on a mesh (ignores errors for meshes without edges).
 * @param {BABYLON.AbstractMesh} mesh
 */
function safeDisableEdges(mesh) {
    try { mesh.disableEdgesRendering(); } catch (_) {}
}

/**
 * Checks if dark mode is enabled for a canvas.
 * @param {string} canvasId
 * @returns {boolean}
 */
function isDarkMode(canvasId) {
    return darkModes[canvasId] ?? false;
}

/**
 * Animates a material's alpha property for smooth fade transitions.
 * @param {BABYLON.Material} material - Material to animate
 * @param {number} fromAlpha - Starting alpha value (0-1)
 * @param {number} toAlpha - Ending alpha value (0-1)
 * @param {BABYLON.Scene} scene - Scene for animation
 * @param {number} duration - Animation duration in milliseconds (default: 200ms)
 * @returns {Promise} - Resolves when animation completes
 */
function animateMaterialAlpha(material, fromAlpha, toAlpha, scene, duration = CONFIG.ANIMATION_ALPHA_FADE_DURATION) {
    return new Promise(resolve => {
        const anim = new BABYLON.Animation(
            'alphaFade',
            'alpha',
            CONFIG.ANIMATION_FRAME_RATE,  // frames per second
            BABYLON.Animation.ANIMATIONTYPE_FLOAT,
            BABYLON.Animation.ANIMATIONLOOPMODE_CONSTANT
        );

        const keys = [
            { frame: 0, value: fromAlpha },
            { frame: (duration / 1000) * 60, value: toAlpha }
        ];
        anim.setKeys(keys);

        // Create animation group and run
        const animGroup = new BABYLON.AnimationGroup('alphaFadeGroup');
        animGroup.addTargetedAnimation(anim, material);
        animGroup.onAnimationEnd = () => {
            animGroup.dispose();
            resolve();
        };
        animGroup.play();
    });
}

// ── applyStudioLighting ───────────────────────────────────────────────────────

/**
 * Re-applies studio lighting for the given dark/light mode without re-loading the model.
 * Called when the user toggles the app theme after a model is already loaded.
 * @param {string} canvasId
 * @param {boolean} isDark
 */
export function applyStudioLighting(canvasId, isDark) {
    const scene = scenes[canvasId];
    if (!scene || modelLoadState[canvasId] !== 'loaded') return;

    darkModes[canvasId] = !!isDark;

    // Dispose old shadow generator before disposing lights (prevents orphaned references)
    const oldShadowGen = shadowGenerators[canvasId];
    if (oldShadowGen) {
        try { oldShadowGen.dispose(); } catch (_) {}
        delete shadowGenerators[canvasId];
    }

    // Dispose all existing scene lights
    scene.lights.slice().forEach(l => { try { l.dispose(); } catch (_) {} });

    const _lc = isDark ? CONFIG.STUDIO_DARK : CONFIG.STUDIO_LIGHT;

    // Ambient hemisphere
    const _amb = _lc.ambient;
    const hemi = new BABYLON.HemisphericLight('hemi', toVector3(_amb.direction), scene);
    hemi.intensity   = _amb.intensity;
    hemi.diffuse     = toColor3(_amb.diffuse);
    hemi.groundColor = toColor3(_amb.groundColor);
    hemi.specular    = toColor3(_amb.specular);

    // Key light with shadows
    const key = new BABYLON.DirectionalLight('key', toVector3(_lc.key.direction), scene);
    key.intensity = _lc.key.intensity;
    key.diffuse   = toColor3(_lc.key.diffuse);
    key.specular  = toColor3(_lc.key.diffuse);

    const shadowGen = new BABYLON.ShadowGenerator(_lc.key.shadowMapSize, key);
    shadowGen.usePercentageCloserFiltering = true;
    shadowGen.filteringQuality = BABYLON.ShadowGenerator.QUALITY_HIGH;
    shadowGen.setDarkness(_lc.key.shadowDarkness);
    shadowGen.transparencyShadow = true;
    shadowGenerators[canvasId] = shadowGen;

    // Fill / rim / back lights
    if (_lc.fill) {
        const fill = new BABYLON.DirectionalLight('fill', toVector3(_lc.fill.direction), scene);
        fill.intensity = _lc.fill.intensity;
        fill.diffuse   = toColor3(_lc.fill.diffuse);
        fill.specular  = new BABYLON.Color3(0.05, 0.05, 0.06);
    }
    if (_lc.rim) {
        const rim = new BABYLON.DirectionalLight('rim', toVector3(_lc.rim.direction), scene);
        rim.intensity = _lc.rim.intensity;
        rim.diffuse   = toColor3(_lc.rim.diffuse);
        rim.specular  = toColor3(_lc.rim.diffuse);
    }
    if (_lc.back) {
        const back2 = new BABYLON.DirectionalLight('back', toVector3(_lc.back.direction), scene);
        back2.intensity = _lc.back.intensity;
        back2.diffuse   = toColor3(_lc.back.diffuse);
        back2.specular  = new BABYLON.Color3(0.02, 0.02, 0.04);
    }

    // Re-position key light relative to model bounds (same logic as initialize)
    const bb = sceneBoundingBoxes[canvasId];
    const mc = meshCenters[canvasId];
    if (bb && mc) {
        const dist = Math.max(bb.max.x - bb.min.x, bb.max.y - bb.min.y, bb.max.z - bb.min.z);
        key.position = new BABYLON.Vector3(mc.x - dist, mc.y - dist, bb.max.z + dist);
    }

    // Re-register model meshes as shadow casters without projecting shadows onto CAD surfaces or the mat.
    scene.meshes.forEach(m => {
        if (m.name?.startsWith('__cutting_mat')) {
            m.receiveShadows = false;
            return;
        }
        if (m.name !== '__grid__' && m.name !== '__shadow_catcher__' && !m.name.startsWith('__axis')) {
            shadowGen.addShadowCaster(m);
            m.receiveShadows = false;
        }
    });
}

// ── setRenderMode ─────────────────────────────────────────────────────────────

export function setRenderMode(canvasId, mode) {
    const scene = scenes[canvasId];
    if (!scene) return;
    const origMats = originalMaterials[canvasId] ?? {};
    const prevMode = currentRenderModes[canvasId] || 'solid';

    // Ensure the IBL environment texture exists before assigning PBR materials.
    // Solid CAD mode also uses PBR material, so it needs the same environment
    // lighting that realistic mode creates; otherwise the first upload render is too dark.
    if (mode === 'realistic' || mode === 'solid') getOrCreateEnvironmentTexture(scene, canvasId);

    scene.meshes.forEach(mesh => {
        // Skip system meshes: ground grid, axis gizmo parts, bounding box lines
        if (isSystemMesh(mesh)) return;

        if (mode === 'wireframe') {
            if (!origMats[mesh.uniqueId] && mesh.material) origMats[mesh.uniqueId] = mesh.material;

            // Create per-mesh wireframe material for true triangle wireframe
            const wm = new BABYLON.StandardMaterial('wire_' + mesh.uniqueId, scene);
            const wireColor = isDarkMode(canvasId)
                ? CONFIG.WIREFRAME.colorDark
                : CONFIG.WIREFRAME.colorLight;

            wm.wireframe = true;
            // Use emissive for line color, set alpha for transparency to reduce visual density
            wm.emissiveColor = new BABYLON.Color3(wireColor.r, wireColor.g, wireColor.b);
            wm.alpha = CONFIG.WIREFRAME.faceAlpha;  // Semi-transparent lines reduce density on high-poly meshes
            wm.diffuseColor = BABYLON.Color3.Black();
            wm.specularColor = BABYLON.Color3.Black();
            wm.disableLighting = true;
            wm.backFaceCulling = false;

            mesh.material = wm;
            safeDisableEdges(mesh);

        } else if (mode === 'transparent') {
            // CAD-gray semi-transparent (X-Ray view) - uses shared material
            const tm = getOrCreateXrayMaterial(scene);
            mesh.material = tm;
            safeDisableEdges(mesh);

        } else if (mode === 'realistic') {
            const matType = materialTypes[canvasId] || 'aluminum';
            const finishMod = perCanvasFinishModifiers[canvasId] || { roughnessOffset: 0, metallicOffset: 0 };
            // All bodies (single or multi) share the same configurator-colour realistic material.
            // Original per-body materials are never mutated — solid mode restores them intact.
            mesh.material = getRealisticMaterial(scene, canvasId, matType);
            const preset = CONFIG.MATERIAL_REALISTIC[matType] || CONFIG.MATERIAL_REALISTIC['aluminum'];
            syncRealisticMaterialProperties(
                mesh.material,
                preset,
                customAlbedoColors[canvasId],
                finishMod,
                resolveRealisticNodeMaterialProfile(canvasId, matType));
            safeDisableEdges(mesh);

        } else {
            // Solid — restore the immutable baseline captured at load time.
            // Prefer defaultSolidMaterials (never overwritten by mode switches),
            // then multi-body colors, then uniform CAD gray.
            const defMat = defaultSolidMaterials[canvasId]?.get(mesh.uniqueId);
            if (defMat) {
                mesh.material = defMat;
            } else {
                const bodyMap = perCanvasBodyMap[canvasId];
                const bodyEntry = bodyMap && Array.from(bodyMap.values()).find(bd => bd.meshes.includes(mesh));
                mesh.material = bodyEntry?.colorMaterial || getCadMaterial(scene);
            }
            safeDisableEdges(mesh);
        }
    });

    // Re-apply edges after solid/transparent mode change if they were enabled.
    // Wireframe uses StandardMaterial.wireframe and disables edge rendering.
    if (mode !== 'wireframe' && edgesEnabled[canvasId]) {
        toggleEdges(canvasId, true);
    }

    // Smooth normals transition — apply on enter, restore on leave
    if (mode === 'realistic' && prevMode !== 'realistic') {
        applySmoothNormals(canvasId);
    } else if (mode !== 'realistic' && prevMode === 'realistic') {
        restoreOriginalNormals(canvasId);
    }
    currentRenderModes[canvasId] = mode;
    _syncCuttingMatRenderMode(canvasId);
}

// ── setCameraPreset ───────────────────────────────────────────────────────────

export function setCameraPreset(canvasId, preset, smooth = true) {
    const cam = mainCameras[canvasId];
    const bb  = _activeCameraFitBounds(canvasId);
    if (!cam) return;

    // Kill auto-rotation instantly — zeroing current speed prevents the lerp
    // tail from drifting the camera after the preset position is applied.
    autoSpeedCurrent[canvasId] = 0;
    autoSpeedTarget[canvasId]  = SPEED_STOP;
    animStates[canvasId]       = 'interacting';

    if (smooth) {
        // Cancel any ongoing animation by setting a flag
        cam._presetAnimationCancelled = true;
        // Small delay to ensure previous animation frame is cancelled
        setTimeout(() => {
            cam._presetAnimationCancelled = false;
            applyPreset(cam, preset, smooth, canvasId);
        }, 16);
        return;
    }

    // For immediate transitions, reset to fitted view (original behavior)
    orthoZoomFactors[canvasId] = 1.0;
    if (bb) fitCameraToMesh(cam, bb, meshCenters[canvasId], canvasId);
    applyPreset(cam, preset, smooth, canvasId);
}

// ── stopAutoRotation ───────────────────────────────────────────────────────────

export function stopAutoRotation(canvasId) {
    animStates[canvasId]      = 'interacting';
    autoSpeedTarget[canvasId] = SPEED_STOP;
}

// ── resetCamera ───────────────────────────────────────────────────────────────

export function resetCamera(canvasId, smooth = true) {
    const cam = mainCameras[canvasId];
    const bb  = _activeCameraFitBounds(canvasId);
    if (!cam) return;

    // Kill auto-rotation instantly
    autoSpeedCurrent[canvasId] = 0;
    autoSpeedTarget[canvasId]  = SPEED_STOP;
    animStates[canvasId]       = 'interacting';

    // Reset orthographic zoom factor to prevent feedback loop
    orthoZoomFactors[canvasId] = 1.0;

    cam.upVector = new BABYLON.Vector3(0, 0, 1);
    if (bb) fitCameraToMesh(cam, bb, meshCenters[canvasId], canvasId);
    applyPreset(cam, 'iso', smooth, canvasId);

    const canvas = document.getElementById(canvasId);
    if (canvas && !cam.inputs.attached.keyboard) cam.attachControl(canvas, true);
}

// ── toggleEdges ───────────────────────────────────────────────────────────────

/**
 * Reads the --mud-palette-text-primary CSS variable and converts it to a BABYLON.Color4.
 * Falls back to mode-aware hardcoded colors if the variable is missing or unparseable.
 */
function getEdgeColorFromCss(isDark) {
    try {
        const raw = getComputedStyle(document.documentElement)
            .getPropertyValue('--mud-palette-text-primary').trim();
        if (raw) {
            // Use a temporary canvas context to normalize any CSS color format → hex
            const ctx = document.createElement('canvas').getContext('2d');
            ctx.fillStyle = raw;
            const hex = ctx.fillStyle; // browser normalizes to #rrggbb
            const m = hex.match(/^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i);
            if (m) return new BABYLON.Color4(
                parseInt(m[1], 16) / 255,
                parseInt(m[2], 16) / 255,
                parseInt(m[3], 16) / 255,
                0.9
            );
        }
    } catch (_) {}
    return isDark
        ? toColor4(CONFIG.EDGES.colorDark)
        : toColor4(CONFIG.EDGES.colorLight);
}

/**
 * Returns the edge width appropriate for the current camera projection.
 * In perspective mode, width scales with camera radius relative to the initial
 * fit-radius so that edges remain visually thin regardless of zoom level.
 * Orthographic renders all edges at equal screen thickness so a fixed narrow
 * value is used.
 */
function getEdgesWidth(canvasId) {
    const fitR = fitRadiusMap[canvasId];
    if (!fitR) return CONFIG.EDGES.defaultWidth;

    let width;
    if (cameraProjection[canvasId] === 'orthographic') {
        const zoomFactor = orthoZoomFactors[canvasId] || 1;
        // Orthographic: use much smaller base width (~1/12 of default) for cleaner look
        const orthoBase = CONFIG.EDGES.defaultWidth * 0.08;
        width = Math.max(CONFIG.EDGES.minWidth, Math.min(orthoBase, orthoBase * zoomFactor));
    } else {
        // Perspective mode: use moderate base width for clean lines without being too thick
        const cam = mainCameras[canvasId];
        const perspBase = CONFIG.EDGES.defaultWidth * 0.4;
        if (!cam) width = perspBase;
        else width = Math.max(CONFIG.EDGES.minWidth, Math.min(perspBase, perspBase * (cam.radius / fitR)));
    }
    return width;
}

/**
 * Returns the polygon offset factor for edge rendering.
 * In orthographic mode a minimal value suffices (depth is linear).
 * In perspective mode with logarithmic depth buffer, we need a much larger factor
 * to push edges above the surface.
 */
function getEdgesZOffset(canvasId) {
    const fitR = fitRadiusMap[canvasId];
    if (!fitR) return 1;

    if (cameraProjection[canvasId] === 'orthographic') {
        const zoomFactor = orthoZoomFactors[canvasId] || 1;
        return Math.max(1, Math.round(1 * Math.sqrt(zoomFactor)));
    }
    // Perspective mode with logarithmic depth: use much larger base offset
    const cam = mainCameras[canvasId];
    if (!cam) return 1000;
    return Math.max(1000, Math.round(1000 * Math.sqrt(cam.radius / fitR)));
}

export function toggleEdges(canvasId, enabled) {
    const scene = scenes[canvasId];
    if (!scene) return;
    edgesEnabled[canvasId] = enabled;
    const edgeColor = getEdgeColorFromCss(darkModes[canvasId]);
    const width = getEdgesWidth(canvasId);
    // zOffset (factor) scales with camera distance in perspective to compensate for
    // non-linear depth precision. zOffsetUnits provides a constant depth bias that
    // prevents Z-fighting on flat faces viewed head-on (where the factor contribution is ~0).
    const zOffset      = getEdgesZOffset(canvasId);
    const zOffsetUnits = cameraProjection[canvasId] === 'orthographic' ? CONFIG.EDGES.zOffsetOrthographic : CONFIG.EDGES.zOffsetPerspective;
    scene.meshes.forEach(mesh => {
        // Skip system meshes: ground grid, axis gizmo parts, bounding box lines
        if (isSystemMesh(mesh)) return;
        if (enabled) {
            try {
                mesh.disableEdgesRendering();
                // Tighter epsilon catches chamfers and shallow draft angles on CAD parts.
                mesh.enableEdgesRendering(CONFIG.EDGES.epsilon, false, zOffset);
                mesh.edgesWidth = width;
                mesh.edgesColor = edgeColor;
                if (mesh._edgesRenderer && 'zOffsetUnits' in mesh._edgesRenderer) {
                    mesh._edgesRenderer.zOffsetUnits = zOffsetUnits;
                }
            } catch (_) {}
        } else {
            safeDisableEdges(mesh);
        }
    });

    // Attach view-matrix observer so edge width updates dynamically as you zoom
    // (works for both orthographic and perspective modes)
    if (enabled) {
        _attachEdgeZoomObserver(canvasId);
    } else {
        _detachEdgeZoomObserver(canvasId);
    }
}

/**
 * Attaches a camera view-matrix observer that re-applies edges width
 * and zOffset every time the user zooms in perspective mode.
 */
function _attachEdgeZoomObserver(canvasId) {
    _detachEdgeZoomObserver(canvasId); // remove any previous
    const cam   = mainCameras[canvasId];
    const scene = scenes[canvasId];
    if (!cam || !scene) return;
    edgeZoomObservers[canvasId] = cam.onViewMatrixChangedObservable.add(() => {
        if (!edgesEnabled[canvasId]) return;
        if (panStates[canvasId]?.active) return;  // Skip during pan to prevent stutter
        const w    = getEdgesWidth(canvasId);
        const zOff = getEdgesZOffset(canvasId);
        scene.meshes.forEach(mesh => {
            if (mesh.name === '__grid__' || mesh.name === '__shadow_catcher__' || mesh.name.startsWith('__axis') || mesh.name.startsWith('bbox_')) return;
            if (mesh._edgesRenderer) {
                mesh.edgesWidth = w;
                mesh._edgesRenderer.zOffset = zOff;
                if ('zOffsetUnits' in mesh._edgesRenderer) {
                    mesh._edgesRenderer.zOffsetUnits = CONFIG.EDGES.zOffsetPerspective;
                }
            }
        });
    });
}

function _detachEdgeZoomObserver(canvasId) {
    if (!edgeZoomObservers[canvasId]) return;
    const cam = mainCameras[canvasId];
    if (cam) cam.onViewMatrixChangedObservable.remove(edgeZoomObservers[canvasId]);
    delete edgeZoomObservers[canvasId];
}

// ── toggleBoundingBox ─────────────────────────────────────────────────────────

export function toggleBoundingBox(canvasId, enabled) {
    if (!enabled) { clearBoundingBox(canvasId); return; }

    const scene  = scenes[canvasId];
    const engine = engines[canvasId];
    const canvas = document.getElementById(canvasId);
    if (!scene || !engine || !canvas) return;

    clearBoundingBox(canvasId);

    const bb = sceneBoundingBoxes[canvasId];
    if (!bb) return;

    const v3 = (x, y, z) => new BABYLON.Vector3(x, y, z);

    // 12 edges of the bounding box (Z-up world: X=width, Y=depth, Z=height)
    const edges = [
        // 4 edges along X (width)
        [v3(bb.min.x, bb.min.y, bb.min.z), v3(bb.max.x, bb.min.y, bb.min.z)],
        [v3(bb.min.x, bb.max.y, bb.min.z), v3(bb.max.x, bb.max.y, bb.min.z)],
        [v3(bb.min.x, bb.min.y, bb.max.z), v3(bb.max.x, bb.min.y, bb.max.z)],
        [v3(bb.min.x, bb.max.y, bb.max.z), v3(bb.max.x, bb.max.y, bb.max.z)],
        // 4 edges along Y (depth)
        [v3(bb.min.x, bb.min.y, bb.min.z), v3(bb.min.x, bb.max.y, bb.min.z)],
        [v3(bb.max.x, bb.min.y, bb.min.z), v3(bb.max.x, bb.max.y, bb.min.z)],
        [v3(bb.min.x, bb.min.y, bb.max.z), v3(bb.min.x, bb.max.y, bb.max.z)],
        [v3(bb.max.x, bb.min.y, bb.max.z), v3(bb.max.x, bb.max.y, bb.max.z)],
        // 4 edges along Z (height)
        [v3(bb.min.x, bb.min.y, bb.min.z), v3(bb.min.x, bb.min.y, bb.max.z)],
        [v3(bb.max.x, bb.min.y, bb.min.z), v3(bb.max.x, bb.min.y, bb.max.z)],
        [v3(bb.min.x, bb.max.y, bb.min.z), v3(bb.min.x, bb.max.y, bb.max.z)],
        [v3(bb.max.x, bb.max.y, bb.min.z), v3(bb.max.x, bb.max.y, bb.max.z)],
    ];

    const gold = new BABYLON.Color4(1, 0.85, 0, 1);
    const lineMesh = BABYLON.MeshBuilder.CreateLineSystem('bbox_lines', {
        lines: edges,
        colors: edges.map(() => [gold, gold]),
        updatable: false
    }, scene);
    lineMesh.isPickable = false;
    bboxLines[canvasId] = lineMesh;

    // Dimension labels — midpoint of each dimension, worldPos is a mutable Vector3
    // so the render observable can reposition them to the camera-facing side each frame.
    const midX = (bb.min.x + bb.max.x) / 2;
    const midY = (bb.min.y + bb.max.y) / 2;
    const midZ = (bb.min.z + bb.max.z) / 2;
    const gap  = Math.max((bb.max.x - bb.min.x) * CONFIG.BBOX_LABEL_GAP_RATIO, CONFIG.BBOX_LABEL_GAP_MIN);

    const labelDefs = [
        { text: `X: ${(bb.max.x - bb.min.x).toFixed(1)} mm`, borderColor: '#f04444' },
        { text: `Y: ${(bb.max.y - bb.min.y).toFixed(1)} mm`, borderColor: '#22c750' },
        { text: `Z: ${(bb.max.z - bb.min.z).toFixed(1)} mm`, borderColor: '#3882f5' },
    ];

    const labelHost = canvas.parentElement ?? document.body;
    const labelEntries = labelDefs.map(({ text, borderColor }) => {
        const div = document.createElement('div');
        div.textContent = text;
        div.style.cssText = `
            position: absolute;
            transform: translate(-50%, -50%);
            background: rgba(10, 10, 14, 0.82);
            color: #f0f0f0;
            font-size: ${CONFIG.AXIS_GIZMO.labelFontSize};
            font-weight: 600;
            font-family: monospace;
            padding: 2px 7px;
            border-radius: 4px;
            border-left: 2px solid ${borderColor};
            pointer-events: none;
            white-space: nowrap;
            z-index: 20;
        `;
        labelHost.appendChild(div);
        // Use mutable Vector3 so each frame we can call .set() with the camera-facing anchor
        return { div, worldPos: new BABYLON.Vector3(midX, bb.min.y - gap, bb.min.z - gap) };
    });

    // Store entries + gap for use in the render observable
    bboxLabels[canvasId] = { entries: labelEntries, gap };

    // Update label world-positions and screen positions every frame
    const cam = mainCameras[canvasId];
    if (cam) {
        const obs = scene.onAfterRenderObservable.add(() => {
            const cvs  = engine.getRenderingCanvas();
            const rect = cvs?.getBoundingClientRect();
            if (!rect || rect.width <= 0 || rect.height <= 0) {
                labelEntries.forEach(({ div }) => { div.style.display = 'none'; });
                return;
            }
            const rw = engine.getRenderWidth(), rh = engine.getRenderHeight();
            // Build view×projection from the main camera explicitly — scene.getTransformMatrix()
            // is unreliable when activeCameras has multiple entries (returns last-rendered camera).
            const viewProj = cam.getViewMatrix().multiply(cam.getProjectionMatrix());

            // Reposition anchors to the camera-facing side of the bounding box each frame
            // so labels are never hidden behind the mesh when the camera orbits.
            const camPos = cam.position;
            const bbLive = sceneBoundingBoxes[canvasId];
            const g = bboxLabels[canvasId]?.gap ?? gap;
            if (bbLive) {
                const anchorY = camPos.y < (bbLive.min.y + bbLive.max.y) / 2 ? bbLive.min.y - g : bbLive.max.y + g;
                const anchorZ = camPos.z > (bbLive.min.z + bbLive.max.z) / 2 ? bbLive.max.z + g : bbLive.min.z - g;
                const anchorX = camPos.x > (bbLive.min.x + bbLive.max.x) / 2 ? bbLive.max.x + g : bbLive.min.x - g;
                const mx = (bbLive.min.x + bbLive.max.x) / 2;
                const my = (bbLive.min.y + bbLive.max.y) / 2;
                const mz = (bbLive.min.z + bbLive.max.z) / 2;
                labelEntries[0].worldPos.set(mx,      anchorY, anchorZ); // X dim label
                labelEntries[1].worldPos.set(anchorX, my,      anchorZ); // Y dim label
                labelEntries[2].worldPos.set(anchorX, anchorY, mz);      // Z dim label
            }

            labelEntries.forEach(({ div, worldPos }) => {
                const p = BABYLON.Vector3.Project(
                    worldPos, BABYLON.Matrix.Identity(), viewProj,
                    cam.viewport.toGlobal(rw, rh)
                );
                if (p.z >= 0 && p.z <= 1) {
                    div.style.left    = ((p.x / rw) * rect.width)  + 'px';
                    div.style.top     = ((p.y / rh) * rect.height) + 'px';
                    div.style.display = '';
                } else {
                    div.style.display = 'none';
                }
            });
        });
        bboxObservers[canvasId] = obs;
    }
}

function clearBoundingBox(canvasId) {
    if (bboxLines[canvasId]) { bboxLines[canvasId].dispose(); delete bboxLines[canvasId]; }
    if (bboxLabels[canvasId]) {
        bboxLabels[canvasId].entries.forEach(({ div }) => div.remove());
        delete bboxLabels[canvasId];
    }
    if (bboxObservers[canvasId]) {
        const scene = scenes[canvasId];
        if (scene) scene.onAfterRenderObservable.remove(bboxObservers[canvasId]);
        delete bboxObservers[canvasId];
    }
}

// ── showGrid / hideGrid ───────────────────────────────────────────────────────

const GRID_FADE_ANIMATION_MS = 240;
const gridAnimationStates = {};

function getGridThemeConfig(canvasId) {
    return isDarkMode(canvasId) ? CONFIG.GRID.dark : CONFIG.GRID.light;
}

function _gridNow() {
    return typeof performance !== 'undefined' && typeof performance.now === 'function'
        ? performance.now()
        : Date.now();
}

function _easeGridFade(t) {
    return t * t * (3 - 2 * t);
}

function _getGridOpacity(material) {
    if (!material) return 0;
    if (typeof material.opacity === 'number') return material.opacity;
    if (typeof material.alpha === 'number') return material.alpha;
    return 1;
}

function _setGridOpacity(material, opacity) {
    if (!material) return;
    if ('opacity' in material) {
        material.opacity = opacity;
    } else {
        material.alpha = opacity;
    }
}

function _cancelGridAnimation(canvasId) {
    const state = gridAnimationStates[canvasId];
    if (!state) return;
    if (state.observer && state.scene?.onBeforeRenderObservable?.remove) {
        state.scene.onBeforeRenderObservable.remove(state.observer);
    }
    delete gridAnimationStates[canvasId];
}

function _animateGridOpacity(canvasId, scene, grid, fromOpacity, toOpacity, onComplete) {
    const material = grid?.material;
    if (!grid || !material) {
        onComplete?.();
        return;
    }

    _cancelGridAnimation(canvasId);

    const apply = eased => {
        const opacity = fromOpacity + (toOpacity - fromOpacity) * eased;
        _setGridOpacity(material, opacity);
    };

    apply(0);

    if (!scene.onBeforeRenderObservable?.add) {
        apply(1);
        onComplete?.();
        return;
    }

    const startedAt = _gridNow();
    const state = { scene, observer: null };
    const tick = () => {
        const elapsed = Math.max(0, _gridNow() - startedAt);
        const t = Math.min(1, elapsed / GRID_FADE_ANIMATION_MS);
        apply(_easeGridFade(t));

        if (t >= 1) {
            if (state.observer && scene.onBeforeRenderObservable?.remove) {
                scene.onBeforeRenderObservable.remove(state.observer);
            }
            if (gridAnimationStates[canvasId] === state) {
                delete gridAnimationStates[canvasId];
            }
            onComplete?.();
        }
    };

    state.observer = scene.onBeforeRenderObservable.add(tick);
    gridAnimationStates[canvasId] = state;
}

/**
 * Shows a grid floor at the model's base (Z=0 after centering) to visualise
 * the print bed / machine table. Uses a 10mm-spaced GridMaterial.
 * The mesh is named '__grid__' so existing exclusion guards skip it in all
 * bounding-box, render-mode, shadow, and edge-rendering operations.
 */
export function showGrid(canvasId) {
    const scene = scenes[canvasId];
    if (!scene) return;

    const existing = scene.getMeshByName('__grid__');
    if (existing) {
        const targetOpacity = existing.metadata?.malievGridTargetOpacity ?? _getGridOpacity(existing.material);
        _animateGridOpacity(canvasId, scene, existing, _getGridOpacity(existing.material), targetOpacity);
        return;
    }

    const bb = sceneBoundingBoxes[canvasId];
    if (!bb) return;

    const sizeX = bb.max.x - bb.min.x;
    const sizeY = bb.max.y - bb.min.y;
    const gridSize = Math.max(sizeX, sizeY) * 3;

    // In Z-up space the floor is the XY plane at z=0 (already the model base after centering).
    // BabylonJS ground lies in the XZ plane by default, so we rotate −90° around X to flip it.
    const ground = BABYLON.MeshBuilder.CreateGround('__grid__', {
        width: gridSize, height: gridSize, subdivisions: 1
    }, scene);
    ground.rotation.x = -Math.PI / 2;
    ground.position.z = 0;
    ground.isPickable = false;
    ground.receiveShadows = true;

    if (typeof BABYLON.GridMaterial !== 'undefined') {
        const mat = new BABYLON.GridMaterial('__grid_mat__', scene);
        const gridTheme = getGridThemeConfig(canvasId);
        mat.majorUnitFrequency = CONFIG.GRID.majorUnitFrequency;
        mat.minorUnitVisibility = gridTheme.minorUnitVisibility;
        mat.gridRatio = CONFIG.GRID.gridRatio;
        mat.backFaceCulling = false;
        mat.mainColor   = toColor3(gridTheme.mainColor);
        mat.lineColor   = toColor3(gridTheme.lineColor);
        mat.opacity     = gridTheme.opacity;
        ground.material = mat;
        ground.metadata = { ...(ground.metadata ?? {}), malievGridTargetOpacity: gridTheme.opacity };
        disableSectionClippingForMesh(ground);
    } else {
        // GridMaterial CDN not yet loaded — use a plain transparent material as fallback
        const mat = new BABYLON.StandardMaterial('__grid_mat__', scene);
        mat.alpha = 0.15;
        mat.diffuseColor = new BABYLON.Color3(0.6, 0.6, 0.6);
        mat.backFaceCulling = false;
        ground.material = mat;
        ground.metadata = { ...(ground.metadata ?? {}), malievGridTargetOpacity: 0.15 };
        disableSectionClippingForMesh(ground);
    }

    const targetOpacity = ground.metadata.malievGridTargetOpacity;
    _setGridOpacity(ground.material, 0);
    _animateGridOpacity(canvasId, scene, ground, 0, targetOpacity);
}

/**
 * Removes the grid floor mesh from the scene.
 */
export function hideGrid(canvasId) {
    const scene = scenes[canvasId];
    if (!scene) return;
    const grid = scene.getMeshByName('__grid__');
    if (!grid) return;

    const fromOpacity = _getGridOpacity(grid.material);
    _animateGridOpacity(canvasId, scene, grid, fromOpacity, 0, () => {
        grid.dispose();
    });
}

// ── showCuttingMat / hideCuttingMat ───────────────────────────────────────────

const CUTTING_MAT_ANIMATION_MS = 240;
const CUTTING_MAT_ORTHOGRAPHIC_CAMERA_MIN_Z = 0.001;
const CUTTING_MAT_PERSPECTIVE_CAMERA_MIN_Z = 0.01;
const CUTTING_MAT_MINOR_GRID_MM = 10;
const CUTTING_MAT_MAJOR_GRID_MM = 100;
const CUTTING_MAT_NUMBER_FONT_MM = 4.5;
const CUTTING_MAT_SURFACE_COLOR = '#2d7a4f';
const CUTTING_MAT_TOP_OVERLAP_MM = 0.6;
const MALIEV_LOGO_VIEWBOX = { width: 449.33078, height: 103.18751 };
const MALIEV_LOGO_GROUP_TRANSLATE = { x: 178.09872, y: -25.13541 };
// Source: wwwroot/images/logo.svg. Keep this path in sync with the asset.
const MALIEV_LOGO_PATH = 'M 246.47181,25.13541 220.60482,96.206993 194.73651,25.13541 H 112.1492 v 103.1875 h 82.12005 l -7.5983,-20.90209 H 135.43254 V 86.783323 l 43.73483,-10e-4 -7.02072,-19.31352 h -36.71411 v -21.69583 l 42.02139,10e-4 30.04555,82.548947 h 26.17523 L 271.23205,25.13541 Z M 83.045039,128.32291 H 106.32837 V 25.13541 H 83.045039 Z m -126.51,-41.538527 11.54854,-30.12334 11.54985,30.12228 z m 85.235,-61.648973 h -24.87084 v 91.01666 l -36.7284,-91.01666 h -24.17312 l -36.72973,91.01666 V 25.13541 h -24.341659 l -24.34167,42.212423 -24.34167,-42.212423 h -24.34167 v 103.1875 h 24.34167 V 76.729163 l 17.03996,30.691657 h 14.60474 l 17.03864,-30.691657 v 51.593747 h 45.682159 l 8.01502,-20.90209 h 38.92153 l 8.0139697,20.90209 H 76.959619 v -20.90209 h -35.18958 z';
const cuttingMatAnimationStates = {};
const cuttingMatCameraClipStates = {};

function _cuttingMatSlabOutline(width, height, radius) {
    return _roundedRectPoints(width, height, radius, 8);
}

function _cuttingMatTopOutline(width, height, radius) {
    const overlap = CUTTING_MAT_TOP_OVERLAP_MM;
    return _roundedRectPoints(width + overlap * 2, height + overlap * 2, radius + overlap, 8);
}

function _primeCuttingMatTextureBleedGuard(ctx, width, height) {
    ctx.fillStyle = CUTTING_MAT_SURFACE_COLOR;
    ctx.fillRect(0, 0, width, height);
}

/**
 * Renders a realistic cutting-mat floor at model base (Z=0).
 *
 * Design:
 *   - Brighter green (#2e7d52 surface, lit with emissive baseline)
 *   - 16 mm margin band: grid lines stop at the border, numbers live in the margin
 *   - Rounded corners (8 mm radius) in both the visible top and slab geometry
 *   - Raw RGBA texture upload so the green surface, grid, and labels render immediately
 *   - Top-right MALIEV wordmark, away from the scale labels
 *   - Manual convex fan triangulation (no CreatePolygon / earcut dependency)
 */
export function showCuttingMat(canvasId) {
    const scene = scenes[canvasId];
    if (!scene) return;

    _cancelCuttingMatAnimation(canvasId);
    ['__cutting_mat__', '__cutting_mat_slab__'].forEach(n => {
        const m = scene.getMeshByName(n);
        if (m) m.dispose(false, true);
    });

    const bb = sceneBoundingBoxes[canvasId];
    if (!bb) {
        _restoreCuttingMatCameraClipping(canvasId);
        return;
    }
    _relaxCuttingMatCameraClipping(canvasId, scene, true);

    const modelW = bb.max.x - bb.min.x;
    const modelH = bb.max.y - bb.min.y;

    const PAD    = 60;   // mm clearance around model
    const MARGIN = 16;   // mm margin band (numbers + title live here, outside grid)
    const CORNER = 8;    // mm corner fillet radius
    const THICK  = 3;    // mm slab thickness
    const matW   = Math.ceil(Math.max(300, modelW + PAD * 2) / 10) * 10;
    const matH   = Math.ceil(Math.max(220, modelH + PAD * 2) / 10) * 10;
    const slideOffset = _cuttingMatSlideOffset(bb);
    cuttingMatFrameBoundsMap[canvasId] = _cuttingMatFrameBounds(bb, matW, matH, THICK);
    _applyCameraFitBounds(canvasId, cuttingMatFrameBoundsMap[canvasId]);

    // ── Texture ───────────────────────────────────────────────────────────────
    const TEX_W = 2048;
    const TEX_H = Math.max(256, Math.round(TEX_W * matH / matW));
    const px    = TEX_W / matW;   // pixels per mm
    const MPX   = MARGIN * px;    // margin in pixels
    const CPX   = CORNER * px;    // corner radius in pixels

    // Pre-create a standard HTML canvas — BabylonJS DynamicTexture's internal
    // canvas suppresses ctx.fillRect in some build configurations, producing a
    // blue/blank mat surface.  Drawing to a plain canvas always works.
    // Drawing to canvas first keeps text/grid crisp before the raw RGBA upload.
    const rawCanvas = document.createElement('canvas');
    rawCanvas.width  = TEX_W;
    rawCanvas.height = TEX_H;
    const ctx = rawCanvas.getContext('2d');
    _primeCuttingMatTextureBleedGuard(ctx, TEX_W, TEX_H);

    // Helper: build a rounded-rect path on ctx
    const _rrPath = (x, y, w, h, r) => {
        ctx.beginPath();
        ctx.moveTo(x + r, y);
        ctx.lineTo(x + w - r, y);
        ctx.arcTo(x + w, y,     x + w, y + r,   r);
        ctx.lineTo(x + w, y + h - r);
        ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
        ctx.lineTo(x + r, y + h);
        ctx.arcTo(x,     y + h, x,     y + h - r, r);
        ctx.lineTo(x,     y + r);
        ctx.arcTo(x,     y,     x + r,   y,       r);
        ctx.closePath();
    };

    // ── Background with rounded corners ───────────────────────────────────────
    _rrPath(0, 0, TEX_W, TEX_H, CPX);
    ctx.fillStyle = CUTTING_MAT_SURFACE_COLOR;
    ctx.fill();
    // Clip all subsequent drawing to the rounded rectangle
    _rrPath(0, 0, TEX_W, TEX_H, CPX);
    ctx.clip();

    // ── Outer mat border ──────────────────────────────────────────────────────
    const borderW = Math.max(3, px * 1.6);
    ctx.strokeStyle = 'rgba(255,255,255,0.45)';
    ctx.lineWidth   = borderW;
    _rrPath(borderW / 2, borderW / 2, TEX_W - borderW, TEX_H - borderW, Math.max(0, CPX - borderW / 2));
    ctx.stroke();

    // ── Inner grid-area border ────────────────────────────────────────────────
    ctx.strokeStyle = 'rgba(255,255,255,0.60)';
    ctx.lineWidth   = Math.max(2, px * 1.0);
    ctx.strokeRect(MPX, MPX, TEX_W - 2 * MPX, TEX_H - 2 * MPX);

    // ── Grid lines (symmetric — no mirroring needed) ──────────────────────────
    _cuttingMatGridLines(ctx, TEX_W - 2 * MPX, TEX_H - 2 * MPX,
        CUTTING_MAT_MINOR_GRID_MM * px, 'rgba(255,255,255,0.28)', Math.max(0.8, px * 0.40), MPX, MPX);
    _cuttingMatGridLines(ctx, TEX_W - 2 * MPX, TEX_H - 2 * MPX,
        CUTTING_MAT_MAJOR_GRID_MM * px, 'rgba(255,255,255,0.70)', Math.max(1.5, px * 0.85), MPX, MPX);

    // ── Margin logo + number labels ───────────────────────────────────────────
    const NUMBER_LABEL_PX = Math.round(px * CUTTING_MAT_NUMBER_FONT_MM);
    const LABEL_STEP      = 10 * px;
    const colCount        = Math.round((matW - 2 * MARGIN) / 10);
    const rowCount        = Math.round((matH - 2 * MARGIN) / 10);
    ctx.fillStyle         = 'rgba(255,255,255,0.88)';
    _drawCuttingMatLogo(ctx, TEX_W - MPX * 0.45, MPX * 0.5, MPX * 0.44);

    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = `bold ${NUMBER_LABEL_PX}px Arial, sans-serif`;

    // Bottom edge labels (column axis), matching the physical mat reference.
    for (let i = 0; i <= colCount; i++) {
        const cx = MPX + i * LABEL_STEP;
        ctx.fillText(String(i), cx, TEX_H - MPX * 0.5);
    }

    // Left edge labels (row axis). The top/right margins stay clear for the title.
    for (let j = 0; j <= rowCount; j++) {
        const cy = MPX + j * LABEL_STEP;
        ctx.fillText(String(j), MPX * 0.5, cy);
    }

    // ── Upload texture from raw RGBA pixels ───────────────────────────────────
    const tex = _createCuttingMatTexture(scene, rawCanvas, TEX_W, TEX_H);

    // ── Rounded top surface and slab body ─────────────────────────────────────
    const slabOutline = _cuttingMatSlabOutline(matW, matH, CORNER);
    const topOutline = _cuttingMatTopOutline(matW, matH, CORNER);
    const topMesh = _createRoundedMatTopMesh(scene, topOutline, matW, matH);

    const topMat = _createCuttingMatTopMaterial(scene, canvasId, tex, 0);
    topMesh.material = topMat;
    topMesh.metadata = { ...(topMesh.metadata ?? {}), malievCuttingMatSlideOffset: slideOffset };
    disableSectionClippingForMesh(topMesh);

    const slabMesh = _createRoundedMatSlabMesh(scene, slabOutline, THICK);

    const slabMat = _createCuttingMatSlabMaterial(scene, canvasId, 0);
    slabMesh.material = slabMat;
    slabMesh.metadata = { ...(slabMesh.metadata ?? {}), malievCuttingMatSlideOffset: slideOffset };
    disableSectionClippingForMesh(slabMesh);

    // ── Hide the shadow catcher ───────────────────────────────────────────────
    // The __shadow_catcher__ mesh sits at z=0 — the same plane as the mat top
    // surface.  Leaving it visible causes z-fighting that makes the model shadow
    // appear shifted / "ghosted" on the mat and can leak through the slab when
    // viewed from below. The mat is a visual reference surface, not a shadow receiver.
    const shadowCatcher = scene.getMeshByName('__shadow_catcher__');
    if (shadowCatcher) shadowCatcher.isVisible = false;

    _animateCuttingMat(canvasId, scene, [topMesh, slabMesh], [topMat, slabMat], {
        fromZ: -slideOffset,
        toZ: 0,
        fromAlpha: 0,
        toAlpha: 1,
        onComplete: () => _setCuttingMatMaterialsOpaque([topMat, slabMat]),
    });
}

function _drawCuttingMatLogo(ctx, rightX, centerY, logoHeight) {
    if (typeof Path2D === 'undefined') {
        ctx.font = `900 ${Math.round(logoHeight)}px Arial Black, Arial, sans-serif`;
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillText('MALIEV', rightX, centerY);
        return;
    }

    const scale = logoHeight / MALIEV_LOGO_VIEWBOX.height;
    const logoWidth = MALIEV_LOGO_VIEWBOX.width * scale;
    const leftX = rightX - logoWidth;
    const topY = centerY - logoHeight / 2;
    const path = new Path2D(MALIEV_LOGO_PATH);

    ctx.save();
    ctx.translate(leftX, topY);
    ctx.scale(scale, scale);
    ctx.translate(MALIEV_LOGO_GROUP_TRANSLATE.x, MALIEV_LOGO_GROUP_TRANSLATE.y);
    ctx.fill(path);
    ctx.restore();
}

function _cuttingMatSlideOffset(bb) {
    const modelHeight = Math.max(0, (bb?.max?.z ?? 0) - (bb?.min?.z ?? 0));
    return Math.max(12, Math.min(40, modelHeight * 0.35 || 18));
}

function _cuttingMatFrameBounds(modelBounds, matW, matH, thickness) {
    return {
        min: {
            x: Math.min(modelBounds.min.x, -matW / 2),
            y: Math.min(modelBounds.min.y, -matH / 2),
            z: Math.min(modelBounds.min.z, -thickness),
        },
        max: {
            x: Math.max(modelBounds.max.x, matW / 2),
            y: Math.max(modelBounds.max.y, matH / 2),
            z: modelBounds.max.z,
        },
    };
}

function _restoreModelCameraFit(canvasId) {
    const modelFit = modelFitRadiusMap[canvasId];
    const modelBounds = sceneBoundingBoxes[canvasId];
    if (!modelFit || !modelBounds) return;

    delete cuttingMatFrameBoundsMap[canvasId];
    _applyCameraFitBounds(canvasId, modelBounds);
}

function _cuttingMatNow() {
    return typeof performance !== 'undefined' && typeof performance.now === 'function'
        ? performance.now()
        : Date.now();
}

function _easeCuttingMat(t) {
    return t * t * (3 - 2 * t);
}

function _applyCuttingMatAnimation(meshes, materials, z, alpha) {
    meshes.forEach(mesh => {
        if (mesh?.position) mesh.position.z = z;
    });
    materials.forEach(material => {
        if (material) material.alpha = alpha;
    });
}

function _cuttingMatAlphaBlendMode() {
    return BABYLON.Material?.MATERIAL_ALPHABLEND ?? 2;
}

function _cuttingMatOpaqueMode() {
    return BABYLON.Material?.MATERIAL_OPAQUE ?? 0;
}

function _setCuttingMatMaterialsForFade(materials) {
    materials.forEach(material => {
        if (!material) return;
        material.transparencyMode = _cuttingMatAlphaBlendMode();
        material.needDepthPrePass = false;
    });
}

function _setCuttingMatMaterialsOpaque(materials) {
    materials.forEach(material => {
        if (!material) return;
        material.alpha = 1;
        material.transparencyMode = _cuttingMatOpaqueMode();
        material.needDepthPrePass = false;
    });
}

function _createCuttingMatTopMaterial(scene, canvasId, texture, alpha = 1) {
    const mat = new BABYLON.StandardMaterial('__cutting_mat_mat__', scene);
    mat.diffuseTexture = texture;
    mat.useAlphaFromDiffuseTexture = false;
    mat.diffuseColor = new BABYLON.Color3(1, 1, 1);
    mat.emissiveColor = new BABYLON.Color3(0.04, 0.12, 0.06);
    mat.ambientColor = new BABYLON.Color3(0.18, 0.42, 0.26);
    mat.specularColor = new BABYLON.Color3(0.02, 0.05, 0.03);
    mat.backFaceCulling = false;
    mat.transparencyMode = alpha < 1 ? _cuttingMatAlphaBlendMode() : _cuttingMatOpaqueMode();
    mat.alphaCutOff = 0.5;
    mat.alpha = alpha;
    return mat;
}

function _createCuttingMatSlabMaterial(scene, canvasId, alpha = 1) {
    const mat = new BABYLON.StandardMaterial('__cutting_mat_slab_mat__', scene);
    mat.diffuseColor = new BABYLON.Color3(0.12, 0.40, 0.24);
    mat.emissiveColor = new BABYLON.Color3(0.05, 0.15, 0.08);
    mat.specularColor = new BABYLON.Color3(0.02, 0.05, 0.03);
    mat.backFaceCulling = false;
    mat.transparencyMode = alpha < 1 ? _cuttingMatAlphaBlendMode() : _cuttingMatOpaqueMode();
    mat.alpha = alpha;
    return mat;
}

function _syncCuttingMatRenderMode(canvasId) {
    const scene = scenes[canvasId];
    if (!scene) return;

    const top = _sceneMeshByName(scene, '__cutting_mat__');
    const slab = _sceneMeshByName(scene, '__cutting_mat_slab__');
    const wantPbr = false;

    if (top?.material && (!!(top.material instanceof BABYLON.PBRMaterial) !== wantPbr)) {
        const oldMat = top.material;
        const texture = oldMat.albedoTexture ?? oldMat.diffuseTexture ?? null;
        top.material = _createCuttingMatTopMaterial(scene, canvasId, texture, oldMat.alpha ?? 1);
        try { oldMat.dispose?.(false, false); } catch (_) {}
    }

    if (slab?.material && (!!(slab.material instanceof BABYLON.PBRMaterial) !== wantPbr)) {
        const oldMat = slab.material;
        slab.material = _createCuttingMatSlabMaterial(scene, canvasId, oldMat.alpha ?? 1);
        try { oldMat.dispose?.(false, false); } catch (_) {}
    }

    [top, slab].forEach(mesh => {
        if (!mesh) return;
        mesh.receiveShadows = false;
        disableSectionClippingForMesh(mesh);
    });
}

function _sceneMeshByName(scene, name) {
    return scene?.getMeshByName?.(name) ?? scene?.meshes?.find(mesh => mesh.name === name && !mesh.disposed) ?? null;
}

function _cuttingMatCamera(canvasId, scene) {
    return mainCameras[canvasId] ?? scene?.activeCamera ?? null;
}

function _cuttingMatCameraMinZ(canvasId) {
    return cameraProjection[canvasId] === 'orthographic'
        ? CUTTING_MAT_ORTHOGRAPHIC_CAMERA_MIN_Z
        : CUTTING_MAT_PERSPECTIVE_CAMERA_MIN_Z;
}

function _enforceCuttingMatCameraClipping(canvasId, scene) {
    const state = cuttingMatCameraClipStates[canvasId];
    const camera = _cuttingMatCamera(canvasId, scene);
    if (!state || !camera || typeof camera.minZ !== 'number') return;
    const minZ = _cuttingMatCameraMinZ(canvasId);
    state.targetMinZ = minZ;
    camera.minZ = minZ;
}

function _hasCuttingMatMesh(scene) {
    return !!(_sceneMeshByName(scene, '__cutting_mat__') || _sceneMeshByName(scene, '__cutting_mat_slab__'));
}

function _relaxCuttingMatCameraClipping(canvasId, scene, force = false) {
    const camera = _cuttingMatCamera(canvasId, scene);
    if (!camera || typeof camera.minZ !== 'number') return;

    const state = cuttingMatCameraClipStates[canvasId];
    if (!force && !state && !_hasCuttingMatMesh(scene)) return;
    if (state?.camera && state.camera !== camera) {
        _restoreCuttingMatCameraClipping(canvasId);
    }

    if (!cuttingMatCameraClipStates[canvasId]) {
        cuttingMatCameraClipStates[canvasId] = {
            camera,
            minZ: camera.minZ,
            targetMinZ: _cuttingMatCameraMinZ(canvasId),
            scene,
            observer: null,
        };
    }

    const activeState = cuttingMatCameraClipStates[canvasId];
    if (!activeState.observer && scene?.onBeforeRenderObservable?.add) {
        activeState.observer = scene.onBeforeRenderObservable.add(() => {
            _enforceCuttingMatCameraClipping(canvasId, scene);
        });
    }

    _enforceCuttingMatCameraClipping(canvasId, scene);
}

function _restoreCuttingMatCameraClipping(canvasId) {
    const state = cuttingMatCameraClipStates[canvasId];
    if (!state) return;

    if (state.observer && state.scene?.onBeforeRenderObservable?.remove) {
        state.scene.onBeforeRenderObservable.remove(state.observer);
    }

    const targetMinZ = state.targetMinZ ?? _cuttingMatCameraMinZ(canvasId);
    if (state.camera && typeof state.camera.minZ === 'number'
        && state.camera.minZ <= targetMinZ + 0.000001) {
        state.camera.minZ = state.minZ;
    }

    delete cuttingMatCameraClipStates[canvasId];
}

function _cancelCuttingMatAnimation(canvasId) {
    const state = cuttingMatAnimationStates[canvasId];
    if (!state) return;
    if (state.observer && state.scene?.onBeforeRenderObservable?.remove) {
        state.scene.onBeforeRenderObservable.remove(state.observer);
    }
    delete cuttingMatAnimationStates[canvasId];
}

function _animateCuttingMat(canvasId, scene, meshes, materials, options) {
    const durationMs = CUTTING_MAT_ANIMATION_MS;
    const startedAt = _cuttingMatNow();

    const apply = eased => {
        const z = options.fromZ + (options.toZ - options.fromZ) * eased;
        const alpha = options.fromAlpha + (options.toAlpha - options.fromAlpha) * eased;
        _applyCuttingMatAnimation(meshes, materials, z, alpha);
    };

    apply(0);

    if (!scene.onBeforeRenderObservable?.add) {
        apply(1);
        options.onComplete?.();
        return;
    }

    const state = { scene, observer: null };
    const tick = () => {
        const elapsed = Math.max(0, _cuttingMatNow() - startedAt);
        const t = Math.min(1, elapsed / durationMs);
        apply(_easeCuttingMat(t));

        if (t >= 1) {
            if (state.observer && scene.onBeforeRenderObservable?.remove) {
                scene.onBeforeRenderObservable.remove(state.observer);
            }
            if (cuttingMatAnimationStates[canvasId] === state) {
                delete cuttingMatAnimationStates[canvasId];
            }
            options.onComplete?.();
        }
    };

    state.observer = scene.onBeforeRenderObservable.add(tick);
    cuttingMatAnimationStates[canvasId] = state;
}

function _createCuttingMatTexture(scene, rawCanvas, width, height) {
    const ctx = rawCanvas.getContext('2d');
    const pixels = ctx.getImageData(0, 0, width, height).data;

    if (BABYLON.RawTexture?.CreateRGBATexture) {
        const samplingMode = BABYLON.Constants?.TEXTURE_TRILINEAR_SAMPLINGMODE
            ?? BABYLON.Texture?.TRILINEAR_SAMPLINGMODE
            ?? 3;
        const tex = BABYLON.RawTexture.CreateRGBATexture(
            pixels,
            width,
            height,
            scene,
            true,
            false,
            samplingMode);
        tex.hasAlpha = false;
        if (BABYLON.Texture?.CLAMP_ADDRESSMODE !== undefined) {
            tex.wrapU = BABYLON.Texture.CLAMP_ADDRESSMODE;
            tex.wrapV = BABYLON.Texture.CLAMP_ADDRESSMODE;
        }
        return tex;
    }

    const tex = new BABYLON.DynamicTexture('__cutting_mat_tex__', { width, height }, scene, false);
    tex.hasAlpha = false;
    const texCtx = tex.getContext?.();
    if (texCtx?.putImageData) {
        texCtx.putImageData(ctx.getImageData(0, 0, width, height), 0, 0);
    } else if (texCtx?.drawImage) {
        texCtx.drawImage(rawCanvas, 0, 0);
    }
    tex.update(false);
    return tex;
}

function _roundedRectPoints(width, height, radius, segments) {
    const hw = width / 2;
    const hh = height / 2;
    const r = Math.min(radius, hw, hh);
    const arcs = [
        { cx:  hw - r, cy:  hh - r, start: 0, end: Math.PI / 2 },
        { cx: -hw + r, cy:  hh - r, start: Math.PI / 2, end: Math.PI },
        { cx: -hw + r, cy: -hh + r, start: Math.PI, end: Math.PI * 1.5 },
        { cx:  hw - r, cy: -hh + r, start: Math.PI * 1.5, end: Math.PI * 2 },
    ];
    const pts = [];
    arcs.forEach(arc => {
        for (let i = 0; i <= segments; i++) {
            const t = i / segments;
            const a = arc.start + (arc.end - arc.start) * t;
            pts.push({
                x: arc.cx + Math.cos(a) * r,
                y: arc.cy + Math.sin(a) * r,
            });
        }
    });
    return pts;
}

function _cuttingMatUv(x, y, width, height) {
    return {
        u: 1 - ((x + width / 2) / width),
        v: 1 - ((y + height / 2) / height),
    };
}

function _createRoundedMatTopMesh(scene, outline, width, height) {
    const mesh = new BABYLON.Mesh('__cutting_mat__', scene);
    const positions = [0, 0, 0];
    const indices = [];
    const normals = [0, 0, 1];
    const uvs = [0.5, 0.5];

    outline.forEach(p => {
        positions.push(p.x, p.y, 0);
        normals.push(0, 0, 1);
        const uv = _cuttingMatUv(p.x, p.y, width, height);
        uvs.push(uv.u, uv.v);
    });

    for (let i = 1; i <= outline.length; i++) {
        const next = i === outline.length ? 1 : i + 1;
        indices.push(0, i, next);
    }

    const vertexData = new BABYLON.VertexData();
    vertexData.positions = positions;
    vertexData.indices = indices;
    vertexData.normals = normals;
    vertexData.uvs = uvs;
    vertexData.applyToMesh(mesh);

    mesh.isPickable = false;
    mesh.receiveShadows = false;
    return markAnalysisHelperMesh(mesh);
}

function _createRoundedMatSlabMesh(scene, outline, thickness) {
    const mesh = new BABYLON.Mesh('__cutting_mat_slab__', scene);
    const positions = [];
    const indices = [];
    const topZ = 0;
    const bottomZ = -thickness;

    outline.forEach(p => positions.push(p.x, p.y, topZ));
    outline.forEach(p => positions.push(p.x, p.y, bottomZ));

    const n = outline.length;
    for (let i = 0; i < n; i++) {
        const next = (i + 1) % n;
        indices.push(i, next, next + n, i, next + n, i + n);
    }

    const bottomCenterIndex = positions.length / 3;
    positions.push(0, 0, bottomZ);
    outline.forEach(p => positions.push(p.x, p.y, bottomZ));
    for (let i = 0; i < n; i++) {
        const current = bottomCenterIndex + 1 + i;
        const next = bottomCenterIndex + 1 + ((i + 1) % n);
        indices.push(bottomCenterIndex, next, current);
    }

    const normals = [];
    if (BABYLON.VertexData.ComputeNormals) {
        BABYLON.VertexData.ComputeNormals(positions, indices, normals);
    }

    const vertexData = new BABYLON.VertexData();
    vertexData.positions = positions;
    vertexData.indices = indices;
    if (normals.length > 0) vertexData.normals = normals;
    vertexData.applyToMesh(mesh);

    mesh.isPickable = false;
    mesh.receiveShadows = false;
    return markAnalysisHelperMesh(mesh);
}

/**
 * Draws a uniform grid pass (horizontal + vertical) clipped to an inset rectangle.
 * offsetX/Y shift the grid origin so lines start at the grid-area edge.
 */
function _cuttingMatGridLines(ctx, w, h, step, color, lineWidth, offsetX = 0, offsetY = 0) {
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth   = lineWidth;
    ctx.beginPath();
    for (let x = 0; x <= w + 0.5; x += step) {
        ctx.moveTo(x + offsetX, offsetY);
        ctx.lineTo(x + offsetX, offsetY + h);
    }
    for (let y = 0; y <= h + 0.5; y += step) {
        ctx.moveTo(offsetX,     y + offsetY);
        ctx.lineTo(offsetX + w, y + offsetY);
    }
    ctx.stroke();
    ctx.restore();
}

/**
 * Removes the cutting-mat meshes (top plane + slab body) from the scene,
 * disposing materials and texture resources together to avoid memory leaks.
 */
export function hideCuttingMat(canvasId) {
    const scene = scenes[canvasId];
    if (!scene) return;

    _cancelCuttingMatAnimation(canvasId);
    const meshes = ['__cutting_mat__', '__cutting_mat_slab__']
        .map(n => scene.getMeshByName(n))
        .filter(Boolean);
    const shadowCatcher = scene.getMeshByName('__shadow_catcher__');

    if (meshes.length === 0) {
        if (shadowCatcher) shadowCatcher.isVisible = true;
        _restoreModelCameraFit(canvasId);
        _restoreCuttingMatCameraClipping(canvasId);
        return;
    }

    const materials = meshes.map(mesh => mesh.material).filter(Boolean);
    const slideOffset = Math.max(...meshes.map(mesh => mesh.metadata?.malievCuttingMatSlideOffset ?? 18));
    const fromZ = meshes[0]?.position?.z ?? 0;
    const fromAlpha = materials[0]?.alpha ?? 1;
    _setCuttingMatMaterialsForFade(materials);

    _animateCuttingMat(canvasId, scene, meshes, materials, {
        fromZ,
        toZ: -slideOffset,
        fromAlpha,
        toAlpha: 0,
        onComplete: () => {
            meshes.forEach(mesh => mesh.dispose(false, true));
            if (shadowCatcher) shadowCatcher.isVisible = true;
            _restoreModelCameraFit(canvasId);
            _restoreCuttingMatCameraClipping(canvasId);
        },
    });
}

// ── setCameraProjection ───────────────────────────────────────────────────────

/**
 * Toggle between perspective and orthographic projection for the main camera.
 * In ortho mode the ortho bounds are kept in sync with camera radius so
 * scroll-to-zoom continues to work.
 */
export function setCameraProjection(canvasId, mode) {
    const cam    = mainCameras[canvasId];
    const engine = engines[canvasId];
    debugLog('[BabylonViewer] setCameraProjection:', canvasId, mode, 'cam?', !!cam, 'engine?', !!engine);
    if (!cam || !engine) return;

    cameraProjection[canvasId] = mode;

    if (mode === 'orthographic') {
        const meshRadius = fitRadiusMap[canvasId] || cam.radius;
        orthoZoomFactors[canvasId] = cam.radius / meshRadius;
        const aspect = engine.getAspectRatio(cam);
        const half   = cam.radius * ORTHO_RADIUS_FACTOR;
        cam.mode        = BABYLON.Camera.ORTHOGRAPHIC_CAMERA;
        cam.orthoLeft   = -half * aspect;
        cam.orthoRight  =  half * aspect;
        cam.orthoTop    =  half;
        cam.orthoBottom = -half;
        cam.minZ        = Math.max(meshRadius * CONFIG.CAMERA_NEAR_PLANE, 0.01);
        _relaxCuttingMatCameraClipping(canvasId, scenes[canvasId]);

        // Keep ortho bounds in sync when the user zooms — but do NOT move camera!
        // Accumulate zoom factor and compute ortho bounds from it, then reset cam.radius.
        if (!orthoZoomObservers[canvasId]) {
            let _orthoGuard = false;  // prevent recursive observer calls when we reset radius
            orthoZoomObservers[canvasId] = cam.onViewMatrixChangedObservable.add(() => {
                if (cameraProjection[canvasId] !== 'orthographic' || _orthoGuard || _arcAnimGuard[canvasId]) return;
                const initialRadius = fitRadiusMap[canvasId] || cam.radius;
                if (!orthoZoomFactors[canvasId]) orthoZoomFactors[canvasId] = 1.0;

                // Compute how much radius changed (ratio to initial) and accumulate
                const ratio = cam.radius / initialRadius;
                orthoZoomFactors[canvasId] *= ratio;

                // Update ortho bounds from zoom factor, not from moving camera
                const asp = engine.getAspectRatio(cam);
                const h   = initialRadius * orthoZoomFactors[canvasId] * ORTHO_RADIUS_FACTOR;
                cam.orthoLeft   = -h * asp;
                cam.orthoRight  =  h * asp;
                cam.orthoTop    =  h;
                cam.orthoBottom = -h;

                // Reset camera to initial distance — prevents camera from moving into model
                _orthoGuard = true;
                cam.radius = initialRadius;
                cam.minZ    = Math.max(meshRadius * CONFIG.CAMERA_NEAR_PLANE, 0.01);
                _relaxCuttingMatCameraClipping(canvasId, scenes[canvasId]);
                _orthoGuard = false;
            });
        }

        // Update near plane dynamically for perspective camera too
        if (!perspZoomObservers[canvasId]) {
            perspZoomObservers[canvasId] = cam.onViewMatrixChangedObservable.add(() => {
                if (cameraProjection[canvasId] === 'orthographic') return;
                if (panStates[canvasId]?.active) return;  // Skip during pan to prevent stutter
                cam.minZ = 0.1;
                _relaxCuttingMatCameraClipping(canvasId, scenes[canvasId]);
            });
        }
    } else {
        // Switching to perspective: set radius from ortho zoom level to preserve zoom
        const initialRadius = fitRadiusMap[canvasId];
        if (initialRadius && orthoZoomFactors[canvasId]) {
            cam.radius = initialRadius * orthoZoomFactors[canvasId];
        }
        cam.mode = BABYLON.Camera.PERSPECTIVE_CAMERA;
        cam.minZ  = 0.01;
        _relaxCuttingMatCameraClipping(canvasId, scenes[canvasId]);
    }

    // Re-apply edges at the width suitable for the new projection mode.
    if (edgesEnabled[canvasId]) toggleEdges(canvasId, true);
}

// ── DFM Overlays ──────────────────────────────────────────────────────────────
// overlayMeshes[canvasId] → Map<overlayKey, BABYLON.AbstractMesh[]>
// overlayLoading[canvasId] → Set<overlayKey> (prevents concurrent loads)
// overlayIntendedVisible[canvasId] → Map<overlayKey, boolean> (handles race: hide before lazy load)
const overlayMeshes          = {};
const overlayLoading         = {};
const overlayIntendedVisible = {};

// Per-category PBR material overrides for DFM overlays.
// Keys are the category suffix (everything after the last "__" in the overlay key).
// If a key is absent the default red style is used.
const OVERLAY_STYLES = {
    overhang_support: {
        albedo:   () => new BABYLON.Color3(0.12, 0.55, 0.95), // support blue
        alpha:    0.34,
        emissive: () => new BABYLON.Color3(0.02, 0.08, 0.16),
        zOffset:  -6,
    },
    support_required: {
        albedo:   () => new BABYLON.Color3(0.12, 0.55, 0.95), // support blue
        alpha:    0.34,
        emissive: () => new BABYLON.Color3(0.02, 0.08, 0.16),
        zOffset:  -6,
    },
};

/**
 * Toggles a DFM overlay GLB on the scene. Lazy-loads on first show.
 * @param {string} canvasId
 * @param {string} overlayKey  e.g. "FDM__thin_wall"
 * @param {string} glbUrl      Signed URL to the overlay GLB
 * @param {boolean} visible    true = show, false = hide
 */
export async function toggleDfmOverlay(canvasId, partKey, overlayKey, glbUrl, visible) {
    const scene = scenes[canvasId];
    if (!scene) return;

    // Use a composite slot so each part's overlays never collide with another part's.
    const slot = `${canvasId}::${partKey}`;
    overlayMeshes[slot]          ??= new Map();
    overlayLoading[slot]         ??= new Set();
    overlayIntendedVisible[slot] ??= new Map();

    // Always record the intended visibility so the post-load callback can apply it.
    overlayIntendedVisible[slot].set(overlayKey, visible);

    const existing = overlayMeshes[slot].get(overlayKey);
    if (existing) {
        existing.forEach(m => { m.isVisible = visible; });
        return;
    }

    if (!visible) return; // nothing to load for a hide-before-load request

    if (overlayLoading[slot].has(overlayKey)) return; // already loading
    overlayLoading[slot].add(overlayKey);

    try {
        const result = await BABYLON.SceneLoader.ImportMeshAsync('', '', glbUrl, scene, null, '.glb');
        const meshes = result.meshes.filter(m => m.getTotalVertices() > 0);

        // Apply the same three transforms that initialize applies to the main model
        // so overlays align perfectly in world space.
        const scaleFactor = modelScaleFactors[canvasId] ?? 1;
        const offset = modelCenterOffsets[canvasId] ?? { cx: 0, cy: 0, zLift: 0 };
        const zUpQuat = BABYLON.Quaternion.RotationAxis(BABYLON.Axis.X, Math.PI / 2);

        const overlayRoots = result.meshes.filter(m => !m.parent);
        overlayRoots.forEach(n => {
            if (scaleFactor !== 1) n.scaling.setAll(scaleFactor);
            if (n.rotationQuaternion == null) {
                n.rotationQuaternion = (n.rotation && n.rotation.length)
                    ? BABYLON.Quaternion.FromEulerVector(n.rotation)
                    : BABYLON.Quaternion.Identity();
            }
            n.rotationQuaternion = zUpQuat.multiply(n.rotationQuaternion);
            n.position.x -= offset.cx;
            n.position.y -= offset.cy;
            n.position.z += offset.zLift;
        });
        result.meshes.forEach(m => m.computeWorldMatrix(true));

        const isMultiBody = overlayKey === 'GENERAL__multi_body';
        meshes.forEach(mesh => {
            const mat = new BABYLON.PBRMaterial(`dfm_${overlayKey}_mat`, scene);
            mat.metallic  = 0;
            mat.roughness = 0.8;
            if (isMultiBody) {
                // Multi-body overlay: honour per-body vertex colours baked into the GLB.
                mat.backFaceCulling = false; // both faces needed for vertex-colored body mesh
                mat.useVertexColors = true;
                mat.albedoColor     = new BABYLON.Color3(1, 1, 1); // multiply with vertex colour
                mat.alpha           = 0.85;
                mat.emissiveColor   = new BABYLON.Color3(0, 0, 0);
                mat.zOffset         = 0; // bodies sit on the model surface — no depth bias needed
            } else {
                mat.backFaceCulling = true; // hide back faces to reduce noisy internal geometry
                // Process-specific DFM issue: look up per-category style, fall back to red.
                mat.useVertexColors = false;
                const categorySuffix = overlayKey.includes('__')
                    ? overlayKey.split('__').slice(1).join('__')
                    : overlayKey;
                const style = OVERLAY_STYLES[categorySuffix];
                if (style) {
                    mat.albedoColor  = style.albedo();
                    mat.alpha        = style.alpha;
                    mat.emissiveColor = style.emissive();
                    mat.zOffset      = style.zOffset;
                    if (categorySuffix === 'overhang_support' || categorySuffix === 'support_required') {
                        mat.transparencyMode = BABYLON.Material.MATERIAL_ALPHABLEND;
                        mat.needDepthPrePass = false;
                    }
                } else {
                    mat.albedoColor  = new BABYLON.Color3(0.95, 0.10, 0.05); // red
                    mat.alpha        = 0.55;
                    mat.emissiveColor = new BABYLON.Color3(0.25, 0.00, 0.00); // faint red glow
                    mat.zOffset      = -2; // depth bias: overlay wins depth test against coplanar main mesh
                }
            }
            mesh.material = mat;
            mesh.isPickable = false;
        });

        overlayMeshes[slot].set(overlayKey, meshes);
        // Apply the most-recent intended visibility (may have been toggled off while loading).
        const shouldShow = overlayIntendedVisible[slot]?.get(overlayKey) ?? true;
        if (!shouldShow) meshes.forEach(m => { m.isVisible = false; });
    } catch (err) {
        console.error(`[BabylonViewer] Failed to load overlay ${overlayKey}:`, err);
    } finally {
        overlayLoading[slot].delete(overlayKey);
    }
}

/**
 * Removes all DFM overlay meshes for the given canvas.
 * @param {string} canvasId
 */
export function clearDfmOverlays(canvasId, partKey) {
    const slot = partKey ? `${canvasId}::${partKey}` : canvasId;
    const map = overlayMeshes[slot];
    if (map) {
        map.forEach(meshes => meshes.forEach(m => {
            if (!m || (typeof m.isDisposed === 'function' && m.isDisposed())) return;
            try {
                m.dispose();
            } catch (error) {
                debugLog('clearDfmOverlays dispose skipped', error);
            }
        }));
        map.clear();
        delete overlayMeshes[slot];
    }
    if (overlayLoading[slot]) { overlayLoading[slot].clear(); delete overlayLoading[slot]; }
    if (overlayIntendedVisible[slot]) { overlayIntendedVisible[slot].clear(); delete overlayIntendedVisible[slot]; }
}

// ── setSectionPlane ──────────────────────────────────────────────────────────

function disposeSectionVisuals(canvasId, scene = scenes[canvasId]) {
    if (sectionEdgeMeshes[canvasId]) {
        sectionEdgeMeshes[canvasId].dispose();
        sectionEdgeMeshes[canvasId] = null;
    }
    if (sectionHatchMeshes[canvasId]) {
        sectionHatchMeshes[canvasId].dispose();
        sectionHatchMeshes[canvasId] = null;
    }
    if (sectionFillMeshes[canvasId]) {
        sectionFillMeshes[canvasId].dispose();
        sectionFillMeshes[canvasId] = null;
    }
    if (sectionObservers[canvasId]) {
        if (scene) scene.onBeforeRenderObservable.remove(sectionObservers[canvasId]);
        sectionObservers[canvasId] = null;
    }
    _disposeSectionGhosts(canvasId);
    _sectionRebuildPending[canvasId] = false;
}

function configureSectionLineMesh(mesh, color) {
    if (!mesh) return mesh;
    mesh.color = toColor3(color);
    mesh.renderingGroupId = CONFIG.SECTION.renderingGroupId;
    mesh.alwaysSelectAsActiveMesh = true;

    if (mesh.material) {
        mesh.material.disableClipPlanes = true;
        mesh.material.disableDepthWrite = false;
        mesh.material.disableDepthTest = false;
        mesh.material.forceDepthWrite = true;
        mesh.material.needDepthPrePass = false;
        mesh.material.zOffset = CONFIG.SECTION.zOffset;
    }

    return markAnalysisHelperMesh(mesh);
}

function disableSectionClippingForMesh(mesh) {
    if (mesh?.material) {
        mesh.material.disableClipPlanes = true;
    }
}

function forEachMeshMaterial(mesh, callback) {
    const material = mesh?.material;
    if (!material) return;

    callback(material);
    if (Array.isArray(material.subMaterials)) {
        material.subMaterials.forEach(subMaterial => {
            if (subMaterial) callback(subMaterial);
        });
    }
}

function clearSectionClippingForModelMeshes(canvasId, scene) {
    if (!scene?.meshes) return;

    for (const mesh of scene.meshes) {
        if (!isModelMeshForAnalysis(mesh, canvasId)) continue;
        forEachMeshMaterial(mesh, material => {
            if (material._malievSectionClip === true) {
                material.clipPlane = null;
                material._malievSectionClip = false;
            }
        });
    }
    sectionClipPlanes[canvasId] = null;
}

function applySectionClippingToModelMeshes(canvasId, scene, plane) {
    if (!scene?.meshes || !plane) return;

    for (const mesh of scene.meshes) {
        if (!isModelMeshForAnalysis(mesh, canvasId)) continue;
        forEachMeshMaterial(mesh, material => {
            material.clipPlane = plane;
            material.disableClipPlanes = false;
            material._malievSectionClip = true;
        });
    }
    sectionClipPlanes[canvasId] = plane;
}

function disableSectionClippingForSystemMeshes(canvasId, scene) {
    if (!scene?.meshes) return;

    for (const mesh of scene.meshes) {
        if (!mesh?.material) continue;
        if (isModelMeshForAnalysis(mesh, canvasId)) continue;
        disableSectionClippingForMesh(mesh);
    }
}

function scheduleSectionRebuild(canvasId, scene, planeNormal, planeD) {
    if (_sectionRebuildPending[canvasId]) return;
    _sectionRebuildPending[canvasId] = true;
    requestAnimationFrame(() => {
        _sectionRebuildPending[canvasId] = false;
        if (scenes[canvasId] !== scene || !sectionClipPlanes[canvasId]) return;
        _rebuildSectionFill(canvasId, scene, planeNormal, planeD);
        _rebuildSectionEdges(canvasId, scene, planeNormal, planeD);
        _rebuildSectionHatch(canvasId, scene, planeNormal, planeD);
    });
}

/**
 * Sets or clears the scene clipping plane and redraws the cut-edge lines.
 * offsetMm is measured from the model centre along the chosen axis (so 0 = centre).
 * @param {string}  canvasId
 * @param {boolean} enabled
 * @param {string}  axis      "x" | "y" | "z"
 * @param {number}  offsetMm  mm from model centre (positive = toward max extent)
 * @param {boolean} inverted  flip which half is kept
 */
export function setSectionPlane(canvasId, enabled, axis, offsetMm, inverted) {
    const scene = scenes[canvasId];
    if (!scene) return;

    disposeSectionVisuals(canvasId, scene);
    clearSectionClippingForModelMeshes(canvasId, scene);
    scene.clipPlane = null;

    if (!enabled) {
        return;
    }

    ensureModelMeshesTagged(canvasId, scene);

    // World coordinate of the clipping plane along the chosen axis.
    // Model centre along each axis (from meshCenters, which stores the post-centering centre):
    //   X, Y ≈ 0 (model is centred at world origin in X/Y)
    //   Z ≈ boundingBoxZ/2 (build-plate is at Z=0, model top at Z=height)
    const scaleFactor = modelScaleFactors[canvasId] ?? 1;
    const mc = meshCenters[canvasId] ?? { x: 0, y: 0, z: 0 };
    const axisCenter = axis === 'x' ? mc.x : (axis === 'y' ? mc.y : mc.z);
    const worldOffset = axisCenter + offsetMm * scaleFactor;

    const defaultSign = axis === 'x' || axis === 'y' ? -1 : 1;
    const sign = inverted ? -defaultSign : defaultSign;
    let nx = 0, ny = 0, nz = 0;
    switch (axis) {
        case 'x': nx = sign; break;
        case 'y': ny = sign; break;
        case 'z': nz = sign; break;
        default:  nx = sign; break;
    }
    const d = -(nx * worldOffset + ny * worldOffset + nz * worldOffset);
    const plane = new BABYLON.Plane(nx, ny, nz, d);
    applySectionClippingToModelMeshes(canvasId, scene, plane);
    disableSectionClippingForSystemMeshes(canvasId, scene);

    // Create ghost clones for the hidden half (xray silhouette)
    _createSectionGhosts(canvasId, scene, nx, ny, nz, d);

    scheduleSectionRebuild(canvasId, scene, new BABYLON.Vector3(nx, ny, nz), d);
}

/**
 * Computes triangle/plane intersection segments for every visible non-overlay mesh,
 * builds a LinesMesh coloured like the model edges, and stores it in sectionEdgeMeshes.
 * @param {string}               canvasId
 * @param {BABYLON.Scene}        scene
 * @param {BABYLON.Vector3}      planeNormal  world-space normal (unit axis vector)
 * @param {number}               planeD       plane constant (n·p + d = 0)
 */
function _rebuildSectionEdges(canvasId, scene, planeNormal, planeD) {
    if (sectionEdgeMeshes[canvasId]) {
        sectionEdgeMeshes[canvasId].dispose();
        sectionEdgeMeshes[canvasId] = null;
    }

    const lines = [];

    for (const mesh of scene.meshes) {
        if (!mesh.isVisible || !isModelMeshForAnalysis(mesh, canvasId)) continue;

        const positions = mesh.getVerticesData(BABYLON.VertexBuffer.PositionKind);
        const indices = mesh.getIndices();
        if (!positions || !indices || indices.length === 0) continue;

        const worldMatrix = mesh.getWorldMatrix();

        for (let i = 0; i < indices.length; i += 3) {
            const i0 = indices[i], i1 = indices[i + 1], i2 = indices[i + 2];

            // Transform to world space
            const wv0 = BABYLON.Vector3.TransformCoordinates(
                new BABYLON.Vector3(positions[i0 * 3], positions[i0 * 3 + 1], positions[i0 * 3 + 2]),
                worldMatrix);
            const wv1 = BABYLON.Vector3.TransformCoordinates(
                new BABYLON.Vector3(positions[i1 * 3], positions[i1 * 3 + 1], positions[i1 * 3 + 2]),
                worldMatrix);
            const wv2 = BABYLON.Vector3.TransformCoordinates(
                new BABYLON.Vector3(positions[i2 * 3], positions[i2 * 3 + 1], positions[i2 * 3 + 2]),
                worldMatrix);

            // Signed distances to plane
            const d0 = BABYLON.Vector3.Dot(planeNormal, wv0) + planeD;
            const d1 = BABYLON.Vector3.Dot(planeNormal, wv1) + planeD;
            const d2 = BABYLON.Vector3.Dot(planeNormal, wv2) + planeD;

            // Collect edge crossings (sign change = the edge crosses the plane)
            const pts = [];
            const edges = [[wv0, wv1, d0, d1], [wv1, wv2, d1, d2], [wv2, wv0, d2, d0]];
            for (const [va, vb, da, db] of edges) {
                if (da * db < 0) {
                    const t = -da / (db - da);
                    pts.push(BABYLON.Vector3.Lerp(va, vb, t));
                }
            }

            if (pts.length === 2) {
                lines.push([pts[0], pts[1]]);
            }
        }
    }

    if (lines.length === 0) return;

    const linesMesh = BABYLON.MeshBuilder.CreateLineSystem(
        `__section_edges_${canvasId}__`,
        { lines, updatable: false },
        scene
    );
    configureSectionLineMesh(linesMesh, CONFIG.SECTION.cutEdgeColor);
    sectionEdgeMeshes[canvasId] = linesMesh;
}

function collectSectionSegments(canvasId, scene, planeNormal, planeD) {
    const segments = [];

    for (const mesh of scene.meshes) {
        if (!mesh.isVisible || !isModelMeshForAnalysis(mesh, canvasId)) continue;

        const positions = mesh.getVerticesData(BABYLON.VertexBuffer.PositionKind);
        const indices = mesh.getIndices();
        if (!positions || !indices || indices.length === 0) continue;

        const worldMatrix = mesh.getWorldMatrix();

        for (let i = 0; i < indices.length; i += 3) {
            const i0 = indices[i], i1 = indices[i + 1], i2 = indices[i + 2];
            const wv0 = BABYLON.Vector3.TransformCoordinates(
                new BABYLON.Vector3(positions[i0 * 3], positions[i0 * 3 + 1], positions[i0 * 3 + 2]), worldMatrix);
            const wv1 = BABYLON.Vector3.TransformCoordinates(
                new BABYLON.Vector3(positions[i1 * 3], positions[i1 * 3 + 1], positions[i1 * 3 + 2]), worldMatrix);
            const wv2 = BABYLON.Vector3.TransformCoordinates(
                new BABYLON.Vector3(positions[i2 * 3], positions[i2 * 3 + 1], positions[i2 * 3 + 2]), worldMatrix);

            const d0 = BABYLON.Vector3.Dot(planeNormal, wv0) + planeD;
            const d1 = BABYLON.Vector3.Dot(planeNormal, wv1) + planeD;
            const d2 = BABYLON.Vector3.Dot(planeNormal, wv2) + planeD;

            const pts = [];
            const edges = [[wv0, wv1, d0, d1], [wv1, wv2, d1, d2], [wv2, wv0, d2, d0]];
            for (const [va, vb, da, db] of edges) {
                if (da * db < 0) {
                    const t = -da / (db - da);
                    pts.push(BABYLON.Vector3.Lerp(va, vb, t));
                }
            }
            if (pts.length === 2) segments.push([pts[0], pts[1]]);
        }
    }

    return segments;
}

function getSectionPlaneAxes(planeNormal) {
    let uAxis, vAxis;
    const absX = Math.abs(planeNormal.x), absY = Math.abs(planeNormal.y), absZ = Math.abs(planeNormal.z);
    if (absX <= absY && absX <= absZ) {
        uAxis = new BABYLON.Vector3(1, 0, 0);
    } else if (absY <= absZ) {
        uAxis = new BABYLON.Vector3(0, 1, 0);
    } else {
        uAxis = new BABYLON.Vector3(0, 0, 1);
    }
    vAxis = BABYLON.Vector3.Cross(planeNormal, uAxis);
    vAxis.normalize();
    uAxis = BABYLON.Vector3.Cross(vAxis, planeNormal);
    uAxis.normalize();
    return { uAxis, vAxis };
}

function pointOnSectionPlane(u, v, uAxis, vAxis, planeNormal, planeD) {
    return new BABYLON.Vector3(
        u * uAxis.x + v * vAxis.x - planeD * planeNormal.x,
        u * uAxis.y + v * vAxis.y - planeD * planeNormal.y,
        u * uAxis.z + v * vAxis.z - planeD * planeNormal.z
    );
}

function _rebuildSectionFill(canvasId, scene, planeNormal, planeD) {
    if (sectionFillMeshes[canvasId]) {
        sectionFillMeshes[canvasId].dispose();
        sectionFillMeshes[canvasId] = null;
    }

    const allSegments = collectSectionSegments(canvasId, scene, planeNormal, planeD);
    if (allSegments.length === 0) return;

    const { uAxis, vAxis } = getSectionPlaneAxes(planeNormal);
    const scaleFactor = modelScaleFactors[canvasId] ?? 1;
    const planeLift = planeNormal.scale(CONFIG.SECTION.planeLiftMm * 0.2 * scaleFactor);
    const segments2D = [];
    let minV = Infinity;
    let maxV = -Infinity;

    for (const [p0, p1] of allSegments) {
        const u0 = BABYLON.Vector3.Dot(p0, uAxis);
        const v0 = BABYLON.Vector3.Dot(p0, vAxis);
        const u1 = BABYLON.Vector3.Dot(p1, uAxis);
        const v1 = BABYLON.Vector3.Dot(p1, vAxis);
        segments2D.push({ u0, v0, u1, v1 });
        minV = Math.min(minV, v0, v1);
        maxV = Math.max(maxV, v0, v1);
    }

    if (!Number.isFinite(minV) || !Number.isFinite(maxV)) return;

    const spanV = Math.max(maxV - minV, CONFIG.SECTION.minHatchSpacing);
    const fillStep = Math.max(Math.min(spanV / 120, 1.1 * scaleFactor), 0.35 * scaleFactor);
    const halfBand = fillStep * 0.48;
    const epsilon = 1e-5;
    const positions = [];
    const indices = [];

    for (let v = minV + fillStep / 2; v <= maxV - fillStep / 2 + epsilon; v += fillStep) {
        const intersections = [];
        for (const segment of segments2D) {
            const vMin = Math.min(segment.v0, segment.v1);
            const vMax = Math.max(segment.v0, segment.v1);
            if (v < vMin - epsilon || v > vMax + epsilon) continue;
            const dv = segment.v1 - segment.v0;
            if (Math.abs(dv) <= epsilon) continue;
            const t = (v - segment.v0) / dv;
            if (t < -epsilon || t > 1 + epsilon) continue;
            intersections.push(segment.u0 + t * (segment.u1 - segment.u0));
        }

        intersections.sort((a, b) => a - b);
        const unique = [];
        for (const value of intersections) {
            if (unique.length === 0 || Math.abs(value - unique[unique.length - 1]) > epsilon * 10) {
                unique.push(value);
            }
        }

        for (let i = 0; i < unique.length - 1; i += 2) {
            const u0 = unique[i];
            const u1 = unique[i + 1];
            if (!Number.isFinite(u0) || !Number.isFinite(u1) || Math.abs(u1 - u0) <= epsilon) continue;
            const v0 = Math.max(minV, v - halfBand);
            const v1 = Math.min(maxV, v + halfBand);
            const p0 = pointOnSectionPlane(u0, v0, uAxis, vAxis, planeNormal, planeD).addInPlace(planeLift);
            const p1 = pointOnSectionPlane(u1, v0, uAxis, vAxis, planeNormal, planeD).addInPlace(planeLift);
            const p2 = pointOnSectionPlane(u1, v1, uAxis, vAxis, planeNormal, planeD).addInPlace(planeLift);
            const p3 = pointOnSectionPlane(u0, v1, uAxis, vAxis, planeNormal, planeD).addInPlace(planeLift);
            const vertexOffset = positions.length / 3;
            positions.push(
                p0.x, p0.y, p0.z,
                p1.x, p1.y, p1.z,
                p2.x, p2.y, p2.z,
                p3.x, p3.y, p3.z);
            indices.push(vertexOffset, vertexOffset + 1, vertexOffset + 2, vertexOffset, vertexOffset + 2, vertexOffset + 3);
        }
    }

    if (positions.length === 0 || indices.length === 0) return;

    const fillMesh = new BABYLON.Mesh(`__section_fill_${canvasId}__`, scene);
    const vertexData = new BABYLON.VertexData();
    vertexData.positions = positions;
    vertexData.indices = indices;
    vertexData.applyToMesh(fillMesh);

    const fillMat = new BABYLON.StandardMaterial(`__section_fill_mat_${canvasId}__`, scene);
    fillMat.diffuseColor = toColor3(CONFIG.SECTION.fillColor);
    fillMat.emissiveColor = toColor3(CONFIG.SECTION.fillColor);
    fillMat.ambientColor = toColor3(CONFIG.SECTION.fillColor);
    fillMat.specularColor = new BABYLON.Color3(0, 0, 0);
    fillMat.alpha = CONFIG.SECTION.fillAlpha;
    fillMat.backFaceCulling = false;
    fillMat.disableLighting = true;
    fillMat.disableClipPlanes = true;
    fillMat.disableDepthWrite = false;
    fillMat.disableDepthTest = false;
    fillMat.forceDepthWrite = true;
    fillMat.needDepthPrePass = false;
    fillMat.zOffset = CONFIG.SECTION.zOffset - 1;
    fillMesh.material = fillMat;
    fillMesh.renderingGroupId = CONFIG.SECTION.renderingGroupId;
    fillMesh.alwaysSelectAsActiveMesh = true;
    sectionFillMeshes[canvasId] = markAnalysisHelperMesh(fillMesh);
    sectionFillMeshes[canvasId].metadata = {
        ...(sectionFillMeshes[canvasId].metadata ?? {}),
        sectionFillMode: 'scanline-bands',
    };
}

/**
 * Draws parallel diagonal hatch lines clipped to the section polygon.
 * This creates the traditional engineering cross-section fill pattern.
 */
function _rebuildSectionHatch(canvasId, scene, planeNormal, planeD) {
    if (sectionHatchMeshes[canvasId]) {
        sectionHatchMeshes[canvasId].dispose();
        sectionHatchMeshes[canvasId] = null;
    }

    // Collect all intersection points as line segments
    const allSegments = [];
    for (const mesh of scene.meshes) {
        if (!mesh.isVisible || !isModelMeshForAnalysis(mesh, canvasId)) continue;

        const positions = mesh.getVerticesData(BABYLON.VertexBuffer.PositionKind);
        const indices = mesh.getIndices();
        if (!positions || !indices || indices.length === 0) continue;

        const worldMatrix = mesh.getWorldMatrix();

        for (let i = 0; i < indices.length; i += 3) {
            const i0 = indices[i], i1 = indices[i + 1], i2 = indices[i + 2];
            const wv0 = BABYLON.Vector3.TransformCoordinates(
                new BABYLON.Vector3(positions[i0 * 3], positions[i0 * 3 + 1], positions[i0 * 3 + 2]), worldMatrix);
            const wv1 = BABYLON.Vector3.TransformCoordinates(
                new BABYLON.Vector3(positions[i1 * 3], positions[i1 * 3 + 1], positions[i1 * 3 + 2]), worldMatrix);
            const wv2 = BABYLON.Vector3.TransformCoordinates(
                new BABYLON.Vector3(positions[i2 * 3], positions[i2 * 3 + 1], positions[i2 * 3 + 2]), worldMatrix);

            const d0 = BABYLON.Vector3.Dot(planeNormal, wv0) + planeD;
            const d1 = BABYLON.Vector3.Dot(planeNormal, wv1) + planeD;
            const d2 = BABYLON.Vector3.Dot(planeNormal, wv2) + planeD;

            const pts = [];
            const edges = [[wv0, wv1, d0, d1], [wv1, wv2, d1, d2], [wv2, wv0, d2, d0]];
            for (const [va, vb, da, db] of edges) {
                if (da * db < 0) {
                    const t = -da / (db - da);
                    pts.push(BABYLON.Vector3.Lerp(va, vb, t));
                }
            }
            if (pts.length === 2) {
                allSegments.push([pts[0], pts[1]]);
            }
        }
    }

    if (allSegments.length === 0) return;

    // Project all intersection points to 2D on the section plane.
    const { uAxis, vAxis } = getSectionPlaneAxes(planeNormal);

    // Compute 2D bounding box of all intersection points
    let minU = Infinity, maxU = -Infinity, minV = Infinity, maxV = -Infinity;
    const points2D = [];
    for (const seg of allSegments) {
        for (const p of seg) {
            const pu = BABYLON.Vector3.Dot(p, uAxis);
            const pv = BABYLON.Vector3.Dot(p, vAxis);
            minU = Math.min(minU, pu);
            maxU = Math.max(maxU, pu);
            minV = Math.min(minV, pv);
            maxV = Math.max(maxV, pv);
            points2D.push({ u: pu, v: pv });
        }
    }

    // Generate diagonal cross-hatch lines across the actual projected contour,
    // not around world zero. Model Z is intentionally lifted above the floor.
    const hatchSpacing = Math.max(
        CONFIG.SECTION.hatchSpacingMm * (modelScaleFactors[canvasId] ?? 1),
        CONFIG.SECTION.minHatchSpacing);
    const hatchAngles = [Math.PI / 4];
    const hatchLines = [];

    const planeLift = planeNormal.scale(CONFIG.SECTION.planeLiftMm * (modelScaleFactors[canvasId] ?? 1));
    const hatchEpsilon = 1e-5;

    for (const hatchAngle of hatchAngles) {
        const cosA = Math.cos(hatchAngle);
        const sinA = Math.sin(hatchAngle);
        const perpU = -sinA;
        const perpV = cosA;

        let minOffset = Infinity;
        let maxOffset = -Infinity;
        for (const point of points2D) {
            const value = perpU * point.u + perpV * point.v;
            minOffset = Math.min(minOffset, value);
            maxOffset = Math.max(maxOffset, value);
        }

        const startOffset = Math.floor((minOffset - hatchSpacing) / hatchSpacing) * hatchSpacing;
        const endOffset = Math.ceil((maxOffset + hatchSpacing) / hatchSpacing) * hatchSpacing;

        for (let offset = startOffset; offset <= endOffset; offset += hatchSpacing) {
            const intersectPts = [];
            for (const seg of allSegments) {
                const u0 = BABYLON.Vector3.Dot(seg[0], uAxis);
                const v0 = BABYLON.Vector3.Dot(seg[0], vAxis);
                const u1 = BABYLON.Vector3.Dot(seg[1], uAxis);
                const v1 = BABYLON.Vector3.Dot(seg[1], vAxis);

                const d0 = perpU * u0 + perpV * v0 - offset;
                const d1 = perpU * u1 + perpV * v1 - offset;
                if (Math.abs(d0) <= hatchEpsilon && Math.abs(d1) <= hatchEpsilon) continue;

                if ((d0 < -hatchEpsilon && d1 > hatchEpsilon)
                    || (d0 > hatchEpsilon && d1 < -hatchEpsilon)
                    || Math.abs(d0) <= hatchEpsilon
                    || Math.abs(d1) <= hatchEpsilon) {
                    const denominator = d1 - d0;
                    if (Math.abs(denominator) <= hatchEpsilon) continue;
                    const t = Math.max(0, Math.min(1, -d0 / denominator));
                    const hu = u0 + t * (u1 - u0);
                    const hv = v0 + t * (v1 - v0);
                    intersectPts.push({ u: hu, v: hv, s: cosA * hu + sinA * hv });
                }
            }

            if (intersectPts.length >= 2) {
                intersectPts.sort((a, b) => a.s - b.s);
                const uniquePts = [];
                for (const point of intersectPts) {
                    if (uniquePts.length === 0 || Math.abs(point.s - uniquePts[uniquePts.length - 1].s) > hatchEpsilon * 10) {
                        uniquePts.push(point);
                    }
                }

                for (let i = 0; i < uniquePts.length - 1; i += 2) {
                    const p1 = uniquePts[i];
                    const p2 = uniquePts[i + 1];
                    const pt1 = new BABYLON.Vector3(
                        p1.u * uAxis.x + p1.v * vAxis.x - planeD * planeNormal.x,
                        p1.u * uAxis.y + p1.v * vAxis.y - planeD * planeNormal.y,
                        p1.u * uAxis.z + p1.v * vAxis.z - planeD * planeNormal.z
                    ).addInPlace(planeLift);
                    const pt2 = new BABYLON.Vector3(
                        p2.u * uAxis.x + p2.v * vAxis.x - planeD * planeNormal.x,
                        p2.u * uAxis.y + p2.v * vAxis.y - planeD * planeNormal.y,
                        p2.u * uAxis.z + p2.v * vAxis.z - planeD * planeNormal.z
                    ).addInPlace(planeLift);
                    hatchLines.push([pt1, pt2]);
                }
            }
        }
    }

    if (hatchLines.length === 0) return;

    const hatchWidth = Math.max(
        CONFIG.SECTION.hatchWidthMm * (modelScaleFactors[canvasId] ?? 1),
        0.02);
    const hatchLift = planeNormal.scale(CONFIG.SECTION.planeLiftMm * 0.8 * (modelScaleFactors[canvasId] ?? 1));
    const stripPaths = [];
    const positions = [];
    const indices = [];

    for (const [baseStart, baseEnd] of hatchLines) {
        const direction = baseEnd.subtract(baseStart);
        if (direction.length() <= 1e-6) continue;
        direction.normalize();

        const widthAxis = BABYLON.Vector3.Cross(planeNormal, direction);
        if (widthAxis.length() <= 1e-6) continue;
        widthAxis.normalize();
        const halfWidth = widthAxis.scale(hatchWidth / 2);

        const start = baseStart.add(hatchLift);
        const end = baseEnd.add(hatchLift);
        const p0 = start.add(halfWidth);
        const p1 = start.subtract(halfWidth);
        const p2 = end.subtract(halfWidth);
        const p3 = end.add(halfWidth);
        const vertexOffset = positions.length / 3;
        positions.push(
            p0.x, p0.y, p0.z,
            p1.x, p1.y, p1.z,
            p2.x, p2.y, p2.z,
            p3.x, p3.y, p3.z);
        indices.push(
            vertexOffset, vertexOffset + 1, vertexOffset + 2,
            vertexOffset, vertexOffset + 2, vertexOffset + 3);
        stripPaths.push([p0, p1, p2, p3]);
    }

    if (positions.length === 0) return;

    const hatchMesh = new BABYLON.Mesh(`__section_hatch_${canvasId}__`, scene);
    const vertexData = new BABYLON.VertexData();
    vertexData.positions = positions;
    vertexData.indices = indices;
    vertexData.applyToMesh(hatchMesh);
    hatchMesh.pathArray = stripPaths;

    const hatchMat = new BABYLON.StandardMaterial(`__section_hatch_mat_${canvasId}__`, scene);
    hatchMat.diffuseColor = toColor3(CONFIG.SECTION.hatchColor);
    hatchMat.emissiveColor = toColor3(CONFIG.SECTION.hatchColor);
    hatchMat.ambientColor = toColor3(CONFIG.SECTION.hatchColor);
    hatchMat.specularColor = new BABYLON.Color3(0, 0, 0);
    hatchMat.backFaceCulling = false;
    hatchMat.disableLighting = true;
    hatchMesh.material = hatchMat;

    configureSectionLineMesh(hatchMesh, CONFIG.SECTION.hatchColor);
    sectionHatchMeshes[canvasId] = hatchMesh;
}

// ── rotateModel ─────────────────────────────────────────────────────────────────

export function rotateModel(canvasId, degrees, smooth = true) {
    const scene = scenes[canvasId];
    if (!scene) return;
    const cam = mainCameras[canvasId];
    if (!cam || !(cam instanceof BABYLON.ArcRotateCamera)) return;

    // Kill auto-rotation instantly
    autoSpeedCurrent[canvasId] = 0;
    autoSpeedTarget[canvasId]  = SPEED_STOP;
    animStates[canvasId]       = 'interacting';

    const rad = degrees * Math.PI / 180;

    // Use smooth animation for 90-degree rotations (or multiples thereof)
    if (smooth && Math.abs(degrees % 90) < 0.001) {
        animateCameraAlpha(cam, rad);
    } else {
        // Immediate rotation for non-90-degree angles
        cam.alpha += rad;
    }
}

// ── zoomTo ────────────────────────────────────────────────────────────────────────

/**
 * Smoothly zooms the camera to a target zoom factor.
 * @param {string} canvasId - Canvas identifier
 * @param {number} zoomFactor - Target zoom factor (1.0 = fit to view, <1 = zoomed in, >1 = zoomed out)
 * @param {boolean} smooth - Whether to animate the transition (default: true)
 */
export function zoomTo(canvasId, zoomFactor, smooth = true) {
    const cam = mainCameras[canvasId];
    const scene = scenes[canvasId];
    if (!cam || !scene) return;

    // Kill auto-rotation instantly
    autoSpeedCurrent[canvasId] = 0;
    autoSpeedTarget[canvasId]  = SPEED_STOP;
    animStates[canvasId]       = 'interacting';

    const initialRadius = fitRadiusMap[canvasId];
    if (!initialRadius) return;

    if (cameraProjection[canvasId] === 'orthographic') {
        // Orthographic mode: animate the zoom factor
        const currentZoomFactor = orthoZoomFactors[canvasId] || 1.0;
        const targetZoomFactor = Math.max(0.01, Math.min(100, zoomFactor)); // Clamp between 1% and 100x

        if (smooth && currentZoomFactor !== targetZoomFactor) {
            const duration = CONFIG.CAMERA_TRANSITION_DURATION * 1000;
            const startZoom = currentZoomFactor;
            const startTime = performance.now();

            const anim = () => {
                const elapsed = performance.now() - startTime;
                const progress = Math.min(elapsed / duration, 1);
                const eased = easeInOutCubic(progress);

                const newZoomFactor = startZoom + (targetZoomFactor - startZoom) * eased;
                orthoZoomFactors[canvasId] = newZoomFactor;

                // Update ortho bounds
                const engine = engines[canvasId];
                if (engine) {
                    const asp = engine.getAspectRatio(cam);
                    const h = initialRadius * newZoomFactor * ORTHO_RADIUS_FACTOR;
                    cam.orthoLeft   = -h * asp;
                    cam.orthoRight  =  h * asp;
                    cam.orthoTop    =  h;
                    cam.orthoBottom = -h;
                }

                if (progress < 1) {
                    requestAnimationFrame(anim);
                }
            };
            anim();
        } else {
            // Immediate zoom
            orthoZoomFactors[canvasId] = targetZoomFactor;
            const engine = engines[canvasId];
            if (engine) {
                const asp = engine.getAspectRatio(cam);
                const h = initialRadius * targetZoomFactor * ORTHO_RADIUS_FACTOR;
                cam.orthoLeft   = -h * asp;
                cam.orthoRight  =  h * asp;
                cam.orthoTop    =  h;
                cam.orthoBottom = -h;
            }
        }
    } else {
        // Perspective mode: animate the camera radius
        const targetRadius = initialRadius * Math.max(0.01, Math.min(100, zoomFactor));

        if (smooth && Math.abs(cam.radius - targetRadius) > 0.001) {
            animateCameraRadius(cam, targetRadius);
        } else {
            cam.radius = targetRadius;
        }
    }
}

/**
 * Resets zoom to fit the model in view (zoomFactor = 1.0).
 * @param {string} canvasId - Canvas identifier
 * @param {boolean} smooth - Whether to animate the transition (default: true)
 */
export function zoomToFit(canvasId, smooth = true) {
    zoomTo(canvasId, 1.0, smooth);
}

// ── dispose ───────────────────────────────────────────────────────────────────

export function dispose(canvasId) {
    loadGenerations[canvasId] = (loadGenerations[canvasId] || 0) + 1;

    const engine = engines[canvasId];
    if (engine?._resizeHandler) window.removeEventListener('resize', engine._resizeHandler);
    try { engine?.stopRenderLoop(); } catch (_) {}

    clearTurningAxis(canvasId);
    if (resizeObservers[canvasId]) { resizeObservers[canvasId].disconnect(); delete resizeObservers[canvasId]; }
    if (axisGizmoLayer[canvasId])  { try { axisGizmoLayer[canvasId].dispose(); } catch (_) {} delete axisGizmoLayer[canvasId]; }
    if (axisLabelDivs[canvasId])   { axisLabelDivs[canvasId].forEach(({ div }) => div.remove()); delete axisLabelDivs[canvasId]; }

    const canvas = document.getElementById(canvasId);
    if (canvas) {
        if (axisMouseHandlers[canvasId])              canvas.removeEventListener('mousemove',  axisMouseHandlers[canvasId]);
        if (axisMouseHandlers[canvasId + '_leave'])   canvas.removeEventListener('mouseleave', axisMouseHandlers[canvasId + '_leave']);
    }
    delete axisMouseHandlers[canvasId];
    delete axisMouseHandlers[canvasId + '_leave'];

    // Clean up custom right-click pan handlers
    const panH = panHandlers[canvasId];
    if (panH && canvas) {
        canvas.removeEventListener('pointerdown',  panH.down);
        canvas.removeEventListener('pointermove',  panH.move);
        canvas.removeEventListener('pointerup',    panH.up);
        canvas.removeEventListener('contextmenu',  panH.ctx);
    }
    delete panHandlers[canvasId];
    delete panStates[canvasId];

    // Clean up middle-mouse zoom handlers
    const midH = middleZoomHandlers[canvasId];
    if (midH && canvas) {
        canvas.removeEventListener('pointerdown',  midH.down);
        canvas.removeEventListener('pointermove',  midH.move);
        canvas.removeEventListener('pointerup',    midH.up);
        canvas.removeEventListener('pointerleave', midH.leave);
    }
    delete middleZoomHandlers[canvasId];

    // Clean up flipped triangle materials
    if (flippedTriangleMaterials[canvasId]) {
        Object.entries(flippedTriangleMaterials[canvasId]).forEach(([meshId, data]) => {
            if (data.material) data.material.dispose();
            if (data.observer && scenes[canvasId]) scenes[canvasId].onBeforeRenderObservable.remove(data.observer);
        });
        delete flippedTriangleMaterials[canvasId];
    }

    // Clean up measure tool
    const measureState = measureStates[canvasId];
    if (measureState) {
        if (measureState.observer && scenes[canvasId]) {
            scenes[canvasId].onPointerObservable.remove(measureState.observer);
        }
        if (measureState.labelObserver && scenes[canvasId]) {
            scenes[canvasId].onBeforeRenderObservable.remove(measureState.labelObserver);
        }
        measureState.lines.forEach(mesh => { try { mesh.dispose(); } catch (_) {} });
        measureState.labels.forEach(({ div }) => { try { div.remove(); } catch (_) {} });
        delete measureStates[canvasId];
    }

    // Clean up thickness analysis
    const thicknessState = thicknessStates[canvasId];
    if (thicknessState) {
        if (thicknessState.observer && scenes[canvasId]) {
            scenes[canvasId].onPointerObservable.remove(thicknessState.observer);
        }
        if (thicknessState.line) { try { thicknessState.line.dispose(); } catch (_) {} }
        if (thicknessState.sphere) { try { thicknessState.sphere.dispose(); } catch (_) {} }
        if (thicknessState.label) { try { thicknessState.label.remove(); } catch (_) {} }
        delete thicknessStates[canvasId];
    }

    if (orthoZoomObservers[canvasId]) {
        const cam = mainCameras[canvasId];
        if (cam) cam.onViewMatrixChangedObservable.remove(orthoZoomObservers[canvasId]);
        delete orthoZoomObservers[canvasId];
    }
    _detachEdgeZoomObserver(canvasId);

    clearBoundingBox(canvasId);

    // Clean up body map
    if (perCanvasBodyMap[canvasId]) {
        perCanvasBodyMap[canvasId].forEach(bodyData => {
            if (bodyData.colorMaterial) {
                try { bodyData.colorMaterial.dispose(); } catch (_) {}
            }
        });
        delete perCanvasBodyMap[canvasId];
    }

    // Clean up shadow generator
    if (shadowGenerators[canvasId]) {
        try { shadowGenerators[canvasId].dispose(); } catch (_) {}
        delete shadowGenerators[canvasId];
    }

    disposeSectionVisuals(canvasId, scenes[canvasId]);

    // Clean up realistic material cache
    if (realisticMaterialCache[canvasId]) {
        Object.values(realisticMaterialCache[canvasId]).forEach(mat => {
            try { mat.dispose(); } catch (_) {}
        });
        delete realisticMaterialCache[canvasId];
    }
    delete materialTypes[canvasId];
    delete environmentTextures[canvasId];
    delete originalNormalData[canvasId];
    delete currentRenderModes[canvasId];
    delete customAlbedoColors[canvasId];
    delete realisticConfiguratorStateKeys[canvasId];
    delete perCanvasFinishModifiers[canvasId];
    delete perCanvasSurfaceEffects[canvasId];
    delete perCanvasProcessCodes[canvasId];

    scenes[canvasId]?.dispose();
    engine?.dispose();

    delete engines[canvasId];
    delete scenes[canvasId];
    delete mainCameras[canvasId];
    delete darkModes[canvasId];
    delete modelLoadState[canvasId];
    delete originalMaterials[canvasId];
    delete sceneBoundingBoxes[canvasId];
    delete meshCenters[canvasId];
    delete cameraProjection[canvasId];
    delete edgesEnabled[canvasId];
    delete fitRadiusMap[canvasId];
    delete modelFitRadiusMap[canvasId];
    delete cuttingMatFrameBoundsMap[canvasId];
    delete animStates[canvasId];
    delete autoSpeedCurrent[canvasId];
    delete autoSpeedTarget[canvasId];
    delete analysisModelMeshIds[canvasId];
    delete analysisCameraButtons[canvasId];
    delete localAdvisoryRuns[canvasId];
    terminateLocalAdvisoryWorker(canvasId);
    clearLocalAdvisoryPanel(canvasId);

    // Clean up all per-part overlay slots for this canvas.
    const prefix = `${canvasId}::`;
    [overlayMeshes, overlayLoading, overlayIntendedVisible].forEach(obj => {
        Object.keys(obj).forEach(k => {
            if (k === canvasId || k.startsWith(prefix)) {
                if (obj === overlayMeshes && obj[k] instanceof Map) {
                    obj[k].forEach(meshes => meshes.forEach(m => m.dispose()));
                }
                delete obj[k];
            }
        });
    });
    delete modelScaleFactors[canvasId];
    delete modelCenterOffsets[canvasId];

    delete sectionEdgeMeshes[canvasId];
    delete sectionHatchMeshes[canvasId];
    delete sectionFillMeshes[canvasId];
    delete sectionGhostMeshes[canvasId];
    delete sectionObservers[canvasId];
    delete sectionClipPlanes[canvasId];
    delete _sectionRebuildPending[canvasId];
}

// ── Multi-body support ─────────────────────────────────────────────────────────

/**
 * Assigns distinct colors to each body in a multi-body GLB assembly.
 * @param {string} canvasId
 * @param {Array} bodies - Array of body metadata from SignalR [{ index, name, volumeCm3, colorHex }]
 */
export function setBodies(canvasId, bodies) {
    const scene = scenes[canvasId];
    if (!scene) return;

    const bodyMap = perCanvasBodyMap[canvasId];
    if (!bodyMap) {
        console.warn(`[BabylonViewer] No body map found for canvas ${canvasId}`);
        return;
    }

    // Color palette for bodies (distinct colors for easy visual separation)
    // Colors cycle using modulo for assemblies with >20 bodies
    const palette = CONFIG.MULTI_BODY_PALETTE.map(c => toColor3(c));

    bodies.forEach((body, idx) => {
        if (idx >= bodyMap.size) {
            console.warn(`[BabylonViewer] Body index ${idx} out of range (only ${bodyMap.size} bodies)`);
            return;
        }

        const bodyData = bodyMap.get(idx);
        if (!bodyData) {
            console.warn(`[BabylonViewer] No body data found for index ${idx}`);
            return;
        }

        const color = palette[idx % palette.length];
        const colorMaterial = new BABYLON.PBRMaterial(`body_${idx}_mat`, scene);
        colorMaterial.albedoColor = color;
        colorMaterial.metallic = CONFIG.MATERIAL_MULTI_BODY.metallic;
        colorMaterial.roughness = CONFIG.MATERIAL_MULTI_BODY.roughness;
        colorMaterial.alpha = CONFIG.MATERIAL_MULTI_BODY.alpha;
        colorMaterial.backFaceCulling = false;

        // Share the same material instance across all meshes in this body (no clones).
        // This lets selectBody and clearBodySelection restore color by re-assigning bodyData.colorMaterial.
        bodyData.meshes.forEach(mesh => {
            mesh.material = colorMaterial;
        });

        bodyData.colorMaterial = colorMaterial;
        bodyData.index = idx;
        bodyData.name = body.name;

        debugLog(`[BabylonViewer] Set body ${idx} (${body.name}) to color RGB(${color.r},${color.g},${color.b})`);
    });
}

/**
 * Highlights a single body and dims all other bodies to x-ray mode.
 * @param {string} canvasId
 * @param {number|null} bodyIndex - Index of body to highlight (0-based), or null to clear selection
 */
export function selectBody(canvasId, bodyIndex) {
    const scene = scenes[canvasId];
    if (!scene) return;

    const bodyMap = perCanvasBodyMap[canvasId];
    if (!bodyMap || bodyMap.size === 0) {
        console.warn(`[BabylonViewer] No body map found for canvas ${canvasId}`);
        return;
    }

    // Deselecting: restore all bodies to colored state
    if (bodyIndex === null) {
        clearBodySelection(canvasId);
        return;
    }

    // Check if clicking the same body that's already selected → deselect all
    const currentlySelected = selectedBodyIndices[canvasId];
    if (bodyIndex === currentlySelected) {
        debugLog(`[BabylonViewer] Deselecting body ${bodyIndex} (same body clicked)`);
        clearBodySelection(canvasId);
        selectedBodyIndices[canvasId] = null;
        return;
    }

    // Selecting a different body: highlight one body, make others transparent
    selectedBodyIndices[canvasId] = bodyIndex;
    const xrayMaterial = getOrCreateBodySelectionXrayMaterial(scene);

    // Remove existing highlight layer
    const existingHighlight = scene.getHighlightLayerByName('sel');
    if (existingHighlight) existingHighlight.dispose();

    bodyMap.forEach((bodyData, idx) => {
        const isSelected = (idx === bodyIndex);

        bodyData.meshes.forEach(mesh => {
            if (isSelected) {
                // Fade from transparent (if currently x-ray) to opaque
                const currentAlpha = mesh.material?.alpha || 1.0;
                mesh.material = bodyData.colorMaterial;
                // Animate from current alpha to full opacity
                if (currentAlpha < 1.0) {
                    animateMaterialAlpha(mesh.material, currentAlpha, 1.0, scene, 200);
                }
                mesh.renderOutline = false;
                mesh.outlineWidth = 0;
            } else {
                // Apply x-ray material and animate to transparent ONLY if not already transparent
                // This prevents the "solid → transparent → solid" flicker when switching between bodies
                const currentAlpha = mesh.material?.alpha || 1.0;
                mesh.material = xrayMaterial;
                if (currentAlpha > 0.2) {  // Only animate if currently opaque or semi-opaque (>20%)
                    animateMaterialAlpha(mesh.material, currentAlpha, 0.15, scene, 200);
                } else {
                    // Already transparent — just set the target alpha directly, no animation
                    mesh.material.alpha = 0.15;
                }
                mesh.renderOutline = false;
            }
        });
    });

    debugLog(`[BabylonViewer] Selected body ${bodyIndex}`);
}

/**
 * Enables click-to-select functionality for bodies in the viewer.
 * @param {string} canvasId
 * @param {object} dotNetRef - Blazor component reference for callback
 */
export function enableBodyPicking(canvasId, dotNetRef) {
    const scene = scenes[canvasId];
    if (!scene) return;

    const bodyMap = perCanvasBodyMap[canvasId];
    if (!bodyMap || bodyMap.size === 0) {
        console.warn(`[BabylonViewer] No body map found for canvas ${canvasId} - picking disabled`);
        return;
    }

    // Remove existing pointer observer to avoid duplicates
    if (scene.bodyPickObserver) {
        scene.onPointerObservable.remove(scene.bodyPickObserver);
        delete scene.bodyPickObserver;
    }

    // onPointerObservable is an Observable — must use .add() to register a handler
    scene.bodyPickObserver = scene.onPointerObservable.add((pointerInfo) => {
        if (pointerInfo.type === BABYLON.PointerEventTypes.POINTERDOWN) {
            if (pointerInfo.pickInfo.hit && pointerInfo.pickInfo.pickedMesh) {
                const pickedMesh = pointerInfo.pickInfo.pickedMesh;

                // Walk up the node hierarchy, checking at each level whether the node
                // is one of the body root nodes. This handles any nesting depth.
                let foundIdx = null;
                let node = pickedMesh;
                while (node && foundIdx === null) {
                    bodyMap.forEach((bodyData, idx) => {
                        if (bodyData.rootNode === node) foundIdx = idx;
                    });
                    node = node.parent;
                }

                if (foundIdx !== null) {
                    dotNetRef?.invokeMethodAsync('NotifyBodyPicked', foundIdx);
                    debugLog(`[BabylonViewer] Picked body ${foundIdx}`);
                }
            } else {
                // Clicked empty space - clear selection
                dotNetRef?.invokeMethodAsync('NotifyBodyPicked', null);
                debugLog(`[BabylonViewer] Cleared body selection (clicked empty space)`);
            }
        }
    });

    debugLog(`[BabylonViewer] Body picking enabled for canvas ${canvasId} (${bodyMap.size} bodies)`);
}

/**
 * Clears body selection, restoring all bodies to their colored state.
 */
export function clearBodySelection(canvasId) {
    const scene = scenes[canvasId];
    if (!scene) return;

    const bodyMap = perCanvasBodyMap[canvasId];
    if (!bodyMap || bodyMap.size === 0) return;

    // Restore each body to its shared colored material (no clone needed — same instance for all meshes in a body)
    bodyMap.forEach((bodyData) => {
        if (bodyData.colorMaterial) {
            bodyData.meshes.forEach(mesh => {
                const currentAlpha = mesh.material?.alpha || 0.15;
                mesh.material = bodyData.colorMaterial;
                // Animate from transparent to opaque
                animateMaterialAlpha(mesh.material, currentAlpha, 1.0, scene, 200);
                mesh.renderOutline = false;
                mesh.outlineWidth = 0;
            });
        }
    });

    // Dispose the highlight layer
    const hl = scene.getHighlightLayerByName('sel');
    if (hl) {
        hl.dispose();
    }

    // Reset selected body tracking
    selectedBodyIndices[canvasId] = null;

    debugLog(`[BabylonViewer] Body selection cleared for canvas ${canvasId}`);
}

/**
 * Enables or disables flipped triangle visualization using custom GLSL shaders.
 * Front-facing triangles render in CAD grey, back-facing (flipped) triangles render in red.
 * @param {string} canvasId - Canvas identifier
 * @param {boolean} enabled - true to enable flipped triangle view, false to restore original materials
 */
export function enableFlippedTriangleView(canvasId, enabled) {
    const scene = scenes[canvasId];
    if (!scene) return;

    const tag = '__flipped_overlay__';

    // Always clean up existing overlay meshes first
    scene.meshes.slice().filter(m => m.name.startsWith(tag)).forEach(m => {
        m.material?.dispose();
        m.dispose();
    });
    delete flippedTriangleMaterials[canvasId];

    if (!enabled) {
        debugLog(`[BabylonViewer] Flipped triangle view disabled for canvas ${canvasId}`);
        return;
    }

    // Register simple overlay shaders (discard front faces, paint back faces red)
    if (!BABYLON.Effect.ShadersStore['flippedOverlayVertexShader']) {
        BABYLON.Effect.ShadersStore['flippedOverlayVertexShader'] = `
            precision highp float;
            attribute vec3 position;
            uniform mat4 worldViewProjection;
            void main() { gl_Position = worldViewProjection * vec4(position, 1.0); }
        `;
        BABYLON.Effect.ShadersStore['flippedOverlayFragmentShader'] = `
            precision highp float;
            uniform vec3 flippedColor;
            void main() {
                if (gl_FrontFacing) discard;
                gl_FragColor = vec4(flippedColor, 1.0);
            }
        `;
    }

    const flippedColor = toColor3(CONFIG.FLIPPED_TRIANGLES.flippedColor);
    flippedTriangleMaterials[canvasId] = {};

    scene.meshes.slice().forEach(mesh => {
        if (!mesh.material || isSystemMesh(mesh) || mesh.name === '__root__' || mesh.name.startsWith(tag)) return;

        const overlay = mesh.clone(`${tag}${mesh.uniqueId}`, mesh.parent, true, false);
        if (!overlay) return;
        overlay.isPickable = false;
        overlay.renderingGroupId = mesh.renderingGroupId;
        overlay.alwaysSelectAsActiveMesh = true;

        const sm = new BABYLON.ShaderMaterial(`${tag}mat${mesh.uniqueId}`, scene,
            { vertex: 'flippedOverlay', fragment: 'flippedOverlay' },
            { attributes: ['position'], uniforms: ['worldViewProjection', 'flippedColor'] });
        sm.backFaceCulling = false;
        sm.disableDepthWrite = true;
        sm.setColor3('flippedColor', flippedColor);
        overlay.material = sm;

        flippedTriangleMaterials[canvasId][mesh.uniqueId] = { material: sm, overlay };
    });

    debugLog(`[BabylonViewer] Flipped triangle view enabled for canvas ${canvasId}`);
}

/**
 * Shared picking predicate: true for user-visible model meshes only.
 * Excludes system meshes, __root__, and all analysis-tool helper meshes.
 */
function isMeasurablePredicate(mesh) {
    return mesh
        && isModelMeshForAnalysis(mesh)
        && mesh.isPickable
        && (typeof mesh.isEnabled !== 'function' || mesh.isEnabled())
        && typeof mesh.getTotalVertices === 'function'
        && mesh.getTotalVertices() > 0;
}

/**
 * Picks a point on the mesh at screen coordinates, ensuring ALL faces are tested
 * (front and back facing). Temporarily disables backFaceCulling on model meshes
 * so inside-out or mixed-winding geometry is still pickable.
 */
function pickMeshPoint(scene, x, y, canvasId = null) {
    // Temporarily disable backFaceCulling on all model meshes
    const restore = [];
    scene.meshes.forEach(m => {
        if (isMeasurablePredicate(m) && m.material && m.material.backFaceCulling) {
            restore.push(m);
            m.material.backFaceCulling = false;
        }
    });
    const result = scene.pick(x, y, isMeasurablePredicate);
    // Restore original setting
    restore.forEach(m => { m.material.backFaceCulling = true; });
    return isPickProjectedNearPointer(canvasId, scene, result, x, y) ? result : { hit: false };
}

function withBackFaceCullingDisabled(scene, action) {
    const restore = [];
    scene.meshes.forEach(m => {
        if (isMeasurablePredicate(m) && m.material && m.material.backFaceCulling) {
            restore.push(m);
            m.material.backFaceCulling = false;
        }
    });
    try {
        return action();
    } finally {
        restore.forEach(m => { m.material.backFaceCulling = true; });
    }
}

function vectorFromFeatureValue(value) {
    if (!value) return null;
    if (value instanceof BABYLON.Vector3) return value.clone();
    const x = Number(value.x ?? value.X);
    const y = Number(value.y ?? value.Y);
    const z = Number(value.z ?? value.Z);
    if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(z)) return null;
    return new BABYLON.Vector3(x, y, z);
}

function getExplicitRoundFeature(pickResult) {
    const metadata = pickResult?.pickedMesh?.metadata ?? {};
    const candidates = [
        metadata.malievRoundFeature,
        metadata.roundFeature,
        metadata.malievFeature,
        metadata.feature,
    ].filter(Boolean);

    if (Array.isArray(metadata.malievFeatures)) candidates.push(...metadata.malievFeatures);
    if (Array.isArray(metadata.features)) candidates.push(...metadata.features);

    return candidates.find(feature => {
        const type = String(feature.kind ?? feature.type ?? feature.featureType ?? '').toLowerCase();
        return type === 'round' || type === 'cylinder' || type === 'cylindrical' || type === 'bore' || type === 'diameter';
    }) ?? null;
}

function inferRoundFeatureFromPick(pickResult) {
    const mesh = pickResult?.pickedMesh;
    if (!mesh) return null;

    const feature = getExplicitRoundFeature(pickResult);
    if (!feature) return null;

    const center = vectorFromFeatureValue(feature.center ?? feature.anchor ?? feature.axisPoint ?? feature.point)
        ?? pickResult.pickedPoint?.clone();
    const axisVector = vectorFromFeatureValue(feature.axis ?? feature.axisVector ?? feature.normal)
        ?? new BABYLON.Vector3(0, 0, 1);
    const diameter = Number(feature.diameter ?? feature.Diameter);
    const radius = Number(feature.radius ?? feature.Radius);
    const resolvedRadius = Number.isFinite(radius) && radius > 0
        ? radius
        : Number.isFinite(diameter) && diameter > 0
            ? diameter / 2
            : null;

    if (!center || !resolvedRadius) return null;

    return {
        kind: 'round',
        point: pickResult.pickedPoint?.clone() ?? center.clone(),
        anchor: center,
        axis: axisVector,
        radius: resolvedRadius,
        diameter: resolvedRadius * 2,
        label: 'Diameter',
    };
}

function pickCadFeature(scene, x, y, canvasId = null) {
    const pickResult = pickMeshPoint(scene, x, y, canvasId);
    if (!pickResult?.hit || !pickResult.pickedPoint || !pickResult.pickedMesh) return null;

    const normal = pickResult.getNormal(true, false) || new BABYLON.Vector3(0, 0, 1);
    const roundFeature = inferRoundFeatureFromPick(pickResult);
    if (roundFeature) return roundFeature;

    return {
        kind: 'face',
        point: pickResult.pickedPoint.clone(),
        anchor: pickResult.pickedPoint.clone(),
        normal: normal.clone(),
        label: 'Face',
    };
}

function createRoundFeatureHighlight(scene, feature) {
    if (!feature || feature.kind !== 'round') return null;

    const axis = feature.axis.clone().normalize();
    const helper = Math.abs(axis.z) < 0.9 ? new BABYLON.Vector3(0, 0, 1) : new BABYLON.Vector3(0, 1, 0);
    const u = BABYLON.Vector3.Cross(axis, helper).normalize();
    const v = BABYLON.Vector3.Cross(axis, u).normalize();
    const points = [];
    const segments = 96;
    for (let i = 0; i <= segments; i += 1) {
        const a = (Math.PI * 2 * i) / segments;
        points.push(feature.anchor
            .add(u.scale(Math.cos(a) * feature.radius))
            .add(v.scale(Math.sin(a) * feature.radius)));
    }

    const line = BABYLON.MeshBuilder.CreateLines('measure_round_highlight', { points }, scene);
    line.color = new BABYLON.Color3(1, 0.22, 0.68);
    return markAnalysisHelperMesh(line);
}

function pickOppositeThicknessHit(scene, entryPoint, normal, entryMesh, entryFaceId) {
    if (!normal) return null;

    return withBackFaceCullingDisabled(scene, () => {
        const candidates = [];
        for (const dir of [normal.scale(-1), normal]) {
            if (dir.length() < 1e-6) continue;
            dir.normalize();
            const ray = new BABYLON.Ray(
                entryPoint.add(dir.scale(0.15)),
                dir,
                CONFIG.THICKNESS.maxRayDistance
            );
            const hits = scene.multiPickWithRay
                ? (scene.multiPickWithRay(ray, isMeasurablePredicate) || [])
                : [scene.pickWithRay(ray, isMeasurablePredicate)].filter(Boolean);

            hits.forEach(hit => {
                if (!hit?.hit || !hit.pickedPoint) return;
                const distance = BABYLON.Vector3.Distance(entryPoint, hit.pickedPoint);
                if (distance < 0.25) return;
                if (hit.pickedMesh === entryMesh && hit.faceId === entryFaceId) return;

                let normalScore = 0;
                try {
                    const hitNormal = hit.getNormal(true, false);
                    if (hitNormal) normalScore = -BABYLON.Vector3.Dot(normal.clone().normalize(), hitNormal.normalize());
                } catch (_) {
                    normalScore = 0;
                }
                candidates.push({ hit, distance, normalScore });
            });
        }

        if (candidates.length === 0) return null;
        candidates.sort((a, b) => {
            const aOpposed = a.normalScore > 0.15 ? 0 : 1;
            const bOpposed = b.normalScore > 0.15 ? 0 : 1;
            return aOpposed - bOpposed || a.distance - b.distance;
        });
        return candidates[0].hit;
    });
}

/**
 * Enables the measure tool for point-to-point distance and angle measurement.
 * @param {string} canvasId - Canvas identifier
 * @param {object} dotNetRef - DotNetObjectReference for callbacks
 */
export function enableMeasureTool(canvasId, dotNetRef) {
    const scene = scenes[canvasId];
    if (!scene) return;

    // Disable if already active
    disableMeasureTool(canvasId);

    measureStates[canvasId] = {
        active: true,
        pointA: null,
        pointB: null,
        featureA: null,
        featureB: null,
        normalA: null,
        normalB: null,
        lines: [],
        labels: [],
        observer: null,
        hoverDot: null,
        hoverFeatureHighlight: null,
        cursorDots: [],
        _downX: null,
        _downY: null,
    };

    const state = measureStates[canvasId];
    const canvas = document.getElementById(canvasId);
    if (!canvas) return;

    ensureModelMeshesTagged(canvasId, scene);
    setAnalysisNavigationLock(canvasId, true);
    canvas.style.cursor = 'crosshair';

    function makeUnpickable(mesh) { markAnalysisHelperMesh(mesh); }

    function createHoverDot(point) {
        if (state.hoverDot) { try { state.hoverDot.dispose(); } catch (_) {} }
        if (state.hoverFeatureHighlight) { try { state.hoverFeatureHighlight.dispose(); } catch (_) {} state.hoverFeatureHighlight = null; }
        const dot = BABYLON.MeshBuilder.CreateSphere('measure_hover_dot', { diameter: 0.8 }, scene);
        dot.position = point.clone();
        const mat = new BABYLON.StandardMaterial('measure_hover_dot_mat', scene);
        mat.diffuseColor = new BABYLON.Color3(1, 0.2, 0.2);
        mat.emissiveColor = new BABYLON.Color3(1, 0.3, 0.3);
        mat.disableLighting = true;
        dot.material = mat;
        makeUnpickable(dot);
        state.hoverDot = dot;
    }

    function showDiameterLabel(feature) {
        if (feature.kind !== 'round') return;
        const labelDiv = document.createElement('div');
        labelDiv.className = 'measure-label';
        labelDiv.style.cssText = `
            position: fixed; transform: translate(-50%, -50%);
            background: rgba(0, 0, 0, 0.85); color: #ff4fb3;
            padding: 6px 10px; border-radius: 4px;
            font-family: 'Segoe UI', sans-serif; font-size: 13px; font-weight: 600;
            pointer-events: none; white-space: nowrap; z-index: 1000;
            border: 1px solid #ff4fb3;
        `;
        labelDiv.innerHTML = `Ø ${feature.diameter.toFixed(2)} mm`;
        document.body.appendChild(labelDiv);
        state.labels.push({ div: labelDiv, worldPos: feature.anchor.clone() });
    }

    function createCursorDot(point) {
        const dot = BABYLON.MeshBuilder.CreateSphere('measure_cursor_dot', { diameter: 0.6 }, scene);
        dot.position = point.clone();
        const mat = new BABYLON.StandardMaterial('measure_cursor_dot_mat', scene);
        mat.diffuseColor = new BABYLON.Color3(1, 0, 0);
        mat.emissiveColor = new BABYLON.Color3(1, 0, 0);
        mat.disableLighting = true;
        dot.material = mat;
        makeUnpickable(dot);
        state.cursorDots.push(dot);
    }

    function clearMeasureHelpers() {
        state.lines.forEach(m => { try { m.dispose(); } catch (_) {} });
        state.labels.forEach(({ div }) => { try { div.remove(); } catch (_) {} });
        state.cursorDots.forEach(m => { try { m.dispose(); } catch (_) {} });
        state.lines = [];
        state.labels = [];
        state.cursorDots = [];
    }

    state.observer = scene.onPointerObservable.add((pointerInfo) => {
        if (!measureStates[canvasId]?.active) return;
        const coords = getPointerInfoRenderCoordinates(canvasId, scene, pointerInfo);

        switch (pointerInfo.type) {
            case BABYLON.PointerEventTypes.POINTERDOWN: {
                if (!coords) break;
                state._downX = coords.x;
                state._downY = coords.y;
                break;
            }

            case BABYLON.PointerEventTypes.POINTERUP: {
                if (!coords) break;
                // Only count as a click if pointer didn't move much (< 5px = camera drag)
                const dx = coords.x - (state._downX ?? coords.x);
                const dy = coords.y - (state._downY ?? coords.y);
                if (dx * dx + dy * dy > 25) { state._downX = null; state._downY = null; break; }
                state._downX = null; state._downY = null;

                const pickResult = pickMeshPoint(scene, coords.x, coords.y, canvasId);
                const feature = pickCadFeature(scene, coords.x, coords.y, canvasId);
                if (!pickResult?.hit || !pickResult.pickedMesh || !feature) return;

                const pickedPoint = feature.anchor ?? pickResult.pickedPoint;
                const normal = feature.normal ?? pickResult.getNormal(true) ?? feature.axis;

                if (!state.pointA) {
                    state.pointA = pickedPoint.clone();
                    state.featureA = feature;
                    state.normalA = normal?.clone() || new BABYLON.Vector3(0, 0, 1);

                    const markerA = BABYLON.MeshBuilder.CreateSphere('measure_A', { diameter: CONFIG.MEASURE.endpointSize }, scene);
                    markerA.position = state.pointA.clone();
                    const matA = new BABYLON.StandardMaterial('measure_A_mat', scene);
                    matA.diffuseColor = toColor3(CONFIG.MEASURE.lineColor);
                    matA.emissiveColor = toColor3(CONFIG.MEASURE.lineColor);
                    markerA.material = matA;
                    makeUnpickable(markerA);
                    state.lines.push(markerA);
                    createCursorDot(pickedPoint);
                    const roundHighlight = createRoundFeatureHighlight(scene, feature);
                    if (roundHighlight) state.lines.push(roundHighlight);
                    showDiameterLabel(feature);

                } else if (!state.pointB) {
                    state.pointB = pickedPoint.clone();
                    state.featureB = feature;
                    state.normalB = normal?.clone() || new BABYLON.Vector3(0, 0, 1);

                    const markerB = BABYLON.MeshBuilder.CreateSphere('measure_B', { diameter: CONFIG.MEASURE.endpointSize }, scene);
                    markerB.position = state.pointB.clone();
                    const matB = new BABYLON.StandardMaterial('measure_B_mat', scene);
                    matB.diffuseColor = toColor3(CONFIG.MEASURE.lineColor);
                    matB.emissiveColor = toColor3(CONFIG.MEASURE.lineColor);
                    markerB.material = matB;
                    makeUnpickable(markerB);
                    state.lines.push(markerB);

                    const line = BABYLON.MeshBuilder.CreateLines('measure_line', {
                        points: [state.pointA, state.pointB]
                    }, scene);
                    line.color = toColor3(CONFIG.MEASURE.lineColor);
                    makeUnpickable(line);
                    state.lines.push(line);

                    const direction = state.pointB.subtract(state.pointA).normalize();
                    const arrowSize = 0.8;

                    const coneA = BABYLON.MeshBuilder.CreateCylinder('measure_arrowA', {
                        diameterTop: 0, diameterBottom: arrowSize, height: arrowSize * 1.5, tessellation: 12
                    }, scene);
                    coneA.position = state.pointA.add(direction.scale(arrowSize * 0.75));
                    coneA.rotationQuaternion = BABYLON.Quaternion.RotationAxis(
                        BABYLON.Vector3.Cross(new BABYLON.Vector3(0, 1, 0), direction),
                        Math.acos(Math.max(-1, Math.min(1, BABYLON.Vector3.Dot(new BABYLON.Vector3(0, 1, 0), direction))))
                    );
                    const matArrowA = new BABYLON.StandardMaterial('measure_arrowA_mat', scene);
                    matArrowA.diffuseColor = toColor3(CONFIG.MEASURE.lineColor);
                    matArrowA.emissiveColor = toColor3(CONFIG.MEASURE.lineColor);
                    coneA.material = matArrowA;
                    makeUnpickable(coneA);
                    state.lines.push(coneA);

                    const coneB = BABYLON.MeshBuilder.CreateCylinder('measure_arrowB', {
                        diameterTop: 0, diameterBottom: arrowSize, height: arrowSize * 1.5, tessellation: 12
                    }, scene);
                    coneB.position = state.pointB.subtract(direction.scale(arrowSize * 0.75));
                    coneB.rotationQuaternion = BABYLON.Quaternion.RotationAxis(
                        BABYLON.Vector3.Cross(new BABYLON.Vector3(0, 1, 0), direction.scale(-1).normalize()),
                        Math.acos(Math.max(-1, Math.min(1, BABYLON.Vector3.Dot(new BABYLON.Vector3(0, 1, 0), direction.scale(-1)))))
                    );
                    const matArrowB = new BABYLON.StandardMaterial('measure_arrowB_mat', scene);
                    matArrowB.diffuseColor = toColor3(CONFIG.MEASURE.lineColor);
                    matArrowB.emissiveColor = toColor3(CONFIG.MEASURE.lineColor);
                    coneB.material = matArrowB;
                    makeUnpickable(coneB);
                    state.lines.push(coneB);

                    const distance = BABYLON.Vector3.Distance(state.pointA, state.pointB);
                    const dot = BABYLON.Vector3.Dot(state.normalA.normalize(), state.normalB.normalize());
                    const angleRad = Math.acos(Math.max(-1, Math.min(1, dot)));
                    const angleDeg = angleRad * (180 / Math.PI);

                    const midPoint = BABYLON.Vector3.Center(state.pointA, state.pointB);
                    const labelDiv = document.createElement('div');
                    labelDiv.className = 'measure-label';
                    labelDiv.style.cssText = `
                        position: fixed; transform: translate(-50%, -50%);
                        background: rgba(0, 0, 0, 0.85); color: #ffd700;
                        padding: 6px 10px; border-radius: 4px;
                        font-family: 'Segoe UI', sans-serif; font-size: 13px; font-weight: 600;
                        pointer-events: none; white-space: nowrap; z-index: 1000;
                        border: 1px solid #ffd700;
                    `;
                    const diameterNotes = [state.featureA, state.featureB]
                        .filter(f => f?.kind === 'round')
                        .map(f => `Ø ${f.diameter.toFixed(2)} mm`);
                    const diameterHtml = diameterNotes.length > 0
                        ? `<br><span style="font-size: 11px; opacity: 0.9;">${diameterNotes.join(' · ')}</span>`
                        : '';
                    labelDiv.innerHTML = `${distance.toFixed(2)} mm${diameterHtml}<br><span style="font-size: 11px; opacity: 0.8;">∠ ${angleDeg.toFixed(1)}°</span>`;
                    document.body.appendChild(labelDiv);
                    state.labels.push({ div: labelDiv, worldPos: midPoint });

                    createCursorDot(pickedPoint);

                    if (dotNetRef) {
                        try { dotNetRef.invokeMethodAsync('NotifyMeasureResult', distance.toFixed(2), angleDeg.toFixed(1)); }
                        catch (e) { console.warn('[BabylonViewer] Failed to notify measure result:', e); }
                    }
                } else {
                    clearMeasureHelpers();
                    state.pointA = pickedPoint.clone();
                    state.pointB = null;
                    state.featureA = feature;
                    state.featureB = null;
                    state.normalA = normal?.clone() || new BABYLON.Vector3(0, 0, 1);
                    state.normalB = null;

                    const markerA = BABYLON.MeshBuilder.CreateSphere('measure_A', { diameter: CONFIG.MEASURE.endpointSize }, scene);
                    markerA.position = state.pointA.clone();
                    const matA = new BABYLON.StandardMaterial('measure_A_mat', scene);
                    matA.diffuseColor = toColor3(CONFIG.MEASURE.lineColor);
                    matA.emissiveColor = toColor3(CONFIG.MEASURE.lineColor);
                    markerA.material = matA;
                    makeUnpickable(markerA);
                    state.lines.push(markerA);
                    createCursorDot(pickedPoint);
                    const roundHighlight = createRoundFeatureHighlight(scene, feature);
                    if (roundHighlight) state.lines.push(roundHighlight);
                    showDiameterLabel(feature);
                }
                break;
            }

            case BABYLON.PointerEventTypes.POINTERMOVE: {
                if (!coords) break;
                const hoverFeature = pickCadFeature(scene, coords.x, coords.y, canvasId);

                // Update hover dot position (face-precise feedback)
                if (hoverFeature) {
                    createHoverDot(hoverFeature.point ?? hoverFeature.anchor);
                    state.hoverFeatureHighlight = createRoundFeatureHighlight(scene, hoverFeature);
                } else if (state.hoverDot) {
                    try { state.hoverDot.dispose(); } catch (_) {}
                    state.hoverDot = null;
                    if (state.hoverFeatureHighlight) { try { state.hoverFeatureHighlight.dispose(); } catch (_) {} state.hoverFeatureHighlight = null; }
                }

                // Preview line from A to cursor (only while waiting for second click)
                if (state.pointA && !state.pointB && hoverFeature) {
                    const prevPreview = state.lines.find(l => l.name === 'measure_preview');
                    if (prevPreview) {
                        prevPreview.dispose();
                        state.lines = state.lines.filter(l => l !== prevPreview);
                    }

                    const previewLine = BABYLON.MeshBuilder.CreateLines('measure_preview', {
                        points: [state.pointA, hoverFeature.anchor],
                        updatable: true
                    }, scene);
                    previewLine.color = toColor3({ r: 1.0, g: 0.85, b: 0.0, a: 0.5 });
                    previewLine.alpha = 0.5;
                    makeUnpickable(previewLine);
                    state.lines.push(previewLine);
                }
                break;
            }
        }
    });

    const labelUpdateObserver = scene.onBeforeRenderObservable.add(() => {
        state.labels.forEach(({ div, worldPos }) => {
            updateLabelPosition(div, worldPos, canvasId);
        });
    });
    state.labelObserver = labelUpdateObserver;

    debugLog(`[BabylonViewer] Measure tool enabled for canvas ${canvasId}`);
}

/**
 * Disables the measure tool and cleans up resources.
 * @param {string} canvasId - Canvas identifier
 */
export function disableMeasureTool(canvasId) {
    const state = measureStates[canvasId];
    if (!state) return;

    const scene = scenes[canvasId];
    const canvas = document.getElementById(canvasId);

    // Remove observers
    if (state.observer && scene) {
        scene.onPointerObservable.remove(state.observer);
    }
    if (state.labelObserver && scene) {
        scene.onBeforeRenderObservable.remove(state.labelObserver);
    }

    // Dispose hover dot and cursor dots
    if (state.hoverDot) { try { state.hoverDot.dispose(); } catch (_) {} }
    if (state.hoverFeatureHighlight) { try { state.hoverFeatureHighlight.dispose(); } catch (_) {} }
    state.cursorDots?.forEach(mesh => { try { mesh.dispose(); } catch (_) {} });

    // Dispose lines and meshes
    state.lines.forEach(mesh => { try { mesh.dispose(); } catch (_) {} });

    // Remove labels
    state.labels.forEach(({ div }) => { try { div.remove(); } catch (_) {} });

    // Reset cursor
    if (canvas) canvas.style.cursor = 'default';

    delete measureStates[canvasId];
    setAnalysisNavigationLock(canvasId, false);
    debugLog(`[BabylonViewer] Measure tool disabled for canvas ${canvasId}`);
}

/**
 * Enables thickness analysis - mouse-over shows wall thickness with color-coded indicator.
 * @param {string} canvasId - Canvas identifier
 */
export function enableThicknessAnalysis(canvasId) {
    const scene = scenes[canvasId];
    if (!scene) return;

    // Disable if already active
    disableThicknessAnalysis(canvasId);

    thicknessStates[canvasId] = {
        active: true,
        line: null,
        label: null,
        sphere: null,
        observer: null,
        pinnedLabels: [],
        lastThickness: null,
        lastPickPoint: null,
        hoverDot: null,
    };

    const state = thicknessStates[canvasId];
    const canvas = document.getElementById(canvasId);
    if (!canvas) return;

    ensureModelMeshesTagged(canvasId, scene);
    setAnalysisNavigationLock(canvasId, true);

    // Set cursor to crosshair
    canvas.style.cursor = 'crosshair';

    // Create label for thickness display
    const labelDiv = document.createElement('div');
    labelDiv.className = 'thickness-label';
    labelDiv.style.cssText = `
        position: fixed;
        transform: translate(-50%, -50%);
        background: rgba(0, 0, 0, 0.85);
        color: #fff;
        padding: 6px 10px;
        border-radius: 4px;
        font-family: 'Segoe UI', sans-serif;
        font-size: 13px;
        font-weight: 600;
        pointer-events: none;
        white-space: nowrap;
        z-index: 1000;
        display: none;
    `;
    document.body.appendChild(labelDiv);
    state.label = labelDiv;

    state.observer = scene.onPointerObservable.add((pointerInfo) => {
        if (!thicknessStates[canvasId]?.active) return;
        const coords = getPointerInfoRenderCoordinates(canvasId, scene, pointerInfo);

        if (pointerInfo.type === BABYLON.PointerEventTypes.POINTERDOWN) {
            // Pin the current thickness measurement
            if (state.lastThickness !== null && state.lastPickPoint !== null && state.lastBorderColor) {
                const pinnedDiv = document.createElement('div');
                pinnedDiv.className = 'thickness-pinned-label';
                pinnedDiv.style.cssText = `
                    position: fixed;
                    transform: translate(-50%, -50%);
                    background: rgba(0, 0, 0, 0.85);
                    color: #fff;
                    padding: 6px 10px;
                    border-radius: 4px;
                    font-family: 'Segoe UI', sans-serif;
                    font-size: 13px;
                    font-weight: 600;
                    pointer-events: none;
                    white-space: nowrap;
                    z-index: 1000;
                    border: 1px solid ${state.lastBorderColor};
                `;
                pinnedDiv.innerHTML = `${state.lastThickness.toFixed(2)} mm`;
                document.body.appendChild(pinnedDiv);
                state.pinnedLabels.push({ div: pinnedDiv, worldPos: state.lastPickPoint.clone() });
            }
        }

        if (pointerInfo.type === BABYLON.PointerEventTypes.POINTERMOVE) {
            if (!coords) return;
            const pickResult = pickMeshPoint(scene, coords.x, coords.y, canvasId);

            // Clear previous hover dot
            if (state.hoverDot) { try { state.hoverDot.dispose(); } catch (_) {} state.hoverDot = null; }

            // Clear previous visualization
            if (state.line) { try { state.line.dispose(); } catch (_) {} state.line = null; }
            if (state.sphere) { try { state.sphere.dispose(); } catch (_) {} state.sphere = null; }
            state.label.style.display = 'none';
            state.lastThickness = null;
            state.lastPickPoint = null;

            if (pickResult?.hit && pickResult.pickedPoint && pickResult.pickedMesh) {
                const normal = pickResult.getNormal(true, false);
                const cam = scene.activeCamera;
                if (!state._lastDiagLog || Date.now() - state._lastDiagLog > 2000) {
                    state._lastDiagLog = Date.now();
                    const m = pickResult.pickedMesh;
                    const bb = m.getBoundingInfo().boundingBox;
                    debugLog('[Thickness DIAG]', {
                        mesh: m.name,
                        faceId: pickResult.faceId,
                        pt: [+pickResult.pickedPoint.x.toFixed(1), +pickResult.pickedPoint.y.toFixed(1), +pickResult.pickedPoint.z.toFixed(1)],
                        normal: normal && [+normal.x.toFixed(2), +normal.y.toFixed(2), +normal.z.toFixed(2)],
                        camPos: cam && [+cam.position.x.toFixed(1), +cam.position.y.toFixed(1), +cam.position.z.toFixed(1)],
                        bbMin: [+bb.minimumWorld.x.toFixed(1), +bb.minimumWorld.y.toFixed(1), +bb.minimumWorld.z.toFixed(1)],
                        bbMax: [+bb.maximumWorld.x.toFixed(1), +bb.maximumWorld.y.toFixed(1), +bb.maximumWorld.z.toFixed(1)],
                        indices: m.getTotalIndices(),
                        backFaceCulling: m.material?.backFaceCulling,
                    });
                }

                // Red hover dot at pick point (face-precise feedback)
                const dot = BABYLON.MeshBuilder.CreateSphere('thickness_hover_dot', { diameter: 0.8 }, scene);
                dot.position = pickResult.pickedPoint.clone();
                const dotMat = new BABYLON.StandardMaterial('thickness_hover_dot_mat', scene);
                dotMat.diffuseColor = new BABYLON.Color3(1, 0.2, 0.2);
                dotMat.emissiveColor = new BABYLON.Color3(1, 0.3, 0.3);
                dotMat.disableLighting = true;
                dot.material = dotMat;
                markAnalysisHelperMesh(dot);
                state.hoverDot = dot;

                const entryPoint = pickResult.pickedPoint;
                if (!normal) return;

                const hit = pickOppositeThicknessHit(
                    scene,
                    entryPoint,
                    normal,
                    pickResult.pickedMesh,
                    pickResult.faceId
                );

                if (hit?.hit && hit.pickedPoint) {
                    const thickness = BABYLON.Vector3.Distance(entryPoint, hit.pickedPoint);

                    let color;
                    if (thickness >= CONFIG.THICKNESS.safeThreshold) {
                        color = { r: 0.2, g: 0.8, b: 0.2 };
                    } else if (thickness <= CONFIG.THICKNESS.criticalThreshold) {
                        color = { r: 1.0, g: 0.2, b: 0.2 };
                    } else {
                        color = { r: 1.0, g: 0.8, b: 0.0 };
                    }

                    state.line = BABYLON.MeshBuilder.CreateLines('thickness_line', {
                        points: [entryPoint, hit.pickedPoint]
                    }, scene);
                    state.line.color = toColor3(color);
                    markAnalysisHelperMesh(state.line);

                    state.sphere = BABYLON.MeshBuilder.CreateSphere('thickness_exit', { diameter: 1.0 }, scene);
                    state.sphere.position = hit.pickedPoint.clone();
                    const sphereMat = new BABYLON.StandardMaterial('thickness_exit_mat', scene);
                    sphereMat.diffuseColor = toColor3(color);
                    sphereMat.emissiveColor = toColor3(color);
                    sphereMat.alpha = 0.8;
                    state.sphere.material = sphereMat;
                    markAnalysisHelperMesh(state.sphere);

                    state.lastThickness = thickness;
                    state.lastPickPoint = entryPoint.clone();
                    state.lastBorderColor = `rgb(${color.r * 255}, ${color.g * 255}, ${color.b * 255})`;

                    state.label.innerHTML = `${thickness.toFixed(2)} mm`;
                    state.label.style.borderColor = state.lastBorderColor;
                    state.label.style.display = 'block';
                    updateLabelPosition(state.label, entryPoint, canvasId);
                } else {
                    state.label.innerHTML = 'N/A';
                    state.label.style.borderColor = 'rgb(128, 128, 128)';
                    state.label.style.display = 'block';
                    updateLabelPosition(state.label, entryPoint, canvasId);
                }
            }
        }
    });

    // Add render observer to update pinned label positions
    const labelUpdateObserver = scene.onBeforeRenderObservable.add(() => {
        state.pinnedLabels.forEach(({ div, worldPos }) => {
            updateLabelPosition(div, worldPos, canvasId);
        });
    });
    state.labelObserver = labelUpdateObserver;

    debugLog(`[BabylonViewer] Thickness analysis enabled for canvas ${canvasId}`);
}

/**
 * Disables thickness analysis and cleans up resources.
 * @param {string} canvasId - Canvas identifier
 */
export function disableThicknessAnalysis(canvasId) {
    const state = thicknessStates[canvasId];
    if (!state) return;

    const scene = scenes[canvasId];
    const canvas = document.getElementById(canvasId);

    // Remove observers
    if (state.observer && scene) {
        scene.onPointerObservable.remove(state.observer);
    }
    if (state.labelObserver && scene) {
        scene.onBeforeRenderObservable.remove(state.labelObserver);
    }

    // Dispose hover dot
    if (state.hoverDot) { try { state.hoverDot.dispose(); } catch (_) {} }

    // Dispose line and sphere
    if (state.line) { try { state.line.dispose(); } catch (_) {} }
    if (state.sphere) { try { state.sphere.dispose(); } catch (_) {} }

    // Remove label
    if (state.label) {
        try { state.label.remove(); } catch (_) {}
    }

    // Remove pinned labels
    state.pinnedLabels.forEach(({ div }) => {
        try { div.remove(); } catch (_) {}
    });

    // Reset cursor
    if (canvas) {
        canvas.style.cursor = 'default';
    }

    delete thicknessStates[canvasId];
    setAnalysisNavigationLock(canvasId, false);
    debugLog(`[BabylonViewer] Thickness analysis disabled for canvas ${canvasId}`);
}

/**
 * Call this when the viewer container is shown after being hidden (display:none → visible).
 * Triggers engine resize so the canvas fills its container correctly.
 * @param {string} canvasId
 */
export function notifyViewerVisible(canvasId) {
    const engine = engines[canvasId];
    if (engine) {
        requestAnimationFrame(() => engine.resize());
    }
}

const draggablePanelCleanups = {};

export function enableSectionPanelDrag(panelId) {
    const panel = document.getElementById(panelId);
    if (!panel) return;

    const container = panel.closest?.('.model-viewer-container');
    const handle = panel.querySelector?.('[data-section-drag-handle]');
    if (!container || !handle) return;

    if (draggablePanelCleanups[panelId]) draggablePanelCleanups[panelId]();

    let dragging = false;
    let pointerOffsetX = 0;
    let pointerOffsetY = 0;

    const clampPanel = (event) => {
        const containerRect = container.getBoundingClientRect();
        const panelRect = panel.getBoundingClientRect();
        const maxLeft = Math.max(0, containerRect.width - panelRect.width);
        const maxTop = Math.max(0, containerRect.height - panelRect.height);
        const left = Math.min(Math.max(0, event.clientX - containerRect.left - pointerOffsetX), maxLeft);
        const top = Math.min(Math.max(0, event.clientY - containerRect.top - pointerOffsetY), maxTop);

        panel.style.left = `${left}px`;
        panel.style.top = `${top}px`;
        panel.style.right = 'auto';
        panel.style.bottom = 'auto';
    };

    const onPointerMove = (event) => {
        if (!dragging) return;
        event.preventDefault?.();
        clampPanel(event);
    };

    const onPointerUp = () => {
        dragging = false;
        document.removeEventListener('pointermove', onPointerMove);
        document.removeEventListener('pointerup', onPointerUp);
        document.removeEventListener('pointercancel', onPointerUp);
    };

    const onPointerDown = (event) => {
        if (event.button !== undefined && event.button !== 0) return;
        const panelRect = panel.getBoundingClientRect();
        pointerOffsetX = event.clientX - panelRect.left;
        pointerOffsetY = event.clientY - panelRect.top;
        dragging = true;
        event.preventDefault?.();
        document.addEventListener('pointermove', onPointerMove);
        document.addEventListener('pointerup', onPointerUp);
        document.addEventListener('pointercancel', onPointerUp);
    };

    handle.addEventListener('pointerdown', onPointerDown);
    draggablePanelCleanups[panelId] = () => {
        handle.removeEventListener('pointerdown', onPointerDown);
        document.removeEventListener('pointermove', onPointerMove);
        document.removeEventListener('pointerup', onPointerUp);
        document.removeEventListener('pointercancel', onPointerUp);
    };
}

